        pair = pick(rng, [('Вагон', 'вагоном', 'т', (20, 30, 40, 60)), ('Тележка', 'тележкой', 'кг', (1, 2, 3, 4, 5)),
                          ('Пластилиновый шарик', 'шариком', 'г', (10, 20, 30, 40, 50)), ('Платформа', 'платформой', 'т', (10, 15, 20, 30))])
        m1, m2 = pick(rng, pair[3]), pick(rng, pair[3])
        v1 = pick(rng, [1, 2, 3, 4, 5, 6])
