        v = pick(rng, [4, 5, 6, 8, 10, 12])
        ang, c = pick(rng, [(60, Fr(1, 2)), (0, Fr(1))])
        p = {'kind': kind, 'm': m, 'M': M, 'v': v, 'c': str(c)}
        ans = _solve_collision(p)
