ORBITERS = [('Искусственный спутник Земли', 'спутника'), ('Космический аппарат, обращающийся вокруг Луны,', 'аппарата'),
            ('Исследовательский зонд, обращающийся вокруг Марса,', 'зонда'), ('Орбитальная станция', 'станции')]


def _pm_orbit(rng):
    who, gen = pick(rng, ORBITERS)
    up = rng.random() < 0.5
    how = pick(rng, [('radius', f'был переведён на новую круговую орбиту, радиус которой {"больше" if up else "меньше"} прежнего', None),
                     ('height', f'перешёл на круговую орбиту, высота которой над поверхностью планеты {"больше" if up else "меньше"} прежней', None),
                     ('speed', f'перешёл на другую круговую орбиту, и скорость его движения {"уменьшилась" if up else "увеличилась"}', 'скорость движения по орбите'),
                     ('acc', f'перешёл на другую круговую орбиту, и его центростремительное ускорение {"уменьшилось" if up else "увеличилось"}', 'центростремительное ускорение'),
                     ('period', f'перешёл на другую круговую орбиту, и период его обращения {"увеличился" if up else "уменьшился"}', 'период обращения')])
    text = f'{who} {how[1]}. Как изменятся в результате этого перехода указанные величины?'
    if who == 'Орбитальная станция':
        text = text.replace('был переведён', 'была переведена').replace('перешёл', 'перешла').replace('его движения', 'её движения').replace('его центростремительное', 'её центростремительное').replace('период его', 'период её')
    cands = [n for n in CM6['orbit']['qty'] if n != how[2]]
    base = {'r': 7e6, 'M': 1.0, 'm': 1000.0}
    return 'orbit', text, base, {'r': Fr(3, 2) if up else Fr(2, 3)}, cands, False


