def _pm_osc(rng):
    if rng.random() < 0.6:
        who = pick(rng, ['Груз, подвешенный на лёгкой пружине, совершает свободные вертикальные гармонические колебания.',
                         'Брусок на гладкой горизонтальной поверхности, прикреплённый к пружине, совершает гармонические колебания.',
                         'Шарик на пружине совершает свободные гармонические колебания.'])
        ch = pick(rng, [('m', 'Массу груза увеличили, не меняя амплитуду колебаний', Fr(2)), ('m', 'Массу груза уменьшили, не меняя амплитуду колебаний', Fr(1, 2)),
                        ('k', 'Пружину заменили более жёсткой, амплитуда колебаний прежняя', Fr(2)), ('k', 'Пружину заменили менее жёсткой, амплитуда колебаний прежняя', Fr(1, 2)),
                        ('A', 'Амплитуду колебаний увеличили', Fr(2)), ('A', 'Амплитуду колебаний уменьшили', Fr(1, 2))])
        text = f'{who} {ch[1]}. Как изменятся при этом указанные величины?'
        return 'spring', text, {'m': 0.4, 'k': 40.0, 'A': 0.05}, {ch[0]: ch[2]}, list(CM6['spring']['qty']), False
    who = pick(rng, ['Шарик на длинной лёгкой нити совершает малые свободные колебания.', 'Математический маятник совершает малые свободные колебания.',
                     'Груз нитяного маятника совершает малые колебания.'])
    ch = pick(rng, [('l', 'Длину нити увеличили, угловая амплитуда колебаний прежняя', Fr(2)), ('l', 'Длину нити уменьшили, угловая амплитуда колебаний прежняя', Fr(1, 2)),
                    ('m', 'Груз заменили на более массивный того же размера, угловая амплитуда прежняя', Fr(2)),
                    ('g', 'Маятник перенесли на Луну, угловая амплитуда прежняя', Fr(1, 6))])
    text = f'{who} {ch[1]}. Как изменятся при этом указанные величины?'
    return 'math', text, {'l': 1.0, 'g': 10.0, 'm': 0.1, 'th': 0.1}, {ch[0]: ch[2]}, list(CM6['math']['qty']), False


