def _pm_throw(rng):
    obj = pick(rng, ['Мяч', 'Камень', 'Снежок', 'Шарик'])
    if rng.random() < 0.5:
        ch = pick(rng, [('v', 'с той же высоты, но с большей начальной скоростью', Fr(2)), ('v', 'с той же высоты, но с меньшей начальной скоростью', Fr(1, 2)),
                        ('h', 'с той же начальной скоростью, но с большей высоты', Fr(2)), ('h', 'с той же начальной скоростью, но с меньшей высоты', Fr(1, 2))])
        text = f'{obj} бросают горизонтально с некоторой высоты. Во втором опыте его бросают горизонтально {ch[1]}. Как изменятся во втором опыте указанные величины? Сопротивлением воздуха пренебречь.'
        return 'hthrow', text, {'v': 5.0, 'h': 20.0}, {ch[0]: ch[2]}, list(CM6['hthrow']['qty']), False
    a1, a2 = pick(rng, [(30, 60), (60, 30), (30, 45), (45, 60), (60, 45), (45, 30)])
    cands = list(CM6['athrow']['qty'])
    if rng.random() < 0.5:
        text = f'{obj} бросают с поверхности земли под углом {a1}° к горизонту. Во втором опыте его бросают с той же по модулю начальной скоростью под углом {a2}° к горизонту. Как изменятся во втором опыте указанные величины? Сопротивлением воздуха пренебречь.'
        return 'athrow', text, {'v': 20.0, 'al': float(a1)}, {'al': Fr(a2, a1)}, cands, False
    up = rng.random() < 0.5
    text = f'{obj} бросают с поверхности земли под углом {a1}° к горизонту. Во втором опыте его бросают под тем же углом, но с {"большей" if up else "меньшей"} начальной скоростью. Как изменятся во втором опыте указанные величины? Сопротивлением воздуха пренебречь.'
    return 'athrow', text, {'v': 20.0, 'al': float(a1)}, {'v': Fr(3, 2) if up else Fr(2, 3)}, cands, False


