def g_change_forces(rng):
    return _change_gen('ph-ege-06-change-forces', CM6, rng, _pm_forces)


# --- «как изменяются величины по ходу движения» (настоящее время)

def _q_up():
    return {'модуль ускорения тела': lambda p: G + 0 * p['t'], 'модуль импульса тела': lambda p: abs(p['v0'] - G * p['t']),
            'кинетическая энергия тела': lambda p: (p['v0'] - G * p['t']) ** 2 / 2,
            'потенциальная энергия тела': lambda p: G * (p['v0'] * p['t'] - G * p['t'] ** 2 / 2),
            'полная механическая энергия тела': lambda p: p['v0'] ** 2 / 2 + 0 * p['t']}


def _q_para():
    return {'скорость парашютиста': lambda p: 5 + 0 * p['t'], 'кинетическая энергия парашютиста': lambda p: 12.5 + 0 * p['t'],
            'потенциальная энергия парашютиста': lambda p: G * (1000 - 5 * p['t']), 'полная механическая энергия парашютиста': lambda p: 12.5 + G * (1000 - 5 * p['t'])}


def _q_wave():
    return {'частота волны': lambda p: 500 + 0 * p['v'], 'длина волны': lambda p: p['v'] / 500, 'скорость распространения волны': lambda p: p['v'],
            'период колебаний частиц среды': lambda p: 1 / 500 + 0 * p['v']}


def _q_pend():
    return {'модуль скорости груза': lambda p: math.sqrt(max(0.0, 2 * G * (math.cos(p['th']) - math.cos(0.3)))),
            'потенциальная энергия груза': lambda p: G * (1 - math.cos(p['th'])),
            'кинетическая энергия груза': lambda p: G * (math.cos(p['th']) - math.cos(0.3)),
            'полная механическая энергия груза': lambda p: G * (1 - math.cos(0.3)) + 0 * p['th'],
            'модуль силы натяжения нити': lambda p: 3 * math.cos(p['th']) - 2 * math.cos(0.3)}


CM6E = {'up': {'qty': _q_up()}, 'down': {'qty': _q_up()}, 'para': {'qty': _q_para()}, 'wave': {'qty': _q_wave()}, 'pend': {'qty': _q_pend()}}


def _pm_evolve(rng):
    kind = pick(rng, ['up', 'down', 'para', 'wave', 'pend'])
    if kind in ('up', 'down'):
        obj = pick(rng, ['Мяч', 'Камень', 'Шарик', 'Снежок'])
        if kind == 'up':
            text = f'{obj} бросили вертикально вверх. Как изменяются по мере подъёма {obj.lower()}а указанные величины? Сопротивлением воздуха пренебречь.'
            text = text.replace('Снежока', 'снежка').replace('снежока', 'снежка').replace('камеа', 'камня').replace('каменьа', 'камня')
            return 'up', text, {'v0': 20.0, 't': 0.2}, {'t': Fr(3)}, list(CM6E['up']['qty']), True
        text = f'{obj} свободно падает без начальной скорости. Как изменяются во время падения указанные величины? Сопротивлением воздуха пренебречь.'
        return 'down', text, {'v0': 0.0, 't': 0.5}, {'t': Fr(3)}, [n for n in CM6E['up']['qty']], True
    if kind == 'para':
        text = 'Парашютист спускается вертикально с постоянной скоростью. Как изменяются в процессе спуска указанные величины?'
        return 'para', text, {'t': 10.0}, {'t': Fr(3)}, list(CM6E['para']['qty']), True
    if kind == 'wave':
        a, b = pick(rng, [(('воздуха', 340.0), ('воду', 1500.0)), (('воды', 1500.0), ('воздух', 340.0)), (('воздуха', 340.0), ('стальной рельс', 5000.0))])
        text = f'Звуковая волна от источника, находящегося в среде из {a[0]}, проникает в {b[0]}. Как изменяются указанные величины при переходе волны в новую среду?'.replace('в среде из воздуха', 'в воздухе').replace('в среде из воды', 'в воде')
        return 'wave', text, {'v': a[1]}, {'v': Fr(round(b[1])) / Fr(round(a[1]))}, list(CM6E['wave']['qty']), True
    text = 'Груз нитяного маятника движется от крайнего положения к положению равновесия. Как изменяются при этом указанные величины? Сопротивлением воздуха пренебречь.'
    return 'pend', text, {'th': 0.25}, {'th': Fr(1, 5)}, list(CM6E['pend']['qty']), True


def _solve_evolve(p):
    return _solve_change(CM6E)(p)


@proto('ph-ege-06-evolve', 'ЕГЭ', 6, 'Как изменяются величины по ходу движения: подъём, падение, равномерный спуск, маятник, переход волны',
       invariant='в поле тяжести без сопротивления ускорение постоянно, механическая энергия сохраняется; при равномерном спуске с сопротивлением '
                 'механическая энергия убывает; при переходе волны в другую среду частота сохраняется, λ = υ/ν',
       varies='сюжет (мяч вверх, свободное падение, парашютист, звук из воздуха в воду/сталь и обратно, маятник к положению равновесия), спрашиваемые величины',
       answer_rule='знак изменения величины между двумя моментами процесса',
       mistakes=['ускорение уменьшается при подъёме', 'энергия парашютиста сохраняется', 'частота меняется при переходе в другую среду'],
       solve=_solve_evolve, kes=['1.1.7', '1.4.8', '1.5.4', '1.5.5'],
       fidelity=FID(6, answer_format='две цифры 1/2/3 (увеличивается/уменьшается/не изменяется)', style=MATCH_STYLE.replace('изменятся', 'изменяются'),
                    scale='качественно, как в банке («Мяч подбросили вертикально вверх. Как меняются по мере подъёма …»)',
                    trap='постоянство ускорения и механической энергии; частота при смене среды'))
def g_evolve(rng):
    return _change_gen('ph-ege-06-evolve', CM6E, rng, _pm_evolve)


# --- соответствие «таблица значений (график) ↔ величина»

def _proc_vals(proc, qid, t, P):
    if proc == 'up':
        v0, m = P['v0'], P['m']
        vy = v0 - G * t
        y = v0 * t - G * t * t / 2
        return {'y': y, 'vy': vy, 'ay': Fr(-G), 'Ek': m * vy * vy / 2, 'Ep': m * G * y, 'py': m * vy, 'E': m * v0 * v0 / 2}[qid]
    if proc == 'incl':
        v0, m = P['v0'], P['m']
        a = Fr(G, 2)
        vx = v0 - a * t
        x = v0 * t - a * t * t / 2
        return {'y': x, 'vy': vx, 'ay': -a, 'Ek': m * vx * vx / 2, 'Ep': m * G * x / 2, 'py': m * vx, 'E': m * v0 * v0 / 2}[qid]
    if proc == 'hor':
        v0, m, h = P['v0'], P['m'], P['h']
        vy = -G * t
        return {'x': v0 * t, 'y': h - G * t * t / 2, 'vx': v0, 'vy': vy, 'Ek': m * (v0 * v0 + vy * vy) / 2, 'Ep': m * G * (h - G * t * t / 2), 'px': m * v0, 'py': m * vy}[qid]
    raise ValueError(proc)


PROC_NAMES = {
    'up': {'y': 'координата y мяча, м', 'vy': 'проекция скорости υy, м/с', 'ay': 'проекция ускорения ay, м/с²', 'Ek': 'кинетическая энергия, Дж',
           'Ep': 'потенциальная энергия, Дж', 'py': 'проекция импульса py, кг·м/с', 'E': 'полная механическая энергия, Дж'},
    'incl': {'y': 'координата x шайбы, м', 'vy': 'проекция скорости υx, м/с', 'ay': 'проекция ускорения ax, м/с²', 'Ek': 'кинетическая энергия, Дж',
             'Ep': 'потенциальная энергия, Дж', 'py': 'проекция импульса px, кг·м/с', 'E': 'полная механическая энергия, Дж'},
    'hor': {'x': 'координата x, м', 'y': 'координата y, м', 'vx': 'проекция скорости υx, м/с', 'vy': 'проекция скорости υy, м/с', 'Ek': 'кинетическая энергия, Дж',
            'Ep': 'потенциальная энергия, Дж', 'px': 'проекция импульса px, кг·м/с', 'py': 'проекция импульса py, кг·м/с'},
}


def _solve_table_match(p):
    P = {k: Fr(v) for k, v in p['P'].items()}
    ts = [Fr(t) for t in p['ts']]
    out = {}
    for lab, vals in zip('АБ', p['tables']):
        vals = [Fr(v) for v in vals]
        hits = [rid for rid, qid in p['right'] if [_proc_vals(p['proc'], qid, t, P) for t in ts] == vals]
        if len(hits) != 1:
            raise ValueError(f'таблица {lab}: совпадений {hits}')
        out[lab] = hits[0]
    return out


@proto('ph-ege-06-table-match', 'ЕГЭ', 6, 'Соответствие: таблица значений (график) ↔ физическая величина при движении тела',
       invariant='в поле тяжести: y = υ0t − gt²/2, υy = υ0 − gt, ay = −g; Eк, Eп, p — через скорость и высоту; горизонтальная составляющая скорости постоянна',
       varies='процесс (мяч вверх, шайба вверх по гладкой наклонной плоскости с углом 30°, бросок горизонтально), масса, начальная скорость, высота, '
              'моменты времени; графики банка заменены таблицами значений',
       answer_rule='для каждой таблицы вычислить значения всех предложенных величин в указанные моменты и найти совпадающую',
       mistakes=['кинетическая энергия путается с потенциальной', 'проекция импульса со знаком «+» после верхней точки'],
       solve=_solve_table_match, kes=['1.1.7', '1.4.1', '1.4.6', '1.4.7'],
       fidelity=FID(6, answer_format='две цифры (номер величины для таблиц А и Б)', style='Соответствие «ГРАФИКИ — ФИЗИЧЕСКИЕ ВЕЛИЧИНЫ» как в банке; '
                    'графики заменены таблицами значений в указанные моменты времени (картинок нет)',
                    scale='как в банке: мяч/шайба, υ0 5–20 м/с, масса 0,1–1 кг', trap='форма зависимости (линейная, квадратичная, постоянная), знак проекций'))
def g_table_match(rng):
    proc = pick(rng, ['up', 'incl', 'hor'])
    m = pick(rng, [Fr(1, 10), Fr(1, 5), Fr(1, 2), 1])
    if proc == 'up':
        v0 = pick(rng, [10, 20, 30])
        tt = Fr(2 * v0, G)
        ts = [tt * k / 4 for k in range(5)]
        P = {'v0': Fr(v0), 'm': m}
        text = f'Мяч массой {Q(m)} кг бросили с поверхности земли вертикально вверх с начальной скоростью {v0} м/с (ось Oy направлена вверх, нулевой уровень потенциальной энергии — поверхность земли).'
    elif proc == 'incl':
        v0 = pick(rng, [5, 10, 15])
        tt = Fr(2 * v0 * 2, G)
        ts = [tt * k / 4 for k in range(5)]
        P = {'v0': Fr(v0), 'm': m}
        text = (f'Шайбе массой {Q(m)} кг сообщили начальную скорость {v0} м/с, направленную вверх вдоль гладкой наклонной плоскости с углом наклона 30° (ось Ox направлена вдоль '
                f'плоскости вверх, начало отсчёта и нулевой уровень потенциальной энергии — в точке старта).')
    else:
        v0 = pick(rng, [5, 10, 15, 20])
        h = pick(rng, [20, 45, 80])
        tt = Fr(math.isqrt(2 * h // G))
        ts = [tt * k / 4 for k in range(5)]
        P = {'v0': Fr(v0), 'm': m, 'h': Fr(h)}
        text = f'Камень массой {Q(m)} кг бросили горизонтально с высоты {h} м с начальной скоростью {v0} м/с (ось Ox горизонтальна, ось Oy направлена вверх, начало координат и нулевой уровень потенциальной энергии — на земле под точкой броска).'
    names = PROC_NAMES[proc]
    qids = list(names)
    # отбор: 4 разные величины с различающимися таблицами
    for _ in range(20):
        right = rng.sample(qids, 4)
        tabs = {q: [_proc_vals(proc, q, t, P) for t in ts] for q in right}
        if len({tuple(v) for v in tabs.values()}) == 4 and all(ok_dec(x, 2) for v in tabs.values() for x in v):
            break
    else:
        raise Retry
    left = rng.sample(right, 2)
    rlist = [(str(i + 1), q) for i, q in enumerate(right)]
    ans = {lab: str(right.index(q) + 1) for lab, q in zip('АБ', left)}
    ttab = table([('t, с', ts)] + [(f'{lab})', tabs[q]) for lab, q in zip('АБ', left)])
    q = (text + ' В таблицах А и Б приведены значения двух величин, характеризующих движение, в моменты времени t. Сопротивлением воздуха пренебречь. '
         'Установите соответствие между таблицами и физическими величинами, значения которых в них приведены. К каждой позиции первого столбца подберите соответствующую позицию из второго столбца.\n' + ttab)
    o = match_opts([f'таблица {lab}' for lab in 'АБ'], [names[qq] for qq in right])
    e = '; '.join(f'{lab} — {names[qq]}' for lab, qq in zip('АБ', left)) + '. Ответ: ' + ans['А'] + ans['Б'] + '.'
    p = {'proc': proc, 'P': {k: str(v) for k, v in P.items()}, 'ts': [str(t) for t in ts], 'tables': [[str(x) for x in tabs[qq]] for qq in left], 'right': rlist}
    return pcard('ph-ege-06-table-match', q, ans, e, k='match', o=o, p=p)


# --- соответствие «формула ↔ величина»

FORMULA_SETS = {
    'circle': ('Материальная точка движется равномерно по окружности радиусом R с угловой скоростью ω.', ('R', 'w'),
               [('период обращения', '2π/ω', lambda p: 2 * math.pi / p['w'], lambda p: 2 * math.pi * p['R'] / (p['w'] * p['R'])),
                ('модуль линейной скорости', 'ωR', lambda p: p['w'] * p['R'], lambda p: 2 * math.pi * p['R'] / (2 * math.pi / p['w'])),
                ('модуль центростремительного ускорения', 'ω²R', lambda p: p['w'] ** 2 * p['R'], lambda p: (p['w'] * p['R']) ** 2 / p['R']),
                ('частота обращения', 'ω/(2π)', lambda p: p['w'] / (2 * math.pi), lambda p: 1 / (2 * math.pi / p['w']))],
               ['ω/R', 'ωR²', '2πR/ω']),
    'incline': ('Брусок массой m соскальзывает с шероховатой наклонной плоскости с углом наклона α; коэффициент трения μ.', ('m', 'al', 'mu'),
                [('модуль силы трения', 'μmg·cosα', lambda p: p['mu'] * p['m'] * G * math.cos(p['al']), lambda p: p['mu'] * (p['m'] * G * math.cos(p['al']))),
                 ('модуль силы нормальной реакции опоры', 'mg·cosα', lambda p: p['m'] * G * math.cos(p['al']), lambda p: math.hypot(p['m'] * G, 0) * math.cos(p['al'])),
                 ('модуль ускорения бруска', 'g(sinα − μcosα)', lambda p: G * (math.sin(p['al']) - p['mu'] * math.cos(p['al'])),
                  lambda p: (p['m'] * G * math.sin(p['al']) - p['mu'] * p['m'] * G * math.cos(p['al'])) / p['m']),
                 ('модуль проекции силы тяжести на ось, направленную вдоль плоскости', 'mg·sinα', lambda p: p['m'] * G * math.sin(p['al']),
                  lambda p: p['m'] * G * math.cos(math.pi / 2 - p['al']))],
                ['μmg·sinα', 'g(sinα + μcosα)', 'mg·tgα']),
    'hthrow': ('Камень бросили горизонтально с высоты h с начальной скоростью υ0. Сопротивлением воздуха пренебречь.', ('h', 'v'),
               [('время полёта', '√(2h/g)', lambda p: math.sqrt(2 * p['h'] / G), lambda p: 2 * p['h'] / math.sqrt(2 * G * p['h'])),
                ('дальность полёта', 'υ0√(2h/g)', lambda p: p['v'] * math.sqrt(2 * p['h'] / G), lambda p: p['v'] * 2 * p['h'] / math.sqrt(2 * G * p['h'])),
                ('модуль скорости в момент падения', '√(υ0² + 2gh)', lambda p: math.sqrt(p['v'] ** 2 + 2 * G * p['h']), lambda p: math.hypot(p['v'], math.sqrt(2 * G * p['h']))),
                ('модуль вертикальной составляющей скорости в момент падения', '√(2gh)', lambda p: math.sqrt(2 * G * p['h']), lambda p: G * math.sqrt(2 * p['h'] / G))],
               ['2h/υ0', 'υ0√(h/g)', 'υ0 + √(2gh)']),
    'spring': ('Груз массой m на пружине жёсткостью k совершает гармонические колебания с амплитудой A.', ('m', 'k', 'A'),
               [('период колебаний', '2π√(m/k)', lambda p: 2 * math.pi * math.sqrt(p['m'] / p['k']), lambda p: 2 * math.pi / math.sqrt(p['k'] / p['m'])),
                ('максимальная скорость груза', 'A√(k/m)', lambda p: p['A'] * math.sqrt(p['k'] / p['m']), lambda p: math.sqrt(p['k'] * p['A'] ** 2 / p['m'])),
                ('полная механическая энергия', 'kA²/2', lambda p: p['k'] * p['A'] ** 2 / 2, lambda p: p['m'] * (p['A'] * math.sqrt(p['k'] / p['m'])) ** 2 / 2),
                ('максимальный модуль ускорения груза', 'kA/m', lambda p: p['k'] * p['A'] / p['m'], lambda p: p['A'] * (p['k'] / p['m']))],
               ['2π√(k/m)', 'A√(m/k)', 'mA²/2']),
    'vthrow': ('Тело бросили с поверхности земли вертикально вверх с начальной скоростью υ0. Сопротивлением воздуха пренебречь.', ('v',),
               [('максимальная высота подъёма', 'υ0²/(2g)', lambda p: p['v'] ** 2 / (2 * G), lambda p: (p['v'] / G) * p['v'] / 2),
                ('время подъёма до верхней точки', 'υ0/g', lambda p: p['v'] / G, lambda p: 2 * (p['v'] ** 2 / (2 * G)) / p['v']),
                ('время полёта до падения на землю', '2υ0/g', lambda p: 2 * p['v'] / G, lambda p: 2 * (p['v'] / G)),
                ('модуль скорости на половине максимальной высоты', 'υ0/√2', lambda p: p['v'] / math.sqrt(2), lambda p: math.sqrt(p['v'] ** 2 - 2 * G * p['v'] ** 2 / (4 * G)))],
               ['υ0²/g', 'υ0/(2g)', '2υ0²/g']),
}


def _solve_formula(p, sets=None):
    fs = (sets or FORMULA_SETS)[p['set']]
    rows = {r[0]: r for r in fs[2]}
    wrongs = {w: None for w in fs[3]}
    out = {}
    import random as _r
    rr = _r.Random(7)
    samples = [{k: rr.uniform(0.3, 1.2) if k in ('al', 'mu') else rr.uniform(1, 5) for k in fs[1]} for _ in range(3)]
    for lab, name in zip('АБ', p['left']):
        want = [rows[name][3](s) for s in samples]   # другой способ расчёта величины
        hits = []
        for rid, f in p['right']:
            if f in wrongs:
                continue
            row = next(r for r in fs[2] if r[1] == f)
            got = [row[2](s) for s in samples]
            if all(math.isclose(a, b, rel_tol=1e-9) for a, b in zip(want, got)):
                hits.append(rid)
        if len(hits) != 1:
            raise ValueError(f'{name}: совпадений {hits}')
        out[lab] = hits[0]
    return out


@proto('ph-ege-06-formula', 'ЕГЭ', 6, 'Соответствие: физическая величина ↔ формула для её расчёта (механика)',
       invariant='вывод формул из определений и законов: движение по окружности, наклонная плоскость с трением, бросок горизонтально и вверх, пружинный маятник',
       varies='ситуация (окружность, наклонная плоскость, горизонтальный бросок, пружинный маятник, бросок вверх), пара величин, набор формул-«ловушек»',
       answer_rule='для каждой величины вывести формулу; проверка — численное совпадение формулы с независимым расчётом величины',
       mistakes=['sin и cos перепутаны в проекциях', 'пропущен множитель 2 или корень'],
       solve=_solve_formula, kes=['1.1.7', '1.1.8', '1.2.8', '1.5.2'],
       fidelity=FID(6, answer_format='две цифры (номер формулы для величин А и Б)', style='Соответствие «ФИЗИЧЕСКИЕ ВЕЛИЧИНЫ — ФОРМУЛЫ» как в банке',
                    scale='буквенные данные, как в банке', trap='правильная проекция силы тяжести; множитель 2 и корни'))
def g_formula(rng, sets=None, pid='ph-ege-06-formula'):
    sets = sets or FORMULA_SETS
    sid = pick(rng, list(sets))
    text, _, rows, wrongs = sets[sid]
    two = rng.sample(rows, 2)
    others = [r for r in rows if r not in two]
    extra = ([pick(rng, others)[1]] if others else []) + rng.sample(wrongs, 2 if not others else 1)
    right_f = [r[1] for r in two] + extra
    rng.shuffle(right_f)
    rlist = [(str(i + 1), f) for i, f in enumerate(right_f)]
    ans = {lab: str(right_f.index(r[1]) + 1) for lab, r in zip('АБ', two)}
    q = text + ' Установите соответствие между физическими величинами и формулами, по которым их можно рассчитать' + (' (g — ускорение свободного падения).' if sets is FORMULA_SETS else '.') + ' К каждой позиции первого столбца подберите соответствующую позицию из второго столбца.'
    o = match_opts([r[0] for r in two], right_f)
    e = '; '.join(f'{r[0]} = {r[1]}' for r in two) + '. Ответ: ' + ans['А'] + ans['Б'] + '.'
    return pcard(pid, q, ans, e, k='match', o=o, p={'set': sid, 'left': [r[0] for r in two], 'right': rlist})


# ================================================================= ЗАДАНИЕ 7. МКТ, идеальный газ (2.1.8, 2.1.9, 2.1.10, 2.1.12)

GASES = [('гелий', 'гелия', 4), ('неон', 'неона', 20), ('аргон', 'аргона', 40), ('азот', 'азота', 28), ('кислород', 'кислорода', 32),
         ('водород', 'водорода', 2), ('углекислый газ', 'углекислого газа', 44)]
MOLS = ['гелий', 'неон', 'аргон']   # одноатомные


def _solve_clap_ratio(p):
    kp, kV, kT = Fr(p['kp']), Fr(p['kV']), Fr(p['kT'])
    if p['ask'] == 'nu':
        return A(Fr(p['nu0']) * kp * kV / kT)
    if p['ask'] == 'T':
        r = kp * kV / Fr(p['kn'])
        return A(1 / r if p.get('inv') else r)
    return A(Fr(p['kn']) * kT / kV)


def _coef(k, s):
    k = Fr(k)
    if k == 1:
        return s
    if k.denominator != 1 and k.numerator == 1:
        return f'{s}/{k.denominator}'
    return f'{Q(k)}{s}'


@proto('ph-ege-07-clapeyron-ratio', 'ЕГЭ', 7, 'Уравнение Менделеева — Клапейрона: изменение состояния в долях p0, V0, T0',
       invariant='pV = νRT ⇒ ν ~ pV/T; при неизменном количестве вещества pV/T = const',
       varies='газ (гелий, неон, азот …), кратности давления, объёма и температуры, что найти (количество вещества, отношение температур, давлений); '
              'масса газа может меняться (утечка, накачка)',
       answer_rule='ν₂ = ν₁·(p₂/p₁)(V₂/V₁)(T₁/T₂); T₂/T₁ = (p₂/p₁)(V₂/V₁)(ν₁/ν₂)',
       mistakes=['температура в числителе', 'отношение перевёрнуто', 'не учтено изменение количества вещества'],
       solve=_solve_clap_ratio, kes=['2.1.10', '2.1.12'],
       fidelity=FID(7, answer_format='число (моль или «в … раз(а)»)', style=NUM_STYLE + '; параметры заданы как доли p0, V0, T0 (как в демоверсии 2027)',
                    scale='количества вещества 0,5–6 моль, кратности ½–4 — как в демоверсии и банке', trap='обратная пропорциональность ν и T'))
def g_clap_ratio(rng):
    gas, gasg, _ = pick(rng, GASES)
    ask = pick(rng, ['nu', 'nu', 'T', 'p'])
    kp = pick(rng, [Fr(1), Fr(2), Fr(1, 2), Fr(3), Fr(3, 2), Fr(1, 3)])
    kV = pick(rng, [Fr(1), Fr(2), Fr(3), Fr(1, 2), Fr(4), Fr(2, 3)])
    kT = pick(rng, [Fr(1), Fr(2), Fr(1, 2), Fr(3), Fr(3, 2), Fr(4)])
    if ask == 'nu':
        nu0 = pick(rng, [Fr(1, 2), 1, Fr(3, 2), 2, 3, 4, 6])
        a0 = pick(rng, [1, 2, 3])
        if kp == 1 and kV == 1 and kT == 1:
            raise Retry
        p = {'ask': ask, 'nu0': str(nu0), 'kp': str(kp), 'kV': str(kV), 'kT': str(kT)}
        ans = _solve_clap_ratio(p)
        q = (f'Идеальный газ {gas} количеством {Q(nu0)} моль при давлении p0 и температуре T0 занимает объём {_coef(a0, "V0")}. '
             f'Какое количество этого газа при давлении {_coef(kp, "p0")} и температуре {_coef(kT, "T0")} будет занимать объём {_coef(kV * a0, "V0")}?' + ans_line('моль'))
        e = f'ν = pV/(RT) ⇒ ν₂ = ν₁·(p₂/p₁)(V₂/V₁)(T₁/T₂) = {Q(nu0)}·{Q(kp)}·{Q(kV)}/{Q(kT)} = {ans} моль.'
        wrong = [W(nu0 * kp * kV * kT), W(nu0 * kT / (kp * kV)), W(nu0 * kp * kV * a0 / kT)]
    elif ask == 'T':
        kn = pick(rng, [Fr(1), Fr(1), Fr(2), Fr(1, 2)])
        r = kp * kV / kn
        if r == 1 or r < 1 and not ok_dec(1 / r) or r > 1 and not ok_dec(r):
            raise Retry
        p = {'ask': ask, 'kp': str(kp), 'kV': str(kV), 'kT': '1', 'kn': str(kn)}
        parts = ([f'давление газа {chg(kp, ("увеличили", "уменьшили"))}'] if kp != 1 else ['давление газа оставили прежним']) + ([f'объём {chg(kV, ("увеличили", "уменьшили"))}'] if kV != 1 else [])
        if kn != 1:
            parts.append(f'количество газа в сосуде {chg(kn, ("увеличили", "уменьшили"))}')
        if r > 1:
            q = f'С разреженным газом ({gas}) провели опыт: ' + ', '.join(parts) + '. Во сколько раз увеличилась абсолютная температура газа?' + ans_line(raz_=True)
            ans = _solve_clap_ratio(p)
        else:
            p['inv'] = 1
            q = f'С разреженным газом ({gas}) провели опыт: ' + ', '.join(parts) + '. Во сколько раз уменьшилась абсолютная температура газа?' + ans_line(raz_=True)
            ans = A(1 / r)
        e = f'T ~ pV/ν ⇒ T₂/T₁ = {Q(kp)}·{Q(kV)}/{Q(kn)} = {Q(r)}. Ответ: {ans}.'
        wrong = [W(kp / kV), W(kV / kp), W(kp * kV * kn)]
    else:
        kn = pick(rng, [Fr(1), Fr(2), Fr(1, 2), Fr(3)])
        r = kn * kT / kV
        if r <= 1 or not ok_dec(r) or kn == 1 and kT == 1 and kV == 1:
            raise Retry
        p = {'ask': ask, 'kp': '1', 'kV': str(kV), 'kT': str(kT), 'kn': str(kn)}
        parts = ([f'абсолютную температуру {chg(kT, ("увеличили", "уменьшили"))}'] if kT != 1 else []) + ([f'объём сосуда {chg(kV, ("увеличили", "уменьшили"))}'] if kV != 1 else []) + \
                ([f'количество газа {chg(kn, ("увеличили", "уменьшили"))}'] if kn != 1 else [])
        q = f'В сосуде находится разреженный {gas}. ' + ', '.join(parts).capitalize() + '. Во сколько раз увеличилось давление газа?' + ans_line(raz_=True)
        ans = _solve_clap_ratio(p)
        e = f'p ~ νT/V ⇒ p₂/p₁ = {Q(kn)}·{Q(kT)}/{Q(kV)} = {ans}.'
        wrong = [W(kn * kT * kV), W(kV / (kn * kT)), W(kT / kV)]
    q = q.replace('разреженный углекислый газ', 'разреженный углекислый газ').replace('Идеальный газ углекислый газ', 'Углекислый газ').replace('Идеальный газ ', 'Газообразный ')
    return num_card('ph-ege-07-clapeyron-ratio', q, ans, e, p, wrong)


def _solve_pnkt(p):
    k = p['kind']
    if k == 'p_nT':
        return A(Fr(p['p0']) * Fr(p['kn']) * Fr(p['kT']))
    if k == 'n_pE':
        r = Fr(p['kp']) / Fr(p['kE'])
        return A(1 / r if p['inv'] else r)
    return A(Fr(p['n']) * Fr(138, 100) * Fr(p['T']) / 10)



@proto('ph-ege-07-pnkt', 'ЕГЭ', 7, 'Связь давления с концентрацией и температурой: p = nkT, p = ⅔nĒ',
       invariant='p = nkT, p = (2/3)nĒ; при изменении n, T, Ē давление меняется пропорционально',
       varies='газ (гелий, аргон, неон, водяной пар в воздухе), кратности изменения концентрации, температуры, средней энергии; что найти (давление, концентрацию, энергию)',
       answer_rule='p₂/p₁ = (n₂/n₁)(T₂/T₁); n₂/n₁ = (p₂/p₁)/(Ē₂/Ē₁); p = nkT при k = 1,38·10⁻²³ Дж/К',
       mistakes=['давление ~ 1/n', 'энергия и температура не связаны', 'степени десяти при подстановке k'],
       solve=_solve_pnkt, kes=['2.1.8', '2.1.9'],
       fidelity=FID(7, answer_format='число (кПа или «в … раз(а)»)', style=NUM_STYLE + '; k = 1,38·10⁻²³ Дж/К из справочных данных',
                    scale='как в банке: давления 60–300 кПа, кратности 2–6, концентрации ~10²⁵ м⁻³', trap='пропорциональность p ~ nT'))
def g_pnkt(rng):
    kind = pick(rng, ['p_nT', 'p_nT', 'n_pE', 'p_num'])
    gas, gasg, _ = pick(rng, GASES[:3] + [GASES[3]])
    if kind == 'p_nT':
        kn = pick(rng, [Fr(2), Fr(3), Fr(1, 2), Fr(1, 3), Fr(4), Fr(1, 4), Fr(1)])
        kT = pick(rng, [Fr(2), Fr(3), Fr(1, 2), Fr(3, 2), Fr(4), Fr(1)])
        p0 = pick(rng, [60, 80, 100, 120, 150, 160, 200, 300])
        if kn == 1 and kT == 1 or kn * kT == 1:
            raise Retry
        p = {'kind': kind, 'kn': str(kn), 'kT': str(kT)}
        r = kn * kT
        if not ok_dec(p0 * r):
            raise Retry
        parts = ([f'концентрацию его молекул {chg(kn, ("увеличили", "уменьшили"))}'] if kn != 1 else []) + ([f'абсолютную температуру {chg(kT, ("увеличили", "уменьшили"))}'] if kT != 1 else [])
        q = f'Разреженный {gas} в сосуде находится под давлением {p0} кПа. ' + ' и '.join(parts).capitalize() + '. Каким стало давление газа?' + ans_line('кПа')
        ans = A(p0 * r)
        p['p0'] = p0
        e = f'p = nkT ⇒ p₂ = {p0}·{Q(kn)}·{Q(kT)} = {ans} кПа.'
        wrong = [W(p0 * kn / kT), W(p0 * kT / kn), W(p0 / r)]
    elif kind == 'n_pE':
        kp = pick(rng, [Fr(2), Fr(3), Fr(4), Fr(6), Fr(1, 2)])
        kE = pick(rng, [Fr(2), Fr(3), Fr(4), Fr(1, 2)])
        r = kp / kE
        if r == 1 or not ok_dec(r if r > 1 else 1 / r):
            raise Retry
        p = {'kind': kind, 'kp': str(kp), 'kE': str(kE)}
        q = (f'В опыте с разреженным газом ({gas}) давление стало в {raz(kp if kp > 1 else 1 / kp)} {"больше" if kp > 1 else "меньше"}, а средняя энергия поступательного движения молекул — '
             f'в {raz(kE if kE > 1 else 1 / kE)} {"больше" if kE > 1 else "меньше"}. Определите, во сколько раз {"возросла" if r > 1 else "снизилась"} концентрация молекул.' + ans_line(raz_=True))
        ans = A(r if r > 1 else 1 / r)
        p['inv'] = r < 1
        e = f'p = ⅔nĒ ⇒ n₂/n₁ = (p₂/p₁)/(Ē₂/Ē₁) = {Q(kp)}/{Q(kE)} = {Q(r)}. Ответ: {ans}.'
        wrong = [W(kp * kE), W(kE / kp), W(kp)]
    else:
        n = pick(rng, [1, 2, 3, 4, 5, 6])
        T = pick(rng, [250, 300, 400, 500, 600])
        p = {'kind': kind, 'n': n, 'T': T, 'e': 0}
        val = Fr(n) * Fr(138, 100) * T * 10 ** 25 * Fr(1, 10 ** 23) / 1000
        if not ok_dec(val, 2):
            raise Retry
        q = f'Концентрация молекул разреженного газа ({gas}) {n}·10²⁵ м⁻³, его температура {T} К. Чему равно давление газа?' + ans_line('кПа')
        ans = A(val)
        e = f'p = nkT = {n}·10²⁵·1,38·10⁻²³·{T} = {Q(val * 1000)} Па = {ans} кПа.'
        wrong = [W(val * 1000), W(val / 10), W(Fr(n) * T / 1000)]
    return num_card('ph-ege-07-pnkt', q, ans, e, p, wrong)





def _solve_ekT(p):
    k = p['kind']
    T1, T2 = Fr(p['T1']), Fr(p['T2'])
    if k == 'ratio':
        return A(T2 / T1 if T2 > T1 else T1 / T2)
    if k == 'dT':
        # Ē растёт в r раз при увеличении T на dT: T1(r − 1) = dT
        r, dT = Fr(p['r']), Fr(p['dT'])
        return A(dT / (r - 1) if p['ask'] == 'T1' else dT / (r - 1) * r)
    if k == 'vrms':
        return A(Fr(p['kv']) ** 2)
    raise ValueError(k)


@proto('ph-ege-07-energy-temp', 'ЕГЭ', 7, 'Средняя кинетическая энергия молекул и абсолютная температура',
       invariant='Ē = (3/2)kT ~ T (абсолютная температура); T = t + 273; υкв ~ √T',
       varies='газ (неон, гелий, аргон, азот), температура в °C или К, как задано изменение (с … до …, «увеличили на ΔT, энергия выросла в r раз», скорость молекул), что найти',
       answer_rule='Ē₂/Ē₁ = T₂/T₁ в кельвинах; из T₂ = rT₁ и T₂ − T₁ = ΔT: T₁ = ΔT/(r − 1); при росте υкв в k раз T растёт в k² раз',
       mistakes=['отношение взято в градусах Цельсия', 'энергия ~ √T', 'T₁ = ΔT/r'],
       solve=_solve_ekT, kes=['2.1.8'],
       fidelity=FID(7, answer_format='число (К или «в … раз(а)»)', style=NUM_STYLE + '; «0 К = −273 °С» из справочных данных',
                    scale='как в банке: 27 → 177 °С, 140 → 280 К, «на 600 К — в 3 раза»', trap='перевод °C → К; линейная связь Ē и T'))
def g_ekT(rng):
    kind = pick(rng, ['ratio', 'ratio', 'dT', 'vrms'])
    gas, gasg, _ = pick(rng, GASES[:4])
    if kind == 'ratio':
        T1 = pick(rng, [150, 200, 250, 300, 350, 400, 450, 500, 600])
        k = pick(rng, [Fr(3, 2), Fr(2), Fr(3), Fr(1, 2), Fr(2, 3), Fr(4), Fr(5, 4), Fr(4, 3)])
        T2 = T1 * k
        if T2.denominator != 1 or T2 < 100:
            raise Retry
        cel = rng.random() < 0.5
        f = (lambda T: f'{Q(T - 273)} °С') if cel else (lambda T: f'{Q(T)} К')
        up = T2 > T1
        p = {'kind': kind, 'T1': str(T1), 'T2': str(T2)}
        ans = _solve_ekT(p)
        q = (f'Разреженный {gas} {"нагрели" if up else "охладили"} от {f(T1)} до {f(T2)}. Определите отношение средней энергии поступательного теплового движения молекул газа '
             f'{"в конечном состоянии к её значению в начальном" if up else "в начальном состоянии к её значению в конечном"}.' + ans_line())
        e = f'Ē ~ T: T₁ = {T1} К, T₂ = {Q(T2)} К; отношение {ans}.'
        wrong = [W(Fr(T2 - 273, T1 - 273) if T1 != 273 else 5) if cel else W(1 / k), W(k * k if up else 1 / k / k), W(abs(T2 - T1))]
    elif kind == 'dT':
        r = pick(rng, [Fr(3, 2), 2, 3, 4, 5])
        T1 = pick(rng, [100, 150, 200, 250, 300, 400])
        dT = T1 * (r - 1)
        ask = pick(rng, ['T1', 'T2'])
        p = {'kind': kind, 'r': str(r), 'dT': str(dT), 'ask': ask, 'T1': '1', 'T2': '1'}
        ans = _solve_ekT(p)
        q = (f'Разреженный {gas} нагрели на {Q(dT)} К, и средняя энергия поступательного теплового движения его молекул стала в {raz(r)} больше. '
             f'Определите {"начальную" if ask == "T1" else "конечную"} абсолютную температуру газа.' + ans_line('К'))
        e = f'T₂ = rT₁, T₂ − T₁ = ΔT ⇒ T₁ = ΔT/(r − 1) = {Q(dT / (r - 1))} К, T₂ = {Q(dT / (r - 1) * r)} К. Ответ: {ans}.'
        wrong = [W(dT / r), W(dT * r), W(dT / (r + 1))]
    else:
        kv = pick(rng, [Fr(2), Fr(3), Fr(3, 2), Fr(1, 2)])
        p = {'kind': kind, 'kv': str(kv), 'T1': '1', 'T2': '1'}
        if kv < 1:
            q = f'После охлаждения газа ({gas}) среднеквадратичная скорость его молекул стала в {raz(1 / kv)} меньше. Определите, во сколько раз снизилась абсолютная температура газа.' + ans_line(raz_=True)
            p['kv'] = str(1 / kv)
        else:
            q = f'После нагревания газа ({gas}) среднеквадратичная скорость его молекул стала в {raz(kv)} больше. Определите, во сколько раз возросла абсолютная температура газа.' + ans_line(raz_=True)
        ans = _solve_ekT(p)
        e = f'Ē = m₀υ²/2 = (3/2)kT ⇒ T ~ υ² ⇒ {ans}.'
        wrong = [W(Fr(p['kv'])), W(2 * Fr(p['kv'])), W(Fr(p['kv']) ** 3)]
    return num_card('ph-ege-07-energy-temp', q, ans, e, p, wrong)


def _solve_iso(p):
    k = p['kind']
    a1, T1, T2 = Fr(p['a1']), Fr(p['T1']), Fr(p['T2'])
    if k in ('isobar', 'isochor'):
        return A(a1 * T2 / T1 - (a1 if p.get('delta') else 0))
    if k == 'isotherm':
        return A(a1 * Fr(p['V1']) / Fr(p['V2']))
    if k == 'Tfind':
        return A(T1 * Fr(p['a2']) / a1 - 273 * (1 if p.get('cel') else 0))
    raise ValueError(k)


@proto('ph-ege-07-isoprocess', 'ЕГЭ', 7, 'Изопроцессы: расчёт параметра конечного состояния',
       invariant='при ν = const: изобара V/T = const, изохора p/T = const, изотерма pV = const; температура — в кельвинах',
       varies='газ и сосуд (баллон, цилиндр с поршнем, шар-зонд, шприц), процесс, температуры в К или °C, что найти (объём, давление, температуру, изменение объёма)',
       answer_rule='подстановка в закон изопроцесса с переводом °C в К',
       mistakes=['температура в °C в отношении', 'изотерма: p ~ V', 'найдено новое значение вместо изменения'],
       solve=_solve_iso, kes=['2.1.12'],
       fidelity=FID(7, answer_format='число (л, кПа, К или °С)', style=NUM_STYLE,
                    scale='как в банке: объёмы 1–20 л, давления 50–400 кПа, температуры 200–600 К', trap='абсолютная температура'))
def g_iso(rng):
    kind = pick(rng, ['isobar', 'isochor', 'isotherm', 'Tfind'])
    gas, gasg, _ = pick(rng, GASES)
    T1 = pick(rng, [200, 250, 273, 300, 350, 400, 500, 600])
    T2 = pick(rng, [150, 200, 273, 300, 400, 450, 546, 600, 800, 900])
    if T1 == T2:
        raise Retry
    cel = rng.random() < 0.4

    def tt(T):
        return f'{Q(T - 273)} °С' if cel else f'{T} К'
    if kind == 'isobar':
        V1 = pick(rng, [2, 3, 4, 5, 6, 8, 10, 12, 15, 20])
        delta = rng.random() < 0.3 and T2 > T1
        p = {'kind': kind, 'a1': V1, 'T1': T1, 'T2': T2, 'delta': delta}
        ans = _solve_iso(p)
        q = (f'{gas.capitalize()} в цилиндре под лёгким подвижным поршнем занимает объём {V1} л при температуре {tt(T1)}. Газ {"нагрели" if T2 > T1 else "охладили"} при постоянном давлении до {tt(T2)}. '
             + ('На сколько увеличился объём газа?' if delta else 'Какой объём занимает газ в конечном состоянии?') + ans_line('л'))
        e = f'V/T = const: V₂ = {V1}·{T2}/{T1} = {Q(Fr(V1 * T2, T1))} л.' + (f' ΔV = {ans} л.' if delta else '')
        wrong = [W(Fr(V1 * T1, T2)), W(Fr(V1 * (T2 - 273), T1 - 273) if cel and T1 != 273 else V1 * 2), W(Fr(V1 * T2, T1))] if delta else [W(Fr(V1 * T1, T2)), W(Fr(V1 * (T2 - 273), (T1 - 273))) if cel and T1 != 273 else W(V1 + T2 - T1), W(Fr(V1 * T2, T1) - V1)]
    elif kind == 'isochor':
        p1 = pick(rng, [50, 80, 100, 120, 150, 200, 240, 300])
        p = {'kind': kind, 'a1': p1, 'T1': T1, 'T2': T2}
        ans = _solve_iso(p)
        q = (f'В закрытом баллоне {gas} находится под давлением {p1} кПа при температуре {tt(T1)}. Каким станет давление газа, если его {"нагреть" if T2 > T1 else "охладить"} до {tt(T2)}? '
             f'Объём баллона считать неизменным.' + ans_line('кПа'))
        e = f'p/T = const: p₂ = {p1}·{T2}/{T1} = {ans} кПа.'
        wrong = [W(Fr(p1 * T1, T2)), W(Fr(p1 * (T2 - 273), (T1 - 273))) if T1 != 273 and T2 != 273 else W(p1 * 2), W(p1)]
    elif kind == 'isotherm':
        pa = pick(rng, [50, 80, 100, 120, 150, 200])
        V1, V2 = rng.sample([1, 2, 3, 4, 5, 6, 8, 10, 12], 2)
        p = {'kind': kind, 'a1': pa, 'V1': V1, 'V2': V2, 'T1': 1, 'T2': 1}
        ans = _solve_iso(p)
        q = (f'Разреженный {gas} при давлении {pa} кПа занимает объём {V1} л. Газ {"сжали" if V2 < V1 else "расширили"} при постоянной температуре до объёма {V2} л. Каким стало его давление?' + ans_line('кПа'))
        e = f'pV = const: p₂ = {pa}·{V1}/{V2} = {ans} кПа.'
        wrong = [W(Fr(pa * V2, V1)), W(pa), W(pa * V1 * V2)]
    else:
        V1 = pick(rng, [2, 3, 4, 5, 6, 8, 10])
        V2 = Fr(V1) * T2 / T1
        if not ok_dec(V2, 1):
            raise Retry
        p = {'kind': kind, 'a1': V1, 'a2': str(V2), 'T1': T1, 'T2': T2, 'cel': cel}
        ans = _solve_iso(p)
        q = (f'Объём {gasg}, находящегося под поршнем при постоянном давлении, изменился от {V1} до {Q(V2)} л. Начальная температура газа {tt(T1)}. '
             f'Какой стала температура газа?' + ans_line('°С' if cel else 'К'))
        e = f'V/T = const: T₂ = {T1}·{Q(V2)}/{V1} = {T2} К' + (f' = {ans} °С.' if cel else '.')
        wrong = [W(Fr(T1 * V1) / V2), W(T2) if cel else W(T2 - 273), W((T1 - 273) * V2 / V1) if cel else W(T1 * V1)]
    return num_card('ph-ege-07-isoprocess', q, ans, e, p, wrong)


def _solve_mendeleev(p):
    k = p['kind']
    if k == 'm':
        return A(Fr(p['p']) * 1000 * Fr(p['V']) / (R_GAS * Fr(p['T'])) * Fr(p['M']) * 1000)
    nu = Fr(p['m']) / Fr(p['M']) if p.get('m') else Fr(p['nu'])
    if k == 'p':
        return A(nu * R_GAS * Fr(p['T']) / Fr(p['V']) / 1000)
    if k == 'V':
        return A(nu * R_GAS * Fr(p['T']) / (Fr(p['p']) * 1000) * 1000)
    if k == 'T':
        return A(Fr(p['p']) * 1000 * Fr(p['V']) / (nu * R_GAS))
    if k == 'm':
        return A(Fr(p['p']) * 1000 * Fr(p['V']) / (R_GAS * Fr(p['T'])) * Fr(p['M']))
    raise ValueError(k)


@proto('ph-ege-07-mendeleev', 'ЕГЭ', 7, 'Уравнение Менделеева — Клапейрона: расчёт давления, объёма, температуры, массы',
       invariant='pV = (m/M)RT = νRT при R = 8,31 Дж/(моль·К)',
       varies='газ (молярные массы из справочных данных КИМ), сосуд, что дано и что найти (p, V, T, m, ν)',
       answer_rule='подстановка в pV = νRT с переводом л → м³, кПа → Па, г → кг',
       mistakes=['объём в литрах подставлен как м³', 'молярная масса в г/моль', 'температура в °C'],
       solve=_solve_mendeleev, kes=['2.1.10'],
       fidelity=FID(7, answer_format='число (кПа, л, К, г)', style=NUM_STYLE + '; R = 8,31 Дж/(моль·К), молярные массы — из справочных данных',
                    scale='как в банке: 1–10 моль, объёмы 8,31–83,1 л, температуры 200–600 К', trap='перевод единиц'))
def g_mendeleev(rng):
    kind = pick(rng, ['p', 'V', 'T', 'm'])
    gas, gasg, M = pick(rng, GASES)
    Mk = Fr(M, 1000)
    T = pick(rng, [200, 250, 300, 350, 400, 500, 600])
    use_m = rng.random() < 0.5
    nu = pick(rng, [Fr(1, 2), 1, 2, 3, 4, 5, 10])
    V = pick(rng, [Fr(831, 100000), Fr(1662, 100000), Fr(831, 10000), Fr(2493, 100000), Fr(4155, 100000)])
    pr = nu * R_GAS * T / V / 1000
    if not ok_dec(pr, 2):
        raise Retry
    mg = nu * M
    sub = f'{Q(mg)} г {gasg}' if use_m else f'{Q(nu)} моль {gasg}'
    base = {'M': str(Mk)} | ({'m': str(mg / 1000)} if use_m else {'nu': str(nu)})
    if kind == 'p':
        p = dict(base, kind=kind, T=T, V=str(V))
        q = f'В сосуде объёмом {Q(V * 1000)} л находится {sub} при температуре {T} К. Каково давление газа?' + ans_line('кПа')
    elif kind == 'V':
        p = dict(base, kind=kind, T=T, p=str(pr))
        q = f'{sub[0].upper() + sub[1:]} находится при температуре {T} К и давлении {Q(pr)} кПа. Какой объём занимает газ?' + ans_line('л')
    elif kind == 'T':
        p = dict(base, kind=kind, p=str(pr), V=str(V))
        q = f'{sub[0].upper() + sub[1:]} занимает объём {Q(V * 1000)} л при давлении {Q(pr)} кПа. Какова температура газа?' + ans_line('К')
    else:
        p = {'kind': kind, 'M': str(Mk), 'p': str(pr), 'V': str(V), 'T': T}
        q = f'В баллоне объёмом {Q(V * 1000)} л находится {gas} при давлении {Q(pr)} кПа и температуре {T} К. Какова масса газа в баллоне?' + ans_line('г')
    ans = _solve_mendeleev(p)
    e = f'pV = νRT (ν = {Q(nu)} моль, R = 8,31 Дж/(моль·К)). Ответ: {ans}.'
    wrong = [W(Fr(ans.replace(',', '.').replace('−', '-')) * 1000), W(Fr(ans.replace(',', '.').replace('−', '-')) / 1000), W(Fr(ans.replace(',', '.').replace('−', '-')) * Fr(273, T))]
    return num_card('ph-ege-07-mendeleev', q, ans, e, p, wrong)





def _solve_leak(p):
    k = p['kind']
    if k == 'released':
        return A(Fr(p['nu']) * (1 - Fr(p['p2']) / Fr(p['p1'])))
    if k == 'frac':
        return A((1 - Fr(p['p2']) / Fr(p['p1'])) * 100)
    if k == 'pump':
        return A(Fr(p['p1']) * (Fr(p['nu']) + Fr(p['dnu'])) / Fr(p['nu']))
    raise ValueError(k)


@proto('ph-ege-07-leak', 'ЕГЭ', 7, 'Изменение количества газа в сосуде (утечка, накачка) при постоянных V и T',
       invariant='при V, T = const давление пропорционально количеству вещества: p₂/p₁ = ν₂/ν₁',
       varies='сосуд (металлический баллон, камера мяча, шина, газгольдер), газ, давления, количество вещества, что найти (выпущенное количество, долю, новое давление)',
       answer_rule='ν₂ = ν₁·p₂/p₁; Δν = ν₁ − ν₂; доля выпущенного газа (1 − p₂/p₁)·100 %',
       mistakes=['найдено оставшееся количество вместо выпущенного', 'давление обратно пропорционально ν'],
       solve=_solve_leak, kes=['2.1.10', '2.1.12'],
       fidelity=FID(7, answer_format='число (моль, %, кПа)', style=NUM_STYLE, scale='как в банке: баллон с 3 моль, давления 100–600 кПа', trap='пропорциональность p и ν при V, T = const'))
def g_leak(rng):
    kind = pick(rng, ['released', 'frac', 'pump'])
    gas, gasg, _ = pick(rng, GASES)
    vessel = pick(rng, ['металлическом баллоне', 'стальном баллоне', 'газгольдере постоянного объёма', 'закрытом жёстком сосуде'])
    p1 = pick(rng, [200, 300, 400, 500, 600, 800, 1000])
    p2 = pick(rng, [x for x in (100, 150, 200, 250, 300, 400, 500) if x < p1])
    nu = pick(rng, [2, 3, 4, 5, 6, 8, 10])
    if kind == 'released':
        p = {'kind': kind, 'nu': nu, 'p1': p1, 'p2': p2}
        ans = _solve_leak(p)
        q = (f'В {vessel} находилось {nu} моль {gasg} под давлением {p1} кПа. После того как часть газа выпустили, давление упало до {p2} кПа, температура не изменилась. '
             f'Какое количество газа выпустили?' + ans_line('моль'))
        e = f'p ~ ν ⇒ ν₂ = {nu}·{p2}/{p1} = {Q(Fr(nu * p2, p1))} моль; выпущено {ans} моль.'
        wrong = [W(Fr(nu * p2, p1)), W(Fr(nu * p1, p2) - nu), W(nu - Fr(p2, 100))]
    elif kind == 'frac':
        p = {'kind': kind, 'p1': p1, 'p2': p2}
        ans = _solve_leak(p)
        q = f'Из {vessel.replace("баллоне", "баллона").replace("газгольдере", "газгольдера").replace("сосуде", "сосуда").replace("металлическом", "металлического").replace("стальном", "стального").replace("закрытом жёстком", "закрытого жёсткого")} с {gasg.replace("гелия", "гелием").replace("неона", "неоном").replace("аргона", "аргоном").replace("азота", "азотом").replace("кислорода", "кислородом").replace("водорода", "водородом").replace("углекислого газа", "углекислым газом")} выпустили часть газа, и давление при неизменной температуре уменьшилось от {p1} до {p2} кПа. Какую часть газа (в процентах) выпустили?' + ans_line('%')
        e = f'Осталось p₂/p₁ = {Q(Fr(p2, p1) * 100)} % газа, выпущено {ans} %.'
        wrong = [W(Fr(p2, p1) * 100), W(Fr(p1, p2) * 100), W(p1 - p2)]
    else:
        dnu = pick(rng, [1, 2, 3, 4, 5])
        p = {'kind': kind, 'nu': nu, 'dnu': dnu, 'p1': p1}
        ans = _solve_leak(p)
        q = (f'В {vessel} находится {nu} моль {gasg} под давлением {p1} кПа. В сосуд накачали ещё {dnu} моль того же газа, температура осталась прежней. Каким стало давление?' + ans_line('кПа'))
        e = f'p ~ ν ⇒ p₂ = {p1}·({nu} + {dnu})/{nu} = {ans} кПа.'
        wrong = [W(Fr(p1 * dnu, nu)), W(Fr(p1 * nu, nu + dnu)), W(p1 + dnu)]
    return num_card('ph-ege-07-leak', q, ans, e, p, wrong)


# ================================================================= ЗАДАНИЕ 8. Термодинамика (2.2.4–2.2.7, 2.2.9, 2.2.10)

HEATC = {'воды': 4200, 'чугуна': 500, 'спирта': 2400, 'железа': 460, 'льда': 2100, 'свинца': 130, 'алюминия': 900, 'меди': 380}
# (объект, вещество (род.), объект в род. падеже — всегда с названием вещества)
HEAT_OBJ = [('Чугунная болванка', 'чугуна', 'чугунной болванки'), ('Алюминиевая деталь', 'алюминия', 'алюминиевой детали'), ('Медный брусок', 'меди', 'медного бруска'),
            ('Железная заготовка', 'железа', 'железной заготовки'), ('Свинцовая пластина', 'свинца', 'свинцовой пластины'), ('Вода в чайнике', 'воды', 'воды'),
            ('Кусок льда', 'льда', 'льда'), ('Спирт в колбе', 'спирта', 'спирта')]


def _solve_heat(p):
    c = HEATC[p['mat']]
    k = p['ask']
    if k == 'Q':
        return A(c * Fr(p['m']) * abs(Fr(p['t2']) - Fr(p['t1'])) / 1000)
    if k == 'm':
        return A(Fr(p['Q']) * 1000 / (c * abs(Fr(p['t2']) - Fr(p['t1']))))
    if k == 'dt':
        return A(Fr(p['Q']) * 1000 / (c * Fr(p['m'])))
    if k == 'c':
        return A(Fr(p['Q']) * 1000 / (Fr(p['m']) * abs(Fr(p['t2']) - Fr(p['t1']))))
    raise ValueError(k)


@proto('ph-ege-08-heat', 'ЕГЭ', 8, 'Количество теплоты при нагревании и охлаждении: Q = cmΔt',
       invariant='Q = cm|Δt|; удельные теплоёмкости — из справочных данных КИМ',
       varies='тело и вещество (чугунная болванка, алюминиевая деталь, медный брусок, вода, лёд, спирт), нагревание или остывание, что найти (Q, m, Δt, c)',
       answer_rule='подстановка в Q = cmΔt с переводом кДж ↔ Дж, г ↔ кг',
       mistakes=['кДж не переведены', 'Δt взята как конечная температура', 'перепутаны удельные теплоёмкости'],
       solve=_solve_heat, kes=['2.2.4'],
       fidelity=FID(8, answer_format='число (кДж, кг, °С, Дж/(кг·К))', style=NUM_STYLE + '; удельные теплоёмкости — из справочных данных КИМ',
                    scale='как в демоверсии 2027 (чугунная болванка 450 → 80 °С, 44 400 кДж) и банке', trap='знак Δt при остывании; единицы'))
def g_heat(rng):
    obj, mat, gen = pick(rng, HEAT_OBJ)
    c = HEATC[mat]
    ask = pick(rng, ['Q', 'm', 'dt', 'c'])
    m = pick(rng, {'Чугунная болванка': [20, 50, 80, 100, 120, 200], 'Алюминиевая деталь': [Fr(1, 5), Fr(1, 2), 1, 2, 3, 6], 'Медный брусок': [Fr(1, 10), Fr(1, 5), Fr(1, 2), 1, 2],
                   'Железная заготовка': [1, 2, 5, 10, 20], 'Свинцовая пластина': [Fr(1, 10), Fr(1, 5), Fr(1, 2), 1, 2], 'Вода в чайнике': [Fr(1, 2), 1, Fr(3, 2), 2],
                   'Кусок льда': [Fr(1, 10), Fr(1, 5), Fr(1, 2), 1, 2, 5], 'Спирт в колбе': [Fr(1, 10), Fr(1, 5), Fr(1, 2)]}[obj])
    t1 = pick(rng, [-20, -10, 0, 10, 20, 25, 40, 80, 100]) if mat == 'льда' else pick(rng, [10, 15, 20, 25, 30, 40, 80, 100, 250, 450])
    t2 = pick(rng, [-5, -2, 0, -10]) if mat == 'льда' else pick(rng, [20, 30, 40, 60, 80, 100, 150, 327, 500])
    if mat == 'льда' and (t1 > 0 or t2 > 0):
        t1 = pick(rng, [-40, -30, -20, -10])
    if mat in ('воды', 'спирта') and (max(t1, t2) > 78 and mat == 'спирта' or max(t1, t2) > 100):
        raise Retry
    if t1 == t2:
        raise Retry
    Qk = c * m * abs(t2 - t1) / 1000
    if not ok_dec(Qk, 2):
        raise Retry
    heat = t2 > t1
    p = {'mat': mat, 'm': str(m), 't1': t1, 't2': t2, 'ask': ask, 'Q': str(Qk)}
    ans = _solve_heat(p)
    mm = f'{Q(m * 1000)} г' if m < 1 else f'{Q(m)} кг'
    verb = 'нагрели' if heat else 'охладили'
    if ask == 'Q':
        q = f'{obj} массой {mm} {"нагревается" if heat else "остывает"} от {Q(t1)} до {Q(t2)} °С. Какое количество теплоты {"получает" if heat else "отдаёт"} { {"воды": "вода", "льда": "лёд", "спирта": "спирт"}.get(gen, obj.split()[1])} при этом?' + ans_line('кДж')
        e = f'Q = cmΔt = {c}·{Q(m)}·{abs(t2 - t1)} = {Q(Qk * 1000)} Дж = {ans} кДж.'
        wrong = [W(Qk * 1000), W(c * m * t2 / 1000), W(Qk * 2)]
    elif ask == 'm':
        q = f'При {"нагревании" if heat else "остывании"} {gen} от {Q(t1)} до {Q(t2)} °С {"было получено" if heat else "выделилось"} количество теплоты {Q(Qk)} кДж. Чему равна масса {gen.replace("воды", "воды").replace("льда", "льда")}?' + ans_line('кг')
        e = f'm = Q/(cΔt) = {Q(Qk * 1000)}/({c}·{abs(t2 - t1)}) = {ans} кг.'
        wrong = [W(Qk / (c * abs(t2 - t1))), W(Qk * 1000 / (c * t1)) if t1 > 0 else W(m * 2), W(Qk * 1000 / c)]
    elif ask == 'dt':
        q = f'{obj} массой {mm} {"получил(а)" if heat else "отдал(а)"} количество теплоты {Q(Qk)} кДж. На сколько градусов {"повысилась" if heat else "понизилась"} {"её" if obj.split()[0].endswith("ая") or obj.startswith("Вода") else "его"} температура? Агрегатное состояние не менялось.' + ans_line('°С')
        q = q.replace('получил(а)', 'получила' if obj.split()[0].endswith('ая') or obj.startswith('Вода') else 'получил').replace('отдал(а)', 'отдала' if obj.split()[0].endswith('ая') or obj.startswith('Вода') else 'отдал')
        e = f'Δt = Q/(cm) = {Q(Qk * 1000)}/({c}·{Q(m)}) = {ans} °С.'
        wrong = [W(Qk / (c * m)), W(Qk * 1000 / c), W(Qk * 1000 * m / c)]
    else:
        q = f'Для определения удельной теплоёмкости вещества образец массой {mm} {verb} от {Q(t1)} до {Q(t2)} °С; при этом оно {"получило" if heat else "отдало"} {Q(Qk)} кДж теплоты. Какова удельная теплоёмкость вещества?' + ans_line('Дж/(кг·К)')
        e = f'c = Q/(mΔt) = {Q(Qk * 1000)}/({Q(m)}·{abs(t2 - t1)}) = {ans} Дж/(кг·К).'
        wrong = [W(Qk / (m * abs(t2 - t1))), W(Qk * 1000 / abs(t2 - t1)), W(Qk * 1000 * m / abs(t2 - t1))]
    return num_card('ph-ege-08-heat', q, ans, e, p, wrong)


LATENT = {'melt_ice': ('плавления льда', 330000, 'лёд', 'льда', 0), 'boil_water': ('парообразования воды', 2300000, 'вода', 'воды', 100),
          'melt_lead': ('плавления свинца', 25000, 'свинец', 'свинца', 327), 'melt_steel': ('плавления стали', 78000, 'сталь', 'стали', 1400),
          'boil_alc': ('парообразования спирта', 900000, 'спирт', 'спирта', 78)}


def _solve_latent(p):
    lam = LATENT[p['sub']][1]
    k = p['ask']
    if k == 'Q':
        return A(lam * Fr(p['m']) / 1000)
    if k == 'm':
        return A(Fr(p['Q']) * 1000 / lam)
    if k == 'Q2':
        c = {'melt_lead': 130, 'melt_ice': 2100}[p['sub']]
        return A((c * Fr(p['m']) * (LATENT[p['sub']][4] - Fr(p['t0'])) + lam * Fr(p['m'])) / 1000)
    raise ValueError(k)


@proto('ph-ege-08-latent', 'ЕГЭ', 8, 'Плавление и парообразование: Q = λm, Q = Lm (в т. ч. с предварительным нагреванием)',
       invariant='при температуре плавления/кипения Q = λm, Q = Lm; при нагревании до этой температуры добавляется cmΔt',
       varies='вещество (лёд, вода, свинец, сталь, спирт — данные КИМ), масса, что найти (Q, m), с нагреванием до точки плавления или без',
       answer_rule='Q = λm (Lm); Q = cm(tпл − t₀) + λm',
       mistakes=['забыт этап нагревания', 'удельная теплота не переведена из 10⁵', 'перепутаны λ и L'],
       solve=_solve_latent, kes=['2.2.4', '2.2.5'],
       fidelity=FID(8, answer_format='число (кДж, кг, г)', style=NUM_STYLE + '; λ и L — из справочных данных КИМ',
                    scale='как в банке: кусок льда 0,1–5 кг, свинец 1 кг от 27 °С', trap='дополнительный этап нагревания до температуры плавления'))
def g_latent(rng):
    sub = pick(rng, list(LATENT))
    name, lam, nom, gen, tm = LATENT[sub]
    ask = pick(rng, ['Q', 'm', 'Q2'] if sub in ('melt_lead', 'melt_ice') else ['Q', 'm'])
    m = pick(rng, [Fr(1, 10), Fr(1, 5), Fr(1, 2), 1, 2, 3, 4, 5, 10])
    Qk = lam * m / 1000
    if not ok_dec(Qk):
        raise Retry
    proc = 'плавления' if 'melt' in sub else 'кипения'
    mm = f'{Q(m * 1000)} г' if m < 1 else f'{Q(m)} кг'
    if ask == 'Q':
        p = {'sub': sub, 'm': str(m), 'ask': ask}
        verb = 'расплавить' if 'melt' in sub else 'превратить в пар'
        q = f'Сколько теплоты потребуется для {"плавления" if "melt" in sub else "превращения в пар"} {mm} {gen}, {"уже нагретого" if nom not in ("вода", "сталь") else "уже нагретой"} до температуры {proc} ({tm} °С)?' + ans_line('кДж')
        e = f'Q = {"λ" if "melt" in sub else "L"}m = {lam}·{Q(m)} = {Q(lam * m)} Дж = {ans_ if (ans_ := A(Qk)) else ""} кДж.'
        ans = _solve_latent(p)
        wrong = [W(lam * m), W(Qk / 1000), W(lam / m / 1000)]
    elif ask == 'm':
        p = {'sub': sub, 'Q': str(Qk), 'ask': ask}
        ans = _solve_latent(p)
        verb = 'расплавили' if 'melt' in sub else 'полностью превратили в пар'
        q = f'{nom.capitalize()} при температуре {proc} {verb}, затратив {Q(Qk)} кДж теплоты. Какова масса {gen}?'.replace('Лёд при', 'Лёд при').replace('Вода при температуре кипения полностью превратили', 'Воду при температуре кипения полностью превратили').replace('Сталь при', 'Сталь при').replace('Спирт при', 'Спирт при') + ans_line('кг')
        e = f'm = Q/{"λ" if "melt" in sub else "L"} = {Q(Qk * 1000)}/{lam} = {ans} кг.'
        wrong = [W(Qk / lam), W(Qk * lam / 1000), W(m * 10)]
    else:
        t0 = pick(rng, [17, 27, 37, 47, 127]) if sub == 'melt_lead' else pick(rng, [-10, -20, -30, -40])
        p = {'sub': sub, 'm': str(m), 't0': t0, 'ask': ask}
        ans = _solve_latent(p)
        c = 130 if sub == 'melt_lead' else 2100
        q = f'Сколько теплоты потребуется, чтобы {"слиток" if sub == "melt_lead" else "кусок"} {gen} массой {mm}, имеющий температуру {t0} °С, довести до температуры плавления и целиком превратить в жидкость?' + ans_line('кДж')
        e = f'Q = cm(tпл − t₀) + λm = {c}·{Q(m)}·{tm - t0} + {lam}·{Q(m)} = {ans} кДж.'
        wrong = [W(lam * m / 1000), W(c * m * (tm - t0) / 1000), W((c * m * (tm - t0) - lam * m) / 1000)]
    q = q.replace('Вода при', 'Воду при').replace('Лёд при температуре плавления расплавили', 'Лёд при температуре плавления расплавили')
    return num_card('ph-ege-08-latent', q, ans, e, p, wrong)


def _solve_first(p):
    Qv, Av = Fr(p['Q']), Fr(p['A'])   # Q > 0 — получено, A > 0 — работа газа
    k = p['ask']
    if k == 'dU':
        return A(Qv - Av)
    if k == 'Q':
        return A(abs(Fr(p['dU']) + Av))
    if k == 'A':
        return A(abs(Qv - Fr(p['dU'])))
    raise ValueError(k)


@proto('ph-ege-08-first-law', 'ЕГЭ', 8, 'Первый закон термодинамики: Q = ΔU + A',
       invariant='Q = ΔU + Aгаза; работа внешних сил A′ = −Aгаза; при отдаче теплоты Q < 0',
       varies='газ и процесс (расширение с получением тепла, сжатие внешними силами с отдачей тепла, адиабатное сжатие), знаки, что найти (ΔU, Q, A)',
       answer_rule='подстановка в Q = ΔU + A с учётом знаков (работа над газом входит с минусом)',
       mistakes=['работа внешних сил и работа газа не различены', 'знак отданной теплоты', 'ΔU = Q + A'],
       solve=_solve_first, kes=['2.2.6', '2.2.7'],
       fidelity=FID(8, answer_format='число, Дж или кДж (со знаком, если спрашивают изменение)', style=NUM_STYLE,
                    scale='как в банке: 30–500 Дж, 12–35 кДж', trap='знаки работы газа и работы внешних сил'))
def g_first(rng):
    gas = pick(rng, ['Газ', 'Идеальный газ', 'Гелий', 'Воздух в цилиндре', 'Аргон'])
    unit = pick(rng, ['Дж', 'кДж'])
    ask = pick(rng, ['dU', 'Q', 'A'])
    sc = pick(rng, ['exp', 'comp', 'comp_out'])
    if sc == 'exp':
        Qv = pick(rng, [100, 200, 300, 400, 500, 600, 800])
        Av = pick(rng, [x for x in (50, 100, 150, 200, 250, 300, 500) if x != Qv])
    elif sc == 'comp':
        Qv = -pick(rng, [10, 20, 30, 50, 100])
        Av = -pick(rng, [30, 50, 100, 200, 300, 500])
    else:
        Qv = pick(rng, [0, 0, 20, 50])
        Av = -pick(rng, [30, 50, 100, 200, 500])
    dU = Qv - Av
    p = {'Q': Qv, 'A': Av, 'dU': dU, 'ask': ask}
    ans = _solve_first(p)

    def qtxt():
        if Qv > 0:
            return f'получил количество теплоты {Qv} {unit}'
        if Qv < 0:
            return f'отдал окружающим телам количество теплоты {-Qv} {unit}'
        return 'не обменивался теплотой с окружающими телами'

    def atxt():
        return f'совершил работу {Av} {unit}' if Av > 0 else f'внешние силы совершили над ним работу {-Av} {unit}'
    if ask == 'dU':
        if Av > 0:
            q = f'В процессе расширения газу ({gas.lower()}) передали {Qv} {unit} теплоты, и он совершил работу {Av} {unit}. Определите изменение внутренней энергии газа.' + ans_line(unit)
        elif Qv < 0:
            q = f'При сжатии газа ({gas.lower()}) внешние силы совершили работу {-Av} {unit}, а газ передал окружающим телам {-Qv} {unit} теплоты. Определите изменение внутренней энергии газа.' + ans_line(unit)
        elif Qv == 0:
            q = f'Газ ({gas.lower()}) сжали без теплообмена с окружающими телами, совершив над ним работу {-Av} {unit}. Определите изменение внутренней энергии газа.' + ans_line(unit)
        else:
            q = f'При сжатии газа ({gas.lower()}) внешние силы совершили работу {-Av} {unit}, и одновременно газу передали {Qv} {unit} теплоты. Определите изменение внутренней энергии газа.' + ans_line(unit)
        q = q.replace(' (газ)', '').replace(' (идеальный газ)', '').replace('(воздух в цилиндре)', '(воздуху в цилиндре)' if 'газу (' in q else '(воздух в цилиндре)')
        e = f'ΔU = Q − Aгаза = {Qv} − ({Av}) = {ans} {unit}.'
        wrong = [W(Qv + Av), W(Av - Qv), W(abs(Qv))]
    elif ask == 'Q':
        if Qv == 0:
            raise Retry
        q = (f'{"При расширении газ совершил работу " + str(Av) + " " + unit if Av > 0 else "При сжатии над газом совершили работу " + str(-Av) + " " + unit}, а его внутренняя энергия '
             f'{"возросла" if dU > 0 else "снизилась"} на {abs(dU)} {unit}. Сколько теплоты газ {"получил от окружающих тел" if Qv > 0 else "передал окружающим телам"}?' + ans_line(unit))
        ans = A(abs(Qv))
        p['abs'] = True
        e = f'Q = ΔU + Aгаза = {dU} + ({Av}) = {Qv} {unit}; модуль {ans} {unit}.'
        wrong = [W(abs(dU - Av)), W(abs(dU)), W(abs(Av))]
    else:
        if dU == 0 or Qv == 0:
            raise Retry
        q = (f'{"Газу передали " + str(Qv) + " " + unit + " теплоты" if Qv > 0 else "Газ передал окружающим телам " + str(-Qv) + " " + unit + " теплоты"}, а его внутренняя энергия {"возросла" if dU > 0 else "снизилась"} на {abs(dU)} {unit}. '
             f'{"Определите работу, совершённую газом." if Av > 0 else "Определите работу, совершённую над газом внешними силами."}' + ans_line(unit))
        ans = A(abs(Av))
        p['abs'] = True
        e = f'Aгаза = Q − ΔU = {Qv} − ({dU}) = {Av} {unit}. Ответ: {ans}.'
        wrong = [W(abs(Qv + dU)), W(abs(dU)), W(abs(Qv))]
    return num_card('ph-ege-08-first-law', q, ans, e, p, wrong)





def _solve_gaswork(p):
    k = p['kind']
    if k == 'pdV':
        return A(Fr(p['p']) * 1000 * (Fr(p['V2']) - Fr(p['V1'])) / 1000)
    if k == 'nuRT':
        return A(Fr(p['nu']) * R_GAS * Fr(p['dT']))
    if k == 'table':
        ps, Vs = [Fr(x) for x in p['ps']], [Fr(x) for x in p['Vs']]
        return A((ps[0] + ps[1]) / 2 * 1000 * (Vs[1] - Vs[0]) / 1000)
    if k == 'Qisobar':
        return A(Fr(5, 2) * Fr(p['p']) * 1000 * (Fr(p['V2']) - Fr(p['V1'])) / 1000)
    raise ValueError(k)


@proto('ph-ege-08-gas-work', 'ЕГЭ', 8, 'Работа газа: изобарный процесс, линейный процесс на pV-диаграмме',
       invariant='при p = const A = pΔV = νRΔT; в общем случае — площадь под графиком p(V); для одноатомного газа в изобаре Q = (5/2)pΔV',
       varies='газ (гелий, неон, аргон, воздух), единицы (кПа, л, моль), процесс (изобарный, линейный от состояния 1 к 2 — график заменён координатами точек), что найти',
       answer_rule='A = pΔV; A = νRΔT; площадь трапеции (p₁ + p₂)/2·(V₂ − V₁); Q = (5/2)pΔV',
       mistakes=['литры не переведены в м³', 'взято конечное давление вместо среднего', 'Q = A при изобарном процессе'],
       solve=_solve_gaswork, kes=['2.2.6', '2.2.7'],
       fidelity=FID(8, answer_format='число, Дж или кДж', style=NUM_STYLE + '; pV-диаграмма заменена координатами состояний',
                    scale='как в банке: 5 моль неона, ΔT до 100 К; давления 100–400 кПа, объёмы 1–10 л', trap='единицы; площадь под графиком'))
def g_gaswork(rng):
    kind = pick(rng, ['pdV', 'nuRT', 'table', 'Qisobar'])
    gas, gasg, _ = pick(rng, GASES[:3])
    if kind == 'pdV':
        pp = pick(rng, [100, 150, 200, 250, 300, 400, 500])
        V1 = pick(rng, [1, 2, 3, 4, 5, 6])
        V2 = V1 + pick(rng, [1, 2, 3, 4, 5])
        comp = rng.random() < 0.3
        if comp:
            V1, V2 = V2, V1
        p = {'kind': kind, 'p': pp, 'V1': V1, 'V2': V2}
        ans = _solve_gaswork(p)
        q = f'Разреженный {gas} при постоянном давлении {pp} кПа {"сжимают" if comp else "расширяется"} от объёма {V1} л до {V2} л. Чему равна работа газа?' + ans_line('Дж')
        e = f'A = pΔV = {pp}·10³·({V2} − {V1})·10⁻³ = {ans} Дж.'
        wrong = [W(-Fr(ans.replace(',', '.').replace('−', '-'))), W(pp * V2), W(pp * (V2 - V1) * 1000)]
    elif kind == 'nuRT':
        nu = pick(rng, [1, 2, 3, 4, 5, 10, 15])
        dT = pick(rng, [10, 20, 50, 100, 200])
        p = {'kind': kind, 'nu': nu, 'dT': dT}
        ans = _solve_gaswork(p)
        q = f'Разреженный {gas} в количестве {nu} моль изобарно нагревают на {dT} К. Какую работу совершает газ?' + ans_line('Дж')
        e = f'A = pΔV = νRΔT = {nu}·8,31·{dT} = {ans} Дж.'
        wrong = [W(Fr(3, 2) * nu * R_GAS * dT), W(Fr(5, 2) * nu * R_GAS * dT), W(nu * dT)]
    elif kind == 'table':
        p1, p2 = pick(rng, [100, 200, 300, 400]), pick(rng, [100, 200, 300, 400, 500])
        V1 = pick(rng, [1, 2, 3, 4])
        V2 = V1 + pick(rng, [1, 2, 3, 4])
        p = {'kind': kind, 'ps': [p1, p2], 'Vs': [V1, V2]}
        ans = _solve_gaswork(p)
        q = (f'Идеальный газ переходит из состояния 1 (p₁ = {p1} кПа, V₁ = {V1} л) в состояние 2 (p₂ = {p2} кПа, V₂ = {V2} л) так, что на pV-диаграмме процесс изображается отрезком прямой. '
             f'Какую работу совершил газ в этом процессе?' + ans_line('Дж'))
        e = f'Работа — площадь трапеции под отрезком: A = (p₁ + p₂)/2·(V₂ − V₁) = {ans} Дж.'
        wrong = [W(p2 * (V2 - V1)), W(p1 * (V2 - V1)), W(Fr(abs(p2 - p1) * (V2 - V1), 2))]
    else:
        pp = pick(rng, [100, 200, 300, 400])
        V1 = pick(rng, [1, 2, 3, 4])
        V2 = V1 + pick(rng, [1, 2, 4])
        p = {'kind': kind, 'p': pp, 'V1': V1, 'V2': V2}
        ans = _solve_gaswork(p)
        q = f'Одноатомный идеальный газ ({gas}) изобарно расширяется при давлении {pp} кПа от {V1} л до {V2} л. Какое количество теплоты получил газ?' + ans_line('Дж')
        e = f'Q = ΔU + A = (3/2)pΔV + pΔV = (5/2)pΔV = {ans} Дж.'
        wrong = [W(pp * (V2 - V1)), W(Fr(3, 2) * pp * (V2 - V1)), W(Fr(5, 2) * pp * V2)]
    return num_card('ph-ege-08-gas-work', q, ans, e, p, wrong)


def _solve_U(p):
    k = p['kind']
    if k == 'U':
        return A(Fr(3, 2) * Fr(p['nu']) * R_GAS * Fr(p['T']))
    if k == 'dU':
        return A(Fr(3, 2) * Fr(p['nu']) * R_GAS * abs(Fr(p['dT'])))
    if k == 'pV':
        return A(Fr(3, 2) * Fr(p['p']) * Fr(p['V']))
    if k == 'Qisochor':
        return A(Fr(p['Q']) / (Fr(3, 2) * Fr(p['nu']) * R_GAS))
    raise ValueError(k)


@proto('ph-ege-08-internal-energy', 'ЕГЭ', 8, 'Внутренняя энергия одноатомного идеального газа',
       invariant='U = (3/2)νRT = (3/2)pV; ΔU = (3/2)νRΔT; в изохорном процессе Q = ΔU',
       varies='газ (гелий, неон, аргон), что дано (ν и T, p и V, изменение температуры, теплота в изохоре), что найти',
       answer_rule='подстановка в U = (3/2)νRT или (3/2)pV; ΔT = Q/((3/2)νR) в изохоре',
       mistakes=['множитель 5/2 вместо 3/2', 'температура в °C', 'кПа и л не переведены'],
       solve=_solve_U, kes=['2.2.7'],
       fidelity=FID(8, answer_format='число, Дж, кДж или К', style=NUM_STYLE + '; R = 8,31 Дж/(моль·К)', scale='как в банке: 1–10 моль, 300–600 К, 1700 Дж на 2 моль', trap='множитель 3/2'))
def g_U(rng):
    kind = pick(rng, ['U', 'dU', 'pV', 'Qisochor'])
    gas, gasg, _ = pick(rng, GASES[:3])
    nu = pick(rng, [1, 2, 3, 4, 5, 10])
    if kind == 'U':
        T = pick(rng, [200, 300, 400, 500, 600])
        p = {'kind': kind, 'nu': nu, 'T': T}
        ans = _solve_U(p)
        q = f'Чему равна внутренняя энергия {nu} моль разреженного {gasg} при температуре {T} К? Газ считать идеальным.' + ans_line('Дж')
        e = f'U = (3/2)νRT = 1,5·{nu}·8,31·{T} = {ans} Дж.'
        wrong = [W(nu * R_GAS * T), W(Fr(5, 2) * nu * R_GAS * T), W(Fr(3, 2) * nu * T)]
    elif kind == 'dU':
        t1 = pick(rng, [27, 77, 127, 227])
        dT = pick(rng, [20, 50, 100, 200])
        down = rng.random() < 0.4
        p = {'kind': kind, 'nu': nu, 'dT': dT}
        ans = _solve_U(p)
        q = f'Разреженный {gas} в количестве {nu} моль {"охлаждают" if down else "нагревают"} от {t1} °С до {t1 - dT if down else t1 + dT} °С. На сколько {"уменьшилась" if down else "увеличилась"} внутренняя энергия газа?' + ans_line('Дж')
        e = f'ΔU = (3/2)νRΔT = 1,5·{nu}·8,31·{dT} = {ans} Дж.'
        wrong = [W(nu * R_GAS * dT), W(Fr(5, 2) * nu * R_GAS * dT), W(Fr(3, 2) * nu * R_GAS * (t1 + dT + 273))]
    elif kind == 'pV':
        pp = pick(rng, [100, 150, 200, 300, 400])
        V = pick(rng, [1, 2, 4, 5, 10, 20])
        p = {'kind': kind, 'p': pp, 'V': V}
        ans = _solve_U(p)
        q = f'Одноатомный идеальный газ ({gas}) занимает объём {V} л при давлении {pp} кПа. Чему равна его внутренняя энергия?' + ans_line('Дж')
        e = f'U = (3/2)pV = 1,5·{pp}·10³·{V}·10⁻³ = {ans} Дж.'
        wrong = [W(pp * V), W(Fr(5, 2) * pp * V), W(Fr(3, 2) * pp * V * 1000)]
    else:
        dT = pick(rng, [10, 20, 40, 50, 100])
        Qv = Fr(3, 2) * nu * R_GAS * dT
        p = {'kind': kind, 'nu': nu, 'Q': str(Qv)}
        ans = _solve_U(p)
        q = f'Разреженному {gasg.replace("гелия", "гелию").replace("неона", "неону").replace("аргона", "аргону")} в количестве {nu} моль в сосуде постоянного объёма сообщили количество теплоты {Q(Qv)} Дж. На сколько кельвинов повысилась температура газа?' + ans_line('К')
        e = f'Изохора: Q = ΔU = (3/2)νRΔT ⇒ ΔT = {Q(Qv)}/(1,5·{nu}·8,31) = {ans} К.'
        wrong = [W(Qv / (nu * R_GAS)), W(Qv / (Fr(5, 2) * nu * R_GAS)), W(Qv / nu)]
    return num_card('ph-ege-08-internal-energy', q, ans, e, p, wrong)


def _solve_engine(p):
    k = p['ask']
    Q1 = Fr(p['Q1']) if p.get('Q1') is not None else None
    if k == 'eta':
        return A(Fr(p['A']) / Q1 * 100)
    if k == 'A':
        return A(Q1 * Fr(p['eta']) / 100)
    if k == 'Q2':
        return A(Q1 * (1 - Fr(p['eta']) / 100))
    if k == 'Q1':
        return A(Fr(p['A']) / (Fr(p['eta']) / 100))
    if k == 'eta2':
        return A((1 - Fr(p['Q2']) / Q1) * 100)
    raise ValueError(k)


@proto('ph-ege-08-engine', 'ЕГЭ', 8, 'КПД тепловой машины: η = A/Q₁ = 1 − Q₂/Q₁',
       invariant='η = A/Qнагр = (Qнагр − Qхол)/Qнагр',
       varies='машина (тепловой двигатель, паровая турбина, двигатель автомобиля, рабочее тело), что дано (Q₁, A, Q₂, η в % или долях), что найти',
       answer_rule='η = A/Q₁ ·100 %; A = ηQ₁; Q₂ = Q₁ − A; Q₁ = A/η',
       mistakes=['η = A/Q₂', 'КПД в долях вместо процентов', 'Q₂ = ηQ₁'],
       solve=_solve_engine, kes=['2.2.9'],
       fidelity=FID(8, answer_format='число (%, Дж, кДж)', style=NUM_STYLE, scale='как в банке: 100 Дж и 60 Дж; КПД 8–50 %', trap='какая теплота в знаменателе'))
def g_engine(rng):
    who = pick(rng, ['тепловой двигатель', 'двигатель катера', 'паровая турбина', 'двигатель мотоцикла', 'газовая турбина', 'тепловая машина'])
    fem = who.split()[-1] in ('турбина', 'машина')
    ask = pick(rng, ['eta', 'A', 'Q2', 'Q1', 'eta2'])
    eta = pick(rng, [8, 10, 20, 25, 30, 40, 50, 60])
    Q1 = pick(rng, [100, 200, 250, 400, 500, 800, 1000, 1500, 2000])
    Av = Fr(Q1 * eta, 100)
    Q2 = Q1 - Av
    unit = pick(rng, ['Дж', 'кДж'])
    if not ok_dec(Av):
        raise Retry
    p = {'ask': ask, 'Q1': Q1, 'A': str(Av), 'eta': eta, 'Q2': str(Q2)}
    ans = _solve_engine(p)
    W_ = who[0].upper() + who[1:]
    if ask == 'eta':
        q = f'За один цикл {who} совершает полезную работу {Q(Av)} {unit}, при этом нагреватель передаёт рабочему телу {Q1} {unit} теплоты. Определите КПД.' + ans_line('%')
        wrong = [W(Fr(Q2, Q1) * 100), W(Av / Q2 * 100), W(Fr(Av, Q1))]
    elif ask == 'A':
        q = f'{W_} имеет КПД {eta} %. Нагреватель передаёт рабочему телу за цикл {Q1} {unit} теплоты. Какую полезную работу за цикл совершает {"она" if fem else "он"}?' + ans_line(unit)
        wrong = [W(Q2), W(Q1 * eta), W(Fr(Q1, eta))]
    elif ask == 'Q2':
        q = f'{W_} имеет КПД {eta} %. Нагреватель передаёт рабочему телу за цикл {Q1} {unit} теплоты. Сколько теплоты за цикл уходит к холодильнику?' + ans_line(unit)
        wrong = [W(Av), W(Q1 + Av), W(Fr(Q1 * (100 + eta), 100))]
    elif ask == 'Q1':
        q = f'Полезная работа, которую {who} совершает за цикл, равна {Q(Av)} {unit}, {"её" if fem else "его"} КПД {eta} %. Сколько теплоты за цикл передаёт рабочему телу нагреватель?' + ans_line(unit)
        wrong = [W(Av * eta / 100), W(Q2), W(Av + Q1)]
    else:
        q = f'За цикл нагреватель передаёт рабочему телу, которое приводит в действие {who.replace("тепловой двигатель", "тепловой двигатель")}, {Q1} {unit} теплоты, а к холодильнику уходит {Q(Q2)} {unit}. Определите КПД.' + ans_line('%')
        q = q.replace('приводит в действие тепловой двигатель', 'приводит в действие тепловой двигатель')
        wrong = [W(Fr(Q2) / Q1 * 100), W(Av / Q2 * 100), W(Q2 / Q1)]
    e = f'η = A/Q₁, A = Q₁ − Q₂: Q₁ = {Q1}, A = {Q(Av)}, Q₂ = {Q(Q2)} ({unit}), η = {eta} %. Ответ: {ans}.'
    return num_card('ph-ege-08-engine', q, ans, e, p, wrong)


def _solve_carnot(p):
    T1, T2 = Fr(p['T1']), Fr(p['T2'])
    k = p['ask']
    if k == 'eta':
        return A((1 - T2 / T1) * 100)
    if k == 'T1':
        return A(T2 / (1 - Fr(p['eta']) / 100) - (273 if p.get('cel') else 0))
    if k == 'T2':
        return A(T1 * (1 - Fr(p['eta']) / 100) - (273 if p.get('cel') else 0))
    if k == 'A':
        return A(Fr(p['Q1']) * (1 - T2 / T1))
    raise ValueError(k)


@proto('ph-ege-08-carnot', 'ЕГЭ', 8, 'Максимальный КПД (цикл Карно): η = 1 − Tх/Tн',
       invariant='ηmax = (Tн − Tх)/Tн, температуры абсолютные',
       varies='машина (идеальная тепловая машина, двигатель по циклу Карно), температуры в К или °C, что найти (η, Tн, Tх, работу за цикл)',
       answer_rule='подстановка в η = 1 − Tх/Tн с переводом в кельвины; A = ηQ₁',
       mistakes=['температуры в °C', 'η = Tх/Tн', 'η > 100 %'],
       solve=_solve_carnot, kes=['2.2.10'],
       fidelity=FID(8, answer_format='число (%, К, °С, Дж)', style=NUM_STYLE, scale='как в банке: Tн 400–1200 К, Tх 250–400 К', trap='абсолютная температура'))
def g_carnot(rng):
    ask = pick(rng, ['eta', 'T1', 'T2', 'A'])
    T1 = pick(rng, [400, 500, 600, 750, 800, 900, 1000, 1200])
    T2 = pick(rng, [t for t in (200, 250, 273, 300, 350, 400, 450, 500, 600) if t < T1])
    eta = (1 - Fr(T2, T1)) * 100
    if not ok_dec(eta, 1):
        raise Retry
    cel = rng.random() < 0.4
    f = (lambda T: f'{Q(Fr(T) - 273)} °С') if cel else (lambda T: f'{Q(T)} К')
    who = pick(rng, ['идеальной тепловой машины', 'идеальной тепловой машины, работающей по циклу Карно,', 'идеального теплового двигателя'])
    p = {'ask': ask, 'T1': T1, 'T2': T2, 'eta': str(eta), 'cel': cel}
    if ask == 'eta':
        ans = _solve_carnot(p)
        q = f'Температура нагревателя {who} {f(T1)}, температура холодильника {f(T2)}. Чему равен КПД машины?' + ans_line('%')
        wrong = [W(Fr(T2, T1) * 100), W(Fr(T1 - T2, T2) * 100), W((1 - Fr(T2 - 273, T1 - 273)) * 100) if cel and T2 != 273 else W(eta / 100)]
    elif ask == 'T1':
        ans = _solve_carnot(p)
        q = f'КПД {who} {Q(eta)} %, температура холодильника {f(T2)}. Какова температура нагревателя?' + ans_line('°С' if cel else 'К')
        wrong = [W(T2 * (1 + eta / 100)), W(Fr(T2) / (eta / 100)), W(T1 if cel else T1 - 273)]
    elif ask == 'T2':
        ans = _solve_carnot(p)
        q = f'КПД {who} {Q(eta)} %, температура нагревателя {f(T1)}. Какова температура холодильника?' + ans_line('°С' if cel else 'К')
        wrong = [W(T1 * eta / 100), W(T2 if cel else T2 - 273), W(T1 - eta)]
    else:
        Q1 = pick(rng, [100, 200, 400, 500, 1000, 2000])
        p['Q1'] = Q1
        ans = _solve_carnot(p)
        q = f'Температура нагревателя {who} {f(T1)}, холодильника {f(T2)}. За цикл рабочее тело получает от нагревателя {Q1} Дж. Какую работу машина совершает за цикл?' + ans_line('Дж')
        wrong = [W(Q1 * Fr(T2, T1)), W(Q1), W(Q1 * (1 - Fr(T2, T1)) * 100)]
    e = f'η = 1 − Tх/Tн, Tн = {T1} К, Tх = {T2} К, η = {Q(eta)} %. Ответ: {ans}.'
    return num_card('ph-ege-08-carnot', q, ans, e, p, wrong)


# ================================================================= ЗАДАНИЕ 9. Молекулярная физика: выберите все верные утверждения

def _solve_iso_many(p):
    ps = [Fr(x) for x in p['ps']]
    Ts = [Fr(x) for x in p['Ts']]
    V = [T / pp for T, pp in zip(Ts, ps)]      # V ~ T/p при ν = const
    out = []
    for i, s in enumerate(p['st']):
        k = s['k']
        a, b = s.get('i', 0) - 1, s.get('j', 0) - 1
        if k == 'Vratio':
            ok = V[a] / V[b] == Fr(s['v'])
        elif k == 'sameV':
            ok = len({V[x - 1] for x in range(s['i'], s['j'] + 1)}) == 1
        elif k == 'Uratio':
            ok = Ts[a] / Ts[b] == Fr(s['v'])
        elif k == 'heat_in':      # газ получал теплоту на переходе a→b (изотерма: при расширении; изохора: при нагревании; изобара: при нагревании)
            dU = Ts[b] - Ts[a]
            Aw = ps[a] * 0 + (V[b] - V[a])   # знак работы = знак ΔV
            if Ts[a] == Ts[b]:
                ok = V[b] > V[a]
            elif V[a] == V[b]:
                ok = dU > 0
            elif ps[a] == ps[b]:
                ok = dU > 0
            else:
                ok = dU > 0 and Aw > 0
            ok = ok == s['claim']
        elif k == 'work0':
            ok = (V[a] == V[b]) == s['claim']
        elif k == 'rho':
            ok = V[b] / V[a] == Fr(s['v'])      # ρa/ρb = Vb/Va
        else:
            raise ValueError(k)
        if ok:
            out.append(str(i + 1))
    return out


def _iso_states(rng):
    """Последовательность состояний: изотерма → изохора → изобара (или другой порядок); p в кПа, T в К."""
    T0 = pick(rng, [240, 288, 300, 360, 400, 480])
    p0 = pick(rng, [60, 90, 120, 150, 180, 240, 300])
    ps, Ts, kinds = [Fr(p0)], [Fr(T0)], []
    order = rng.sample(['T', 'V', 'p'], 3)
    for kind in order:
        n = rng.randint(1, 2)
        for _ in range(n):
            if kind == 'T':
                f = pick(rng, [Fr(2, 3), Fr(1, 2), Fr(3, 4), Fr(4, 3), Fr(3, 2), Fr(5, 4), Fr(5, 6)])
                ps.append(ps[-1] * f)
                Ts.append(Ts[-1])
            elif kind == 'V':
                f = pick(rng, [Fr(4, 3), Fr(3, 2), Fr(2), Fr(3, 4), Fr(1, 2), Fr(5, 4)])
                ps.append(ps[-1] * f)
                Ts.append(Ts[-1] * f)
            else:
                f = pick(rng, [Fr(4, 3), Fr(3, 2), Fr(2), Fr(3, 4), Fr(1, 2), Fr(5, 4)])
                ps.append(ps[-1])
                Ts.append(Ts[-1] * f)
            kinds.append(kind)
    if not all(ok_dec(x, 1) for x in ps) or not all(x.denominator == 1 and 120 <= x <= 1500 for x in Ts) or not all(20 <= x <= 800 for x in ps):
        raise Retry
    return ps, Ts, kinds


@proto('ph-ege-09-iso-table', 'ЕГЭ', 9, 'Изопроцессы по таблице состояний газа: объём, внутренняя энергия, теплообмен, работа',
       invariant='pV = νRT при ν = const; U ~ T; изотерма: pV = const, Q = A; изохора: A = 0, Q = ΔU; изобара: V ~ T',
       varies='газ (гелий, неон, аргон), число и порядок изопроцессов, давления и температуры (в °C или К); графики банка (p–T, V–T, p–V) заменены таблицей состояний',
       answer_rule='для каждого состояния V ~ T/p; каждое утверждение проверяется расчётом отношений и знаков ΔU, A',
       mistakes=['температура в °C в отношениях', 'в изотермическом процессе газ не обменивается теплом', 'в изохорном процессе газ совершает работу'],
       solve=_solve_iso_many, kes=['2.1.10', '2.1.12', '2.2.6', '2.2.7'],
       fidelity=FID(9, answer_format='последовательность номеров верных утверждений (2–3 цифры)', style=MANY_STYLE,
                    scale='как в банке: 5–7 состояний, давления 50–300 кПа, температуры 27–327 °С', trap='абсолютная температура; знак теплообмена в изотерме'))
def g_iso_many(rng):
    ps, Ts, kinds = _iso_states(rng)
    gas = pick(rng, ['гелий', 'неон', 'аргон'])
    n = len(ps)
    cel = rng.random() < 0.5
    Vs = [T / pp for T, pp in zip(Ts, ps)]
    pool = []
    for _ in range(3):
        a, b = rng.sample(range(n), 2)
        r = Vs[a] / Vs[b]
        if r != 1 and ok_dec(r):
            pool.append(_st_num(rng, r, f'Отношение объёмов газа V{a + 1}/V{b + 1} равно {{v}}.', {'k': 'Vratio', 'i': a + 1, 'j': b + 1}, f'V ~ T/p ⇒ {Q(r)}'))
        rU = Ts[a] / Ts[b]
        if rU != 1 and ok_dec(rU):
            pool.append(_st_num(rng, rU, f'Отношение внутренних энергий газа U{a + 1}/U{b + 1} равно {{v}}.', {'k': 'Uratio', 'i': a + 1, 'j': b + 1}, f'U ~ T ⇒ {Q(rU)}'))
    for idx, kd in enumerate(kinds):
        a, b = idx, idx + 1
        tr = rng.random() < 0.5
        if kd == 'T':
            got = Vs[b] > Vs[a]
            pool.append((f'На переходе {a + 1} → {b + 1} газ {"получал" if tr else "отдавал"} некоторое количество теплоты.', got == tr, {'k': 'heat_in', 'i': a + 1, 'j': b + 1, 'claim': tr},
                         'изотерма: Q = A, газ ' + ('расширяется' if got else 'сжимается')))
        if kd == 'V':
            pool.append((f'На переходе {a + 1} → {b + 1} работа газа равна нулю.', True, {'k': 'work0', 'i': a + 1, 'j': b + 1, 'claim': True}, 'объём постоянен'))
        if kd == 'p':
            pool.append((f'На переходе {a + 1} → {b + 1} работа газа равна нулю.', False, {'k': 'work0', 'i': a + 1, 'j': b + 1, 'claim': True}, 'объём менялся'))
    runs = [(i, j) for i in range(n) for j in range(i + 2, n) if len({Vs[x] for x in range(i, j + 1)}) == 1]
    if runs:
        i, j = pick(rng, runs)
        pool.append((f'Во всех состояниях с {i + 1}-го по {j + 1}-е газ занимал один и тот же объём.', True, {'k': 'sameV', 'i': i + 1, 'j': j + 1}, 'p/T = const'))
    i = rng.randrange(0, n - 2)
    j = i + 2
    if len({Vs[x] for x in range(i, j + 1)}) != 1:
        pool.append((f'Во всех состояниях с {i + 1}-го по {j + 1}-е газ занимал один и тот же объём.', False, {'k': 'sameV', 'i': i + 1, 'j': j + 1}, 'p/T меняется'))
    head = ('t, °С', [T - 273 for T in Ts]) if cel else ('T, К', Ts)
    q = (f'Разреженный газ ({gas}) неизменной массы последовательно переводили из одного равновесного состояния в другое; в каждом состоянии измеряли давление и температуру.\n'
         + table([('№ состояния', [str(i + 1) for i in range(n)]), ('p, кПа', ps), head]))
    return many_card('ph-ege-09-iso-table', rng, q, pool, {'ps': [str(x) for x in ps], 'Ts': [str(x) for x in Ts]},
                     tail='Выберите все верные утверждения, соответствующие результатам опытов. Газ считать идеальным.')


def _solve_curve(p):
    ts, Ts = [Fr(x) for x in p['ts']], [Fr(x) for x in p['Ts']]
    P, m = Fr(p['P']), Fr(p['m'])
    cool = p['cool']
    plateau = [i for i in range(len(Ts) - 1) if Ts[i] == Ts[i + 1]]
    tm = Ts[plateau[0]]
    t_start, t_end = ts[plateau[0]], ts[plateau[-1] + 1]
    s1 = abs(Ts[1] - Ts[0]) / (ts[1] - ts[0])                 # скорость изменения до фазового перехода
    s2 = abs(Ts[-1] - Ts[-2]) / (ts[-1] - ts[-2])             # после
    out = []
    for i, s in enumerate(p['st']):
        k = s['k']
        if k == 'tm':
            ok = Fr(s['v']) == tm
        elif k == 'state':
            t = Fr(s['t'])
            st = ('first' if t < t_start else ('both' if t < t_end else 'second')) if t != t_start and t != t_end else 'edge'
            ok = st == s['claim']
        elif k == 'dur':
            ok = (t_end - t_start > Fr(s['v'])) == s['more']
        elif k == 'cmp':
            # c ~ 1/(скорость изменения T) при постоянной мощности; first — фаза до перехода
            ok = ((1 / s1) > (1 / s2)) == s['claim'] if s1 != s2 else not s['claim']
        elif k == 'c1':
            ok = Fr(s['v']) == P * 60 / (m * s1)
        elif k == 'lam':
            ok = Fr(s['v']) == P * (t_end - t_start) * 60 / m
        else:
            raise ValueError(k)
        if ok:
            out.append(str(i + 1))
    return out


# (вещество, род., tпл, c твёрдого, c жидкого, λ) — близко к табличным значениям (для льда и свинца — справочные данные КИМ)
CURVE_SUBST = [('олово', 'олова', 232, 230, 250, 59000), ('свинец', 'свинца', 327, 130, 140, 25000), ('нафталин', 'нафталина', 80, 1300, 1700, 150000),
               ('лёд', 'льда', 0, 2100, 4200, 330000), ('цинк', 'цинка', 420, 400, 480, 112000)]


def _round_step(x):
    return Fr(round(x * 2), 2) if x >= 2 else Fr(round(x * 10), 10)


def _curve_combos():
    out = {}
    for sub in CURVE_SUBST:
        _, _, _, c1, c2, lam = sub
        for cool in (False, True):
            ca, cb = (c2, c1) if cool else (c1, c2)
            lst = []
            for dt in (1, 2, 5):
                for m in (Fr(1, 10), Fr(1, 5), Fr(1, 4), Fr(1, 2), 1, 2):
                    for P in (10, 20, 25, 40, 50, 100, 200, 250, 400, 500, 1000):
                        E = Fr(P * 60 * dt)
                        ra, rb, n2f = E / (ca * m), E / (cb * m), Fr(lam) * m / E
                        rmax, nmax = (15, 12) if sub[0] == 'лёд' else (150, 8)
                        if not (1 <= ra <= rmax and 1 <= rb <= rmax and 2 <= n2f <= nmax + Fr(1, 2)):
                            continue
                        r1, r2, n2 = _round_step(ra), _round_step(rb), round(n2f)
                        if ra >= 20:
                            r1, r2 = Fr(round(ra)), Fr(round(rb))
                        if abs(r1 - ra) / ra < Fr(8, 100) and abs(r2 - rb) / rb < Fr(8, 100) and abs(n2 - n2f) / n2f < Fr(1, 10) and 2 <= n2 <= nmax:
                            lst.append((dt, m, P, r1, r2, n2))
            out[(sub[0], cool)] = lst
    return out


CURVE_OK = _curve_combos()


@proto('ph-ege-09-heating-curve', 'ЕГЭ', 9, 'Нагревание и плавление (охлаждение и кристаллизация) по таблице t(τ)',
       invariant='при постоянной мощности теплообмена: на участке фазового перехода температура постоянна; скорость изменения температуры обратно пропорциональна теплоёмкости; '
                 'Q = Pτ = cmΔt = λm',
       varies='вещество (олово, свинец, парафин, нафталин, лёд, цинк), нагревание или охлаждение, мощность и масса, длительности участков, набор утверждений; '
              'график банка заменён таблицей температур через равные промежутки времени',
       answer_rule='по таблице: температура плавления — значение на «полке»; агрегатное состояние в момент — по участку; c = P·Δτ/(mΔt); λ = P·τпл/m',
       mistakes=['в начале полки вещество уже расплавлено', 'теплоёмкость больше там, где температура растёт быстрее', 'время плавления посчитано по числу точек'],
       solve=_solve_curve, kes=['2.2.4', '2.2.5'],
       fidelity=FID(9, answer_format='последовательность номеров верных утверждений (2–3 цифры)', style=MANY_STYLE,
                    scale='как в банке: измерения через 5 мин, 8–9 значений, «полка» 10–20 мин', trap='агрегатное состояние на полке; сравнение теплоёмкостей по наклону'))
def g_curve(rng):
    nom, gen, tm = pick(rng, CURVE_SUBST)[:3]
    cool = rng.random() < 0.4
    combos = CURVE_OK[(nom, cool)]
    if not combos:
        raise Retry
    dt, m, P, r1, r2, n2 = pick(rng, combos)     # мощность, масса, шаг подобраны так, что c и λ близки к табличным
    n1, n3 = rng.randint(2, 3), rng.randint(2, 3)
    Ts = []
    if not cool:
        start = tm - r1 * n1
        Ts = [start + r1 * k for k in range(n1)] + [tm] * (n2 + 1) + [tm + r2 * (k + 1) for k in range(n3)]
    else:
        start = tm + r1 * n1
        Ts = [start - r1 * k for k in range(n1)] + [tm] * (n2 + 1) + [tm - r2 * (k + 1) for k in range(n3)]
    ts = [dt * k for k in range(len(Ts))]
    # плато: индексы n1 .. n1+n2 (включительно)
    t_start, t_end = ts[n1], ts[n1 + n2]
    pl = [i for i in range(len(Ts) - 1) if Ts[i] == Ts[i + 1]]
    if ts[pl[0]] != t_start or ts[pl[-1] + 1] != t_end:
        raise Retry
    if cool and gen == 'льда':
        gen = 'воды'
    first = 'твёрдом' if not cool else 'жидком'
    second = 'жидком' if not cool else 'твёрдом'
    c1 = Fr(P * 60, 1) / (m * Fr(r1, dt))
    lam = Fr(P) * (t_end - t_start) * 60 / m
    pool = [_st_num(rng, tm, f'Температура {"плавления" if not cool else "кристаллизации"} {gen} в данных условиях равна {{v}} °С.', {'k': 'tm'}, f'«полка» при {tm} °С', dec=0)]
    if tm == 0:
        pool[-1] = (f'Температура {"плавления" if not cool else "кристаллизации"} {gen} в данных условиях равна 0 °С.', True, {'k': 'tm', 'v': '0'}, 'полка при 0 °С')
        pool.append((f'Температура {"плавления" if not cool else "кристаллизации"} {gen} в данных условиях равна {Q(Ts[0])} °С.', False, {'k': 'tm', 'v': str(Ts[0])}, 'полка при 0 °С'))
    tin = pick(rng, [t for t in ts if t_start < t < t_end] or [t_start])
    tafter = pick(rng, [t for t in ts if t > t_end])
    tbefore = pick(rng, [t for t in ts if t < t_start])
    pool += [(f'В момент {Q(tin)} мин {gen} находилось одновременно в {first} и {second} состояниях.'.replace(f' {gen} находилось', f' {"вещество" if True else gen} находилось'), True, {'k': 'state', 't': str(tin), 'claim': 'both'}, 'идёт фазовый переход'),
             (f'В момент {Q(tin)} мин вещество находилось только в {second} состоянии.', False, {'k': 'state', 't': str(tin), 'claim': 'second'}, 'идёт фазовый переход'),
             (f'В момент {Q(tafter)} мин вещество находилось только в {second} состоянии.', True, {'k': 'state', 't': str(tafter), 'claim': 'second'}, 'переход завершён'),
             (f'В момент {Q(tbefore)} мин вещество находилось только в {second} состоянии.', False, {'k': 'state', 't': str(tbefore), 'claim': 'second'}, 'переход ещё не начался')]
    dur = t_end - t_start
    thr = dur + pick(rng, [-dt, dt, 2 * dt])
    if thr > 0:
        more = rng.random() < 0.5
        pool.append((f'Процесс {"плавления" if not cool else "кристаллизации"} длился {"более" if more else "менее"} {Q(thr)} мин.', (dur > thr) == more, {'k': 'dur', 'v': str(thr), 'more': more}, f'длительность {Q(dur)} мин'))
    if r1 != Fr(r2):
        big = rng.random() < 0.5
        s1, s2 = Fr(r1, dt), Fr(r2, dt)
        pool.append((f'Удельная теплоёмкость вещества в {first} состоянии {"больше" if big else "меньше"}, чем в {second}.', ((1 / s1) > (1 / s2)) == big, {'k': 'cmp', 'claim': big},
                     'при постоянной мощности c ~ 1/(скорость изменения температуры)'))
    else:
        pool.append((f'Удельная теплоёмкость вещества в {first} и {second} состояниях одинакова.', True, {'k': 'cmp', 'claim': False}, 'одинаковая скорость изменения температуры'))
    if ok_dec(c1, 0):
        pool.append(_st_num(rng, c1, f'Удельная теплоёмкость вещества в {first} состоянии равна {{v}} Дж/(кг·К).', {'k': 'c1'}, f'c = PΔτ/(mΔt) = {Q(c1)} Дж/(кг·К)', dec=0))
    if ok_dec(lam, 0):
        pool.append(_st_num(rng, lam, f'Удельная теплота {"плавления" if not cool else "кристаллизации"} вещества равна {{v}} Дж/кг.', {'k': 'lam'}, f'λ = Pτ/m = {Q(lam)} Дж/кг', dec=0))
    mm = f'{Q(m * 1000)} г' if m < 1 else f'{Q(m)} кг'
    if not cool:
        q = (f'Твёрдый образец ({nom}) массой {mm} медленно нагревают в печи, подводя к нему постоянную мощность {P} Вт. {"Каждую минуту" if dt == 1 else f"Каждые {dt} мин"} измеряли температуру образца; результаты — в таблице.\n')
    else:
        q = (f'Жидкий образец ({nom.replace("лёд", "вода")}) массой {mm} медленно охлаждают, отводя от него постоянную мощность {P} Вт. {"Каждую минуту" if dt == 1 else f"Каждые {dt} мин"} измеряли температуру; результаты — в таблице.\n')
    q += table([('τ, мин', ts), ('t, °С', Ts)])
    return many_card('ph-ege-09-heating-curve', rng, q, pool, {'ts': [str(t) for t in ts], 'Ts': [str(T) for T in Ts], 'P': P, 'm': str(m), 'cool': cool},
                     tail='Выберите все верные утверждения, соответствующие результатам измерений.')


PSAT = {10: Fr(123, 100), 12: Fr(140, 100), 14: Fr(160, 100), 16: Fr(181, 100), 18: Fr(206, 100), 20: Fr(233, 100), 22: Fr(264, 100), 24: Fr(298, 100),
        26: Fr(336, 100), 28: Fr(378, 100), 30: Fr(424, 100)}


def _solve_hum(p):
    pv = Fr(p['pv'])
    t = p['t']
    ps = {int(k): Fr(v) for k, v in p['psat']}
    out = []
    for i, s in enumerate(p['st']):
        k = s['k']
        if k == 'phi_gt':
            ok = (pv / ps[t] * 100 > Fr(s['v'])) == s['gt']
        elif k == 'dew':   # роса выпадет при охлаждении до tc
            ok = (ps[s['tc']] < pv) == s['claim']
        elif k == 'comp':   # изотермическое сжатие в n раз: пар станет насыщенным (конденсация)
            ok = (pv * Fr(s['n']) >= ps[t]) == s['claim']
        elif k == 'heat':   # нагревание в закрытом сосуде: φ уменьшится
            ok = s['claim'] == 'down'
        elif k == 'phi_at':
            ok = (pv / ps[s['tc']] * 100 > Fr(s['v'])) == s['gt']
        else:
            raise ValueError(k)
        if ok:
            out.append(str(i + 1))
    return out


@proto('ph-ege-09-humidity', 'ЕГЭ', 9, 'Относительная влажность и насыщенный пар по таблице давлений насыщенного пара',
       invariant='φ = pпара/pнас(t)·100 %; при охлаждении до t, где pнас(t) < pпара, выпадает роса; изотермическое сжатие увеличивает pпара до pнас; '
                 'нагревание в закрытом сосуде уменьшает φ',
       varies='место (комната, класс, теплица, сосуд под поршнем), температура и парциальное давление пара, набор температур таблицы, утверждения',
       answer_rule='каждое утверждение проверяется сравнением pпара с pнас при нужной температуре',
       mistakes=['φ при нагревании растёт', 'роса выпадает при любом охлаждении', 'насыщенный пар при сжатии повышает давление'],
       solve=_solve_hum, kes=['2.1.13', '2.1.14'],
       fidelity=FID(9, answer_format='последовательность номеров верных утверждений (2–3 цифры)', style=MANY_STYLE + '; давления насыщенного пара заданы таблицей',
                    scale='как в банке: 10–30 °С, pнас 1,2–4,2 кПа', trap='точка росы; изменение φ при нагревании и сжатии'))
def g_humidity(rng):
    temps = sorted(rng.sample(list(PSAT), 6))
    t = pick(rng, temps[2:])
    phi = pick(rng, [30, 40, 45, 50, 60, 70, 80])
    pv = PSAT[t] * phi / 100
    if not ok_dec(pv, 2):
        raise Retry
    where = pick(rng, ['В комнате', 'В школьном классе', 'В теплице', 'В сосуде под поршнем', 'В закрытой лаборатории'])
    pool = []
    th = pick(rng, [30, 40, 50, 60, 70, 80])
    gt = rng.random() < 0.5
    real = pv / PSAT[t] * 100
    if abs(real - th) >= 3:
        pool.append((f'Относительная влажность воздуха {"больше" if gt else "меньше"} {th} %.', (real > th) == gt, {'k': 'phi_gt', 'v': th, 'gt': gt}, f'φ = {Q(real.limit_denominator(1000)) if ok_dec(real, 2) else "≈" + str(round(float(real)))} %'))
    for tc in rng.sample([x for x in temps if x < t], min(2, len([x for x in temps if x < t]))):
        cl = rng.random() < 0.5
        dew = PSAT[tc] < pv
        if abs(PSAT[tc] - pv) < pv / 20:      # без пограничных случаев (зазор ≥ 5 %)
            continue
        pool.append((f'При охлаждении воздуха до {tc} °С {"выпадет роса" if cl else "роса не выпадет"}.', dew == cl, {'k': 'dew', 'tc': tc, 'claim': cl}, f'pнас({tc} °С) = {Q(PSAT[tc])} кПа'))
    n = pick(rng, [n_ for n_ in (Fr(3, 2), 2, 3, Fr(5, 2)) if abs(pv * n_ - PSAT[t]) >= PSAT[t] / 20] or [None])
    if n is None:
        raise Retry
    cl = rng.random() < 0.5
    sat = pv * n >= PSAT[t]
    pool.append((f'При изотермическом уменьшении объёма в {raz(n)} {"начнётся" if cl else "не начнётся"} конденсация пара.', sat == cl, {'k': 'comp', 'n': str(n), 'claim': cl},
                 f'pпара станет {Q(pv * n) if ok_dec(pv * n, 3) else "≈"} кПа, pнас = {Q(PSAT[t])} кПа'))
    pool.append(('При нагревании воздуха в закрытом сосуде постоянного объёма относительная влажность уменьшится.', True, {'k': 'heat', 'claim': 'down'}, 'pнас растёт быстрее pпара'))
    pool.append(('При нагревании воздуха в закрытом сосуде постоянного объёма относительная влажность увеличится.', False, {'k': 'heat', 'claim': 'up'}, 'pнас растёт быстрее pпара'))
    tc = pick(rng, [x for x in temps if x != t])
    real2 = pv / PSAT[tc] * 100
    th2 = pick(rng, [40, 50, 60, 70, 80, 90])
    if abs(real2 - th2) >= 3 and real2 <= 95:
        gt2 = rng.random() < 0.5
        pool.append((f'Если температуру изменить до {tc} °С при неизменном парциальном давлении пара, относительная влажность станет {"больше" if gt2 else "меньше"} {th2} %.',
                     (real2 > th2) == gt2, {'k': 'phi_at', 'tc': tc, 'v': th2, 'gt': gt2}, f'φ ≈ {round(float(real2))} %'))
    q = (f'{where} при температуре {t} °С парциальное давление водяного пара равно {Q(pv)} кПа. Давление насыщенного водяного пара при разных температурах приведено в таблице.\n'
         + table([('t, °С', temps), ('pнас, кПа', [PSAT[x] for x in temps])]))
    return many_card('ph-ege-09-humidity', rng, q, pool, {'pv': str(pv), 't': t, 'psat': [[x, str(PSAT[x])] for x in temps]})


def _solve_vessels(p):
    n1, n2, V1, V2 = (Fr(p[k]) for k in ('n1', 'n2', 'V1', 'V2'))
    p1, p2 = n1 / V1, n2 / V2
    pm = (n1 + n2) / (V1 + V2)
    out = []
    for i, s in enumerate(p['st']):
        k = s['k']
        if k == 'pratio':
            ok = p1 / p2 == Fr(s['v'])
        elif k == 'Uratio':
            ok = n1 / n2 == Fr(s['v'])
        elif k == 'Ekeq':
            ok = s['claim']
        elif k == 'pmix':
            ok = pm / p1 == Fr(s['v'])
        elif k == 'nconc':
            ok = (n1 / V1) / (n2 / V2) == Fr(s['v'])
        else:
            raise ValueError(k)
        if ok:
            out.append(str(i + 1))
    return out


@proto('ph-ege-09-vessels', 'ЕГЭ', 9, 'Газы в двух сосудах при одинаковой температуре: давление, концентрация, энергия, соединение сосудов',
       invariant='p = nkT = νRT/V; средняя кинетическая энергия молекул зависит только от T; U = (3/2)νRT; после соединения при той же T p = (ν₁ + ν₂)RT/(V₁ + V₂)',
       varies='газы (гелий, неон, аргон), количества вещества и объёмы сосудов, утверждения (отношения давлений, концентраций, внутренних энергий, давление после соединения)',
       answer_rule='каждое утверждение проверяется расчётом отношений при одинаковой температуре',
       mistakes=['средняя энергия молекул зависит от сорта газа', 'давление после соединения — среднее арифметическое'],
       solve=_solve_vessels, kes=['2.1.8', '2.1.9', '2.1.10'],
       fidelity=FID(9, answer_format='последовательность номеров верных утверждений (2–3 цифры)', style=MANY_STYLE,
                    scale='как в банке и демоверсии: 1–3 моль, объёмы равны или отличаются в 2–3 раза', trap='средняя энергия молекул одинакова при одинаковой T'))
def g_vessels(rng):
    g1, g2 = rng.sample(['гелий', 'неон', 'аргон'], 2)
    n1, n2 = pick(rng, [1, 2, 3, 4]), pick(rng, [1, 2, 3, 4, 6])
    V1, V2 = pick(rng, [1, 2, 3]), pick(rng, [1, 2, 3])
    if n1 * V2 == n2 * V1 and rng.random() < 0.7:
        raise Retry
    rp = Fr(n1 * V2, n2 * V1)
    pool = []
    if ok_dec(rp):
        pool.append(_st_num(rng, rp, 'Отношение давления газа в первом сосуде к давлению во втором равно {v}.', {'k': 'pratio'}, f'p ~ ν/V ⇒ {Q(rp)}'))
    rU = Fr(n1, n2)
    if ok_dec(rU) and rU != 1:
        pool.append(_st_num(rng, rU, 'Отношение внутренней энергии газа в первом сосуде к внутренней энергии газа во втором равно {v}.', {'k': 'Uratio'}, f'U ~ ν ⇒ {Q(rU)}'))
    pool.append(('Средние кинетические энергии поступательного теплового движения молекул газов в сосудах одинаковы.', True, {'k': 'Ekeq', 'claim': True}, 'одинаковая температура'))
    pool.append((f'Средняя кинетическая энергия поступательного движения молекул {"аргона" if "аргон" in (g1, g2) else "неона"} больше, чем молекул второго газа.', False, {'k': 'Ekeq', 'claim': False}, 'Ē зависит только от T'))
    rn = Fr(n1 * V2, n2 * V1)
    if ok_dec(rn):
        pool.append(_st_num(rng, rn, 'Отношение концентраций молекул n₁/n₂ равно {v}.', {'k': 'nconc'}, f'n ~ ν/V ⇒ {Q(rn)}'))
    rm = Fr(n1 + n2, V1 + V2) / Fr(n1, V1)
    if ok_dec(rm) and rm != 1:
        pool.append(_st_num(rng, rm, 'Если соединить сосуды тонкой трубкой (температура прежняя), отношение установившегося давления к начальному давлению в первом сосуде будет равно {v}.', {'k': 'pmix'},
                            f'p = (ν₁ + ν₂)RT/(V₁ + V₂) ⇒ {Q(rm)}'))
    q = (f'В первом сосуде объёмом {V1 if V1 != V2 else ""}{"V" if V1 != V2 else "V"} находится {n1} моль разреженного газа ({g1}), во втором сосуде объёмом {V2 if V1 != V2 else ""}V — {n2} моль разреженного газа ({g2}). '
         f'Температуры газов одинаковы. Газы считать идеальными.').replace('объёмом 1V', 'объёмом V')
    return many_card('ph-ege-09-vessels', rng, q, pool, {'n1': n1, 'n2': n2, 'V1': V1, 'V2': V2}, tail='Выберите все верные утверждения.')


def _solve_cycle(p):
    ps, Vs = [Fr(x) for x in p['ps']], [Fr(x) for x in p['Vs']]
    T = [a * b for a, b in zip(ps, Vs)]          # T ~ pV
    out = []
    n = len(ps)
    for i, s in enumerate(p['st']):
        k = s['k']
        if k == 'Acycle':
            area = abs(sum(ps[j] * Vs[(j + 1) % n] - ps[(j + 1) % n] * Vs[j] for j in range(n))) / 2
            ok = Fr(s['v']) == area
        elif k == 'Tmax':
            ok = T[s['i'] - 1] == max(T)
        elif k == 'Q12':
            a, b = s['i'] - 1, s['i'] % n
            dU = Fr(3, 2) * (T[b] - T[a])
            Aw = (ps[a] + ps[b]) / 2 * (Vs[b] - Vs[a])
            ok = ((dU + Aw) > 0) == s['claim']
        elif k == 'dU':
            a, b = s['i'] - 1, s['i'] % n
            ok = ((T[b] - T[a]) > 0) == s['claim']
        elif k == 'Tratio':
            ok = T[s['i'] - 1] / T[s['j'] - 1] == Fr(s['v'])
        else:
            raise ValueError(k)
        if ok:
            out.append(str(i + 1))
    return out


@proto('ph-ege-09-cycle', 'ЕГЭ', 9, 'Циклический процесс одноатомного газа: работа за цикл, теплообмен, температура',
       invariant='T ~ pV при ν = const; работа за цикл — площадь цикла на pV-диаграмме; Q = ΔU + A, ΔU = (3/2)νRΔT = (3/2)Δ(pV)',
       varies='газ, координаты вершин прямоугольного цикла на pV-диаграмме (график заменён таблицей состояний), направление обхода, утверждения',
       answer_rule='для каждого участка ΔU = 1,5Δ(pV), A = pΔV; утверждение проверяется расчётом',
       mistakes=['в изохорном нагревании газ совершает работу', 'работа за цикл равна p·V одного состояния', 'максимальная температура в состоянии с максимальным давлением'],
       solve=_solve_cycle, kes=['2.1.12', '2.2.6', '2.2.7', '2.2.9'],
       fidelity=FID(9, answer_format='последовательность номеров верных утверждений (2–3 цифры)', style=MANY_STYLE + '; pV-диаграмма цикла заменена таблицей состояний',
                    scale='как в банке: 1 моль одноатомного газа, давления 100–400 кПа, объёмы 1–6 л', trap='знак теплоты на участках; максимум T при максимальном pV'))
def g_cycle(rng):
    p1, p2 = sorted(rng.sample([100, 150, 200, 300, 400], 2))
    V1, V2 = sorted(rng.sample([1, 2, 3, 4, 5, 6], 2))
    cw = rng.random() < 0.5
    pts = [(p1, V1), (p2, V1), (p2, V2), (p1, V2)] if cw else [(p1, V1), (p1, V2), (p2, V2), (p2, V1)]
    sh = rng.randrange(4)
    pts = pts[sh:] + pts[:sh]
    ps, Vs = [Fr(a) for a, _ in pts], [Fr(b) for _, b in pts]
    T = [a * b for a, b in pts]
    area = (p2 - p1) * (V2 - V1)
    pool = [_st_num(rng, area, 'Работа, совершённая газом за цикл, по модулю равна {v} Дж.', {'k': 'Acycle'}, f'площадь цикла {area} Дж', dec=0)]
    imax = T.index(max(T)) + 1
    ifake = pick(rng, [i for i in range(1, 5) if T[i - 1] != max(T)])
    pool += [(f'Температура газа максимальна в состоянии {imax}.', True, {'k': 'Tmax', 'i': imax}, 'максимально pV'),
             (f'Температура газа максимальна в состоянии {ifake}.', False, {'k': 'Tmax', 'i': ifake}, 'pV не максимально')]
    for i in rng.sample(range(1, 5), 2):
        a, b = i - 1, i % 4
        dU = Fr(3, 2) * (T[b] - T[a])
        Aw = ps[a] * (Vs[b] - Vs[a]) if ps[a] == ps[b] else 0
        Qv = dU + Aw
        cl = rng.random() < 0.5
        pool.append((f'На участке {i}–{b + 1} газ {"получает" if cl else "отдаёт"} теплоту.', (Qv > 0) == cl, {'k': 'Q12', 'i': i, 'claim': cl}, f'Q = ΔU + A = {Q(Qv)} Дж'))
        cl2 = rng.random() < 0.5
        pool.append((f'На участке {i}–{b + 1} внутренняя энергия газа {"увеличивается" if cl2 else "уменьшается"}.', ((T[b] - T[a]) > 0) == cl2, {'k': 'dU', 'i': i, 'claim': cl2}, 'U ~ pV'))
    a, b = rng.sample(range(4), 2)
    r = Fr(T[a], T[b])
    if r != 1 and ok_dec(r):
        pool.append(_st_num(rng, r, f'Отношение абсолютных температур газа T{a + 1}/T{b + 1} равно {{v}}.', {'k': 'Tratio', 'i': a + 1, 'j': b + 1}, f'T ~ pV ⇒ {Q(r)}'))
    gas = pick(rng, ['гелий', 'неон', 'аргон'])
    q = (f'Один моль одноатомного идеального газа ({gas}) совершает циклический процесс 1–2–3–4–1. На pV-диаграмме цикл имеет вид прямоугольника со сторонами, параллельными осям; '
         f'параметры газа в вершинах приведены в таблице (давление — в кПа, объём — в л).\n'
         + table([('Состояние', ['1', '2', '3', '4']), ('p, кПа', ps), ('V, л', Vs)]))
    return many_card('ph-ege-09-cycle', rng, q, pool, {'ps': [str(x) for x in ps], 'Vs': [str(x) for x in Vs]}, tail='Выберите все верные утверждения.')


# ================================================================= ЗАДАНИЕ 10. Молекулярная физика: изменение величин, соответствия

def _q_gas():
    k = 1.38e-23
    return {
        'давление газа': lambda p: p['nu'] * 8.31 * p['T'] / p['V'],
        'объём газа': lambda p: p['V'] + 0 * p['T'],
        'абсолютная температура газа': lambda p: p['T'] + 0 * p['V'],
        'концентрация молекул газа': lambda p: p['nu'] / p['V'],
        'внутренняя энергия газа': lambda p: 1.5 * p['nu'] * 8.31 * p['T'],
        'плотность газа': lambda p: p['nu'] * 0.004 / p['V'],
        'средняя кинетическая энергия теплового движения молекул': lambda p: 1.5 * k * p['T'],
        'среднеквадратичная скорость молекул': lambda p: math.sqrt(p['T']),
        'масса газа': lambda p: p['nu'] * 0.004 + 0 * p['T'],
    }


CM10 = {'gas': {'qty': _q_gas()}}

