def _q_carnot():
    return {'КПД машины': lambda p: 1 - p['T2'] / p['T1'],
            'работа газа за цикл': lambda p: p['Q1'] * (1 - p['T2'] / p['T1']),
            'количество теплоты, отданное холодильнику за цикл': lambda p: p['Q1'] * p['T2'] / p['T1'],
            'количество теплоты, полученное от нагревателя за цикл': lambda p: p['Q1']}


CM10['carnot'] = {'qty': _q_carnot()}


def _pm_carnot(rng):
    ch = pick(rng, [('T1', 'Температуру нагревателя повысили', Fr(5, 4)), ('T1', 'Температуру нагревателя понизили', Fr(4, 5)),
                    ('T2', 'Температуру холодильника понизили', Fr(4, 5)), ('T2', 'Температуру холодильника повысили', Fr(5, 4))])
    who = pick(rng, ['Идеальная тепловая машина работает по циклу Карно.', 'Тепловая машина работает по циклу Карно.', 'Идеальный тепловой двигатель работает по циклу Карно.'])
    text = f'{who} {ch[1]}, оставив неизменными температуру {"холодильника" if ch[0] == "T1" else "нагревателя"} и количество теплоты, получаемое газом от нагревателя за цикл. Как изменились при этом указанные величины?'
    cands = [n for n in CM10['carnot']['qty'] if n != 'количество теплоты, полученное от нагревателя за цикл']   # названная в условии неизменной — не спрашиваем
    return 'carnot', text, {'T1': 600.0, 'T2': 300.0, 'Q1': 1000.0}, {ch[0]: ch[2]}, cands, False


