def _vap(p):
    T = p['T']
    psat = 2300 * math.exp(0.06 * (T - 293))
    nv = min(p['ntot'], psat * p['V'] / (8.31 * T))
    return psat, nv


def _q_vapor():
    return {'давление пара': lambda p: _vap(p)[1] * 8.31 * p['T'] / p['V'],
            'масса пара': lambda p: _vap(p)[1],
            'относительная влажность воздуха': lambda p: _vap(p)[1] * 8.31 * p['T'] / p['V'] / _vap(p)[0],
            'концентрация молекул пара': lambda p: _vap(p)[1] / p['V'],
            'масса жидкости в сосуде': lambda p: p['ntot'] - _vap(p)[1],
            'плотность пара': lambda p: _vap(p)[1] / p['V']}


CM10['vapor'] = {'qty': _q_vapor()}


def _pm_vapor(rng):
    V0, T0 = 1.0, 293.0
    ns = 2300 * V0 / (8.31 * T0)
    case = pick(rng, ['sat_comp', 'sat_exp', 'unsat_comp', 'unsat_heat', 'unsat_cool'])
    if case == 'sat_comp':
        text = 'В сосуде под поршнем находятся вода и её насыщенный пар. Объём сосуда медленно уменьшают при постоянной температуре, часть пара при этом конденсируется.'
        base, mods, excl = {'V': V0, 'T': T0, 'ntot': ns * 3}, {'V': Fr(2, 3)}, ['масса жидкости в сосуде'] if rng.random() < 0.3 else []
    elif case == 'sat_exp':
        text = 'В сосуде под поршнем находятся вода и её насыщенный пар. Поршень медленно поднимают при постоянной температуре; вода в сосуде ещё остаётся.'
        base, mods, excl = {'V': V0, 'T': T0, 'ntot': ns * 3}, {'V': Fr(5, 4)}, []
    elif case == 'unsat_comp':
        phi, k = pick(rng, [(20, Fr(3, 2)), (25, 2), (30, Fr(3, 2)), (30, 2), (40, Fr(3, 2)), (20, 3), (25, 3), (15, 4)])
        text = f'В сосуде под поршнем находится влажный воздух с относительной влажностью {phi} %. Объём сосуда при постоянной температуре уменьшили в {raz(k)}.'
        base, mods, excl = {'V': V0, 'T': T0, 'ntot': ns * phi / 100}, {'V': 1 / Fr(k)}, ['масса жидкости в сосуде']
    elif case == 'unsat_heat':
        phi, d = pick(rng, [(40, 5), (50, 5), (60, 3), (50, 10), (70, 5), (30, 10)])
        text = f'Влажный воздух с относительной влажностью {phi} % находится в закрытом сосуде неизменного объёма. Сосуд нагрели на {d} °С.'
        base, mods, excl = {'V': V0, 'T': T0, 'ntot': ns * phi / 100}, {'T': Fr(293 + d, 293)}, ['масса жидкости в сосуде']
    else:
        phi, d = pick(rng, [(40, 3), (50, 3), (30, 5), (40, 5), (60, 2)])
        text = f'Влажный воздух с относительной влажностью {phi} % находится в закрытом сосуде неизменного объёма. Сосуд охладили на {d} °С (роса не выпала).'
        base, mods, excl = {'V': V0, 'T': T0, 'ntot': ns * phi / 100}, {'T': Fr(293 - d, 293)}, ['масса жидкости в сосуде']
    cands = [n for n in CM10['vapor']['qty'] if n not in excl]
    return 'vapor', text + ' Как изменились при этом указанные величины?', base, mods, cands, False


@proto('ph-ege-10-change-vapor', 'ЕГЭ', 10, 'Как изменятся величины для насыщенного и ненасыщенного пара, влажность',
       invariant='давление насыщенного пара зависит только от температуры; φ = p/pнас(T); при сжатии ненасыщенного пара p и φ растут, при нагревании в закрытом сосуде φ падает',
       varies='состояние пара (насыщенный над водой / ненасыщенный), процесс (изотермическое сжатие, расширение, нагревание, охлаждение без росы), спрашиваемые величины',
       answer_rule='модель: pнас(T) растёт с T; масса пара = min(вся вода, pнасV/(RT)·M)',
       mistakes=['давление насыщенного пара растёт при сжатии', 'при нагревании в закрытом сосуде влажность растёт'],
       solve=_solve_change(CM10), kes=['2.1.13', '2.1.14'],
       fidelity=FID(10, answer_format='две цифры 1/2/3', style=MATCH_STYLE, scale='качественно, как в банке («В сосуде под поршнем находятся вода и её насыщенный пар …»)',
                    trap='давление насыщенного пара не зависит от объёма'))
def g_change_vapor(rng):
    return _change_gen('ph-ege-10-change-vapor', CM10, rng, _pm_vapor)


def sci(x):
    """Число в виде «2·10⁻⁵» (мантисса ≤ 2 знаков после запятой)."""
    x = Fr(x)
    if x == 0:
        return '0'
    e = 0
    while abs(x) >= 10:
        x /= 10
        e += 1
    while abs(x) < 1:
        x *= 10
        e -= 1
    sup = str(e).translate(str.maketrans('-0123456789', '⁻⁰¹²³⁴⁵⁶⁷⁸⁹'))
    return Q(x) if e == 0 else f'{Q(x)}·10{sup}'


GAS_COEF = {'аргон': 40, 'гелий': 4, 'неон': 20}


def _gas_coef_q(qid, P, T):
    p0, V0, T0, M, m = P['p0'], P['V0'], P['T0'], P['M'], P['m']
    nu = m / M
    if qid == 'V':
        return nu * R_GAS * T / p0
    if qid == 'U':
        return Fr(3, 2) * nu * R_GAS * T
    if qid == 'rho':
        return p0 * M / (R_GAS * T)
    if qid == 'pV':
        return nu * R_GAS * T
    raise ValueError(qid)


def _solve_coef(p):
    P = {k: Fr(v) for k, v in p['P'].items()}
    out = {}
    for lab, qid in zip('АБ', p['left']):
        hits = []
        for rid, form, c in p['right']:
            c = Fr(c)
            ok = all((c * T if form == 'lin' else c / T) == _gas_coef_q(qid, P, T) for T in (Fr(200), Fr(300), Fr(450)))
            if ok:
                hits.append(rid)
        if len(hits) != 1:
            raise ValueError(f'{qid}: {hits}')
        out[lab] = hits[0]
    return out


COEF_NAMES = {'V': ('объём газа V(T)', 'м³/К', 'lin'), 'U': ('внутренняя энергия газа U(T)', 'Дж/К', 'lin'), 'rho': ('плотность газа ρ(T)', 'кг·К/м³', 'inv'),
              'pV': ('произведение давления газа на его объём pV(T)', 'Дж/К', 'lin')}


@proto('ph-ege-10-formula-coef', 'ЕГЭ', 10, 'Соответствие: величина ↔ формула зависимости от температуры (газ под лёгким поршнем)',
       invariant='при p = p₀ = const: V = νRT/p₀ ~ T, U = (3/2)νRT ~ T, ρ = p₀M/(RT) ~ 1/T; ν = pV/(RT) по начальному состоянию',
       varies='газ (аргон, гелий, неон), масса или начальные объём и температура, нагревание/охлаждение, пара величин, числовые коэффициенты формул-«ловушек»',
       answer_rule='найти ν по начальному состоянию, вычислить коэффициенты a = νR/p₀, c = 1,5νR, b = p₀M/R и сравнить с предложенными',
       mistakes=['в U забыт множитель 3/2', 'плотность ~ T', 'коэффициент посчитан без перевода литров'],
       solve=_solve_coef, kes=['2.1.10', '2.1.12'],
       fidelity=FID(10, answer_format='две цифры (номер формулы для величин А и Б)', style='Соответствие «ФИЗИЧЕСКИЕ ВЕЛИЧИНЫ — ФОРМУЛЫ» с числовыми коэффициентами, как в банке (аргон под поршнем, 10⁵ Па)',
                    scale='как в банке: p₀ = 10⁵ Па, V₀ = 9 л, T₀ = 450 К, коэффициенты 2·10⁻⁵ м³/К, 3 Дж/К', trap='множитель 3/2 и обратная зависимость плотности'))
def g_formula_coef(rng):
    gas = pick(rng, list(GAS_COEF))
    M = Fr(GAS_COEF[gas], 1000)
    p0 = Fr(10 ** 5)
    T0 = pick(rng, [300, 400, 450, 500, 600])
    V0 = Fr(pick(rng, [3, 6, 9, 12, 15, 24]), 1000)
    nu = p0 * V0 / (R_GAS * T0)
    m = nu * M
    P = {'p0': p0, 'V0': V0, 'T0': Fr(T0), 'M': M, 'm': m}
    left = rng.sample(['V', 'U', 'rho', 'pV'], 2)
    coef = {q: (_gas_coef_q(q, P, Fr(1)) if COEF_NAMES[q][2] == 'lin' else _gas_coef_q(q, P, Fr(1))) for q in left}
    for q in left:
        if COEF_NAMES[q][2] == 'inv':
            coef[q] = _gas_coef_q(q, P, Fr(1)) * 1
    if not all(ok_dec(c * 10 ** 7, 2) for c in coef.values()):
        raise Retry
    right = [(COEF_NAMES[q][2], coef[q], COEF_NAMES[q][1]) for q in left]
    # «ловушки»: тот же коэффициент с другой формой, коэффициент без 3/2, обратный
    traps = []
    for q in left:
        c = coef[q]
        traps += [('inv' if COEF_NAMES[q][2] == 'lin' else 'lin', c, COEF_NAMES[q][1]), (COEF_NAMES[q][2], c * Fr(2, 3) if q == 'U' else c * 2, COEF_NAMES[q][1])]
    traps = [t for t in traps if t not in right]
    right += rng.sample(traps, 2)
    if len({(f, c) for f, c, _ in right}) != 4:
        raise Retry
    rng.shuffle(right)
    rlist = [(str(i + 1), f, str(c)) for i, (f, c, u) in enumerate(right)]
    lett = 'abcd'
    rtext = [(f'{lett[i]}T' if f == 'lin' else f'{lett[i]}/T') + f', {lett[i]} = {sci(c)} {u}' for i, (f, c, u) in enumerate(right)]
    ans = {lab: str(right.index((COEF_NAMES[q][2], coef[q], COEF_NAMES[q][1])) + 1) for lab, q in zip('АБ', left)}
    heat = rng.random() < 0.5
    q = (f'Разреженный {gas} находится в открытом сверху вертикальном сосуде под лёгким подвижным поршнем; давление окружающего воздуха 10⁵ Па. '
         f'Начальный объём газа {Q(V0 * 1000)} л, начальная температура {T0} К. Газ медленно {"нагревают" if heat else "охлаждают"}, масса газа не меняется, трения нет. '
         f'Установите соответствие между физическими величинами, характеризующими газ, и формулами, выражающими их зависимость от абсолютной температуры T в условиях опыта. '
         f'К каждой позиции первого столбца подберите соответствующую позицию из второго столбца.')
    o = match_opts([COEF_NAMES[x][0] for x in left], rtext)
    e = f'ν = p₀V₀/(RT₀); ' + '; '.join(f'{COEF_NAMES[x][0]} = {rtext[int(ans[l]) - 1]}' for l, x in zip('АБ', left)) + '. Ответ: ' + ans['А'] + ans['Б'] + '.'
    return pcard('ph-ege-10-formula-coef', q, ans, e, k='match', o=o, p={'P': {k: str(v) for k, v in P.items()}, 'left': left, 'right': rlist})


FORMULA_SETS10 = {
    'isobar': ('Одноатомный идеальный газ в количестве ν моль изобарно нагревают на ΔT (R — универсальная газовая постоянная).', ('nu', 'dT'),
               [('работа газа', 'νRΔT', lambda p: p['nu'] * 8.31 * p['dT'], lambda p: 8.31 * p['nu'] * (p['dT'] + 300) - 8.31 * p['nu'] * 300),
                ('изменение внутренней энергии газа', '(3/2)νRΔT', lambda p: 1.5 * p['nu'] * 8.31 * p['dT'], lambda p: 1.5 * 8.31 * p['nu'] * (300 + p['dT']) - 1.5 * 8.31 * p['nu'] * 300),
                ('количество теплоты, полученное газом', '(5/2)νRΔT', lambda p: 2.5 * p['nu'] * 8.31 * p['dT'], lambda p: 1.5 * 8.31 * p['nu'] * p['dT'] + 8.31 * p['nu'] * p['dT'])],
               ['(3/2)νR/ΔT', '3νRΔT', 'νRΔT/2']),
    'melt': ('Твёрдое вещество массой m нагревают в печи постоянной мощности P. Сначала за время τ₁ его температура выросла на Δt, затем за время τ₂ оно полностью расплавилось при постоянной температуре.',
             ('m', 'P', 't1', 't2', 'dt'),
             [('удельная теплоёмкость вещества в твёрдом состоянии', 'Pτ₁/(mΔt)', lambda p: p['P'] * p['t1'] / (p['m'] * p['dt']), lambda p: (p['P'] * p['t1'] / p['dt']) / p['m']),
              ('удельная теплота плавления вещества', 'Pτ₂/m', lambda p: p['P'] * p['t2'] / p['m'], lambda p: (p['P'] * p['t2']) * (1 / p['m'])),
              ('количество теплоты, полученное веществом при плавлении', 'Pτ₂', lambda p: p['P'] * p['t2'], lambda p: p['m'] * (p['P'] * p['t2'] / p['m']))],
             ['Pτ₂/(mΔt)', 'Pτ₁/m', 'mΔt/(Pτ₁)']),
    'engine': ('За один цикл нагреватель передаёт рабочему телу тепловой машины теплоту Q₁, а рабочее тело передаёт холодильнику теплоту Q₂.', ('Q1', 'Q2'),
               [('работа, совершаемая за цикл', 'Q₁ − Q₂', lambda p: p['Q1'] - p['Q2'], lambda p: p['Q1'] * (1 - p['Q2'] / p['Q1'])),
                ('КПД машины', '1 − Q₂/Q₁', lambda p: 1 - p['Q2'] / p['Q1'], lambda p: (p['Q1'] - p['Q2']) / p['Q1'])],
               ['Q₂/Q₁', '1 − Q₁/Q₂', 'Q₁ + Q₂']),
    'isochor': ('Одноатомный идеальный газ в количестве ν моль в сосуде постоянного объёма V нагревают на ΔT (R — универсальная газовая постоянная).', ('nu', 'dT', 'V'),
                [('количество теплоты, полученное газом', '(3/2)νRΔT', lambda p: 1.5 * p['nu'] * 8.31 * p['dT'], lambda p: 1.5 * (p['nu'] * 8.31 * p['dT'] / p['V']) * p['V']),
                 ('изменение давления газа', 'νRΔT/V', lambda p: p['nu'] * 8.31 * p['dT'] / p['V'], lambda p: p['nu'] * 8.31 * (300 + p['dT']) / p['V'] - p['nu'] * 8.31 * 300 / p['V'])],
                ['(5/2)νRΔT', 'νRΔT', 'VΔT/(νR)']),
}


def _solve_formula10(p):
    return _solve_formula(p, FORMULA_SETS10)


@proto('ph-ege-10-formula', 'ЕГЭ', 10, 'Соответствие: физическая величина ↔ формула (изопроцессы, плавление, тепловая машина)',
       invariant='первый закон термодинамики для изопроцессов; Q = cmΔt = Pτ, Q = λm; η = A/Q₁, A = Q₁ − Q₂',
       varies='ситуация (изобарное/изохорное нагревание, нагрев и плавление в печи, тепловая машина), пара величин, формулы-«ловушки»',
       answer_rule='вывести формулы; проверка — численное совпадение с независимым расчётом',
       mistakes=['в изобарном процессе Q = (3/2)νRΔT', 'удельная теплота плавления делится на Δt'],
       solve=_solve_formula10, kes=['2.2.4', '2.2.5', '2.2.7', '2.2.9'],
       fidelity=FID(10, answer_format='две цифры (номер формулы для величин А и Б)', style='Соответствие «ФИЗИЧЕСКИЕ ВЕЛИЧИНЫ — ФОРМУЛЫ» как в банке',
                    scale='буквенные данные, как в банке (формулы ΔQ₁/(mΔt₁), ΔQ₂/m …)', trap='множители 3/2 и 5/2; деление на Δt'))
def g_formula10(rng):
    return g_formula(rng, FORMULA_SETS10, 'ph-ege-10-formula')


# ================================================================= ЗАДАНИЕ 11. Электростатика и постоянный ток (3.1.2, 3.2.1, 3.2.3, 3.2.8, 3.2.9)

K_C = 9 * 10 ** 9
E_CH = Fr(16, 10 ** 20)


def _solve_coulomb(p):
    k = p['kind']
    if k == 'scale':
        return A(Fr(p['F0']) * Fr(p['k1']) * Fr(p['k2']) / (Fr(p['kr']) ** 2 * Fr(p['eps'])))
    if k == 'num':
        q1, q2, r = Fr(p['q1']) * Fr(1, 10 ** 9), Fr(p['q2']) * Fr(1, 10 ** 9), Fr(p['r']) / 100
        return A(K_C * q1 * q2 / r ** 2 * 1000)
    if k == 'touch':
        q1, q2 = Fr(p['q1']), Fr(p['q2'])
        qn = (q1 + q2) / 2
        return A(abs(qn * qn / (q1 * q2)) if p['ask'] == 'ratio' else abs(Fr(p['F0']) * qn * qn / (q1 * q2)))
    raise ValueError(k)


@proto('ph-ege-11-coulomb', 'ЕГЭ', 11, 'Закон Кулона: сила взаимодействия точечных зарядов',
       invariant='F = k|q₁q₂|/(εr²); после соприкосновения одинаковых шариков заряд делится поровну: q = (q₁ + q₂)/2',
       varies='заряженные тела (шарики, пылинки, капли), кратности зарядов и расстояния, среда (керосин ε = 2, вода ε = 81 и т. п.), числа в нКл и см, соприкосновение шариков',
       answer_rule='F₂ = F₁·(k₁k₂)/(k_r²ε); F = kq₁q₂/r² с переводом нКл, см; после касания — новые заряды',
       mistakes=['r не в квадрате', 'при касании заряды складываются без деления', 'знаки зарядов не учтены при касании'],
       solve=lambda p: _solve_coulomb2(p), kes=['3.1.2'],
       fidelity=FID(11, answer_format='число (мН, мкН, Н или «в … раз(а)»)', style=NUM_STYLE + '; k = 9·10⁹ Н·м²/Кл² из справочных данных',
                    scale='как в банке: заряды нКл–мкКл, расстояния см, кратности 2–4', trap='квадрат расстояния; перераспределение заряда при касании'))
def g_coulomb(rng):
    kind = pick(rng, ['scale', 'scale', 'num', 'touch'])
    who = pick(rng, ['Два неподвижных точечных заряда', 'Две заряженные пылинки', 'Два маленьких заряженных шарика', 'Две заряженные капли масла'])
    if kind == 'scale':
        k1 = pick(rng, [Fr(1), Fr(2), Fr(3), Fr(1, 2), Fr(4)])
        k2 = pick(rng, [Fr(1), Fr(2), Fr(1, 2)])
        kr = pick(rng, [Fr(1), Fr(2), Fr(3), Fr(1, 2)])
        med = pick(rng, [(1, ''), (1, ''), (2, 'керосин (ε = 2)'), (81, 'воду (ε = 81)'), (3, 'жидкий диэлектрик с диэлектрической проницаемостью 3')])
        if k1 * k2 == 1 and kr == 1 and med[0] == 1:
            raise Retry
        F0 = pick(rng, [9, 12, 16, 18, 24, 36, 48, 81, 162, 324])
        unit = pick(rng, ['мН', 'мкН', 'нН'])
        p = {'kind': kind, 'F0': F0, 'k1': str(k1), 'k2': str(k2), 'kr': str(kr), 'eps': med[0]}
        ans = _solve_coulomb(p)
        parts = []
        if k1 != 1:
            parts.append(f'модуль одного из зарядов {chg(k1)}')
        if k2 != 1:
            parts.append(f'модуль {"другого" if k1 != 1 else "одного из"} заряд{"а" if k1 != 1 else "ов"} {chg(k2)}')
        if kr != 1:
            parts.append(f'расстояние между ними {chg(kr)}')
        if med[0] != 1:
            parts.append(f'поместить их в {med[1]}')
        jp = parts[0] if len(parts) == 1 else ', '.join(parts[:-1]) + ' и ' + parts[-1]
        q = f'{who} в вакууме взаимодействуют с силами, модуль которых {F0} {unit}. Каким станет модуль сил взаимодействия, если ' + jp + '?' + ans_line(unit)
        e = f'F ~ q₁q₂/(εr²) ⇒ F₂ = {F0}·{Q(k1)}·{Q(k2)}/({Q(kr)}²·{med[0]}) = {ans} {unit}.'
        wrong = [W(F0 * k1 * k2 / kr / med[0]), W(F0 * k1 * k2 * kr * kr / med[0]), W(F0 * k1 * k2 / kr ** 2)]
    elif kind == 'num':
        q1, q2 = pick(rng, [1, 2, 3, 4, 5, 6, 8, 10, 20]), pick(rng, [1, 2, 3, 4, 5, 10, 20])
        r = pick(rng, [1, 2, 3, 5, 6, 10, 20, 30])
        p = {'kind': kind, 'q1': q1, 'q2': q2, 'r': r}
        ans = _solve_coulomb(p)
        if Fr(ans.replace(',', '.')) > 100000:
            raise Retry
        q = f'{who} с зарядами {q1} нКл и {q2} нКл находятся в вакууме на расстоянии {r} см друг от друга. Каков модуль сил их взаимодействия?' + ans_line('мН')
        e = f'F = kq₁q₂/r² = 9·10⁹·{q1}·10⁻⁹·{q2}·10⁻⁹/({Q(Fr(r, 100))})² Н = {ans} мН.'
        wrong = [W(Fr(K_C * q1 * q2, 10 ** 18) / Fr(r, 100) * 1000), W(Fr(K_C * q1 * q2, 10 ** 18) / Fr(r * r) * 1000), W(Fr(ans.replace(',', '.')) * 1000)]
    else:
        q1 = pick(rng, [2, 4, 6, 8, 10, 12])
        q2 = pick(rng, [2, 4, 6, 8, 10, -2, -4, -6, 12])
        if q1 == q2 or q1 + q2 == 0:
            raise Retry
        ask = pick(rng, ['ratio', 'F'])
        F0 = pick(rng, [12, 16, 24, 32, 48, 64, 96])
        p = {'kind': kind, 'q1': q1, 'q2': q2, 'ask': ask, 'F0': F0}
        ans = _solve_coulomb(p)
        qn = Fr(q1 + q2, 2)
        base = (f'Два одинаковых маленьких металлических шарика имеют заряды {Q(q1)} нКл и {Q(q2)} нКл. Шарики привели в соприкосновение и развели на прежнее расстояние.')
        if ask == 'ratio':
            r = abs(qn * qn / (q1 * q2))
            if r == 1:
                raise Retry
            if r < 1:
                p['ask'] = 'inv'
                q = base + ' Во сколько раз уменьшился модуль сил их взаимодействия?' + ans_line(raz_=True)
                ans = A(1 / r)
            else:
                q = base + ' Во сколько раз увеличился модуль сил их взаимодействия?' + ans_line(raz_=True)
        else:
            q = base + f' До соприкосновения модуль сил взаимодействия был {F0} мкН. Каким он стал?' + ans_line('мкН')
        e = f'После касания заряд каждого шарика (q₁ + q₂)/2 = {Q(qn)} нКл; F ~ |q₁q₂| ⇒ ответ {ans}.'
        wrong = [W(Fr((q1 + q2) ** 2, abs(q1 * q2))), W(F0) if ask == 'F' else W(2), W(Fr(abs(q1 * q2), 1))]
    return num_card('ph-ege-11-coulomb', q, ans, e, p, wrong)


def _solve_coulomb2(p):
    if p['kind'] == 'touch' and p['ask'] == 'inv':
        q1, q2 = Fr(p['q1']), Fr(p['q2'])
        qn = (q1 + q2) / 2
        return A(abs(q1 * q2 / (qn * qn)))
    return _solve_coulomb(p)


def _solve_current(p):
    k = p['kind']
    if k == 'q':
        return A(Fr(p['I']) * Fr(p['t']))
    if k == 'I':
        return A(Fr(p['q']) / Fr(p['t']))
    if k == 'N':
        return A(Fr(p['I']) * Fr(p['t']) / E_CH / 10 ** Fr(p['e']))
    if k == 'table':
        ts, Is = [Fr(x) for x in p['ts']], [Fr(x) for x in p['Is']]
        return A(sum((Is[i] + Is[i + 1]) / 2 * (ts[i + 1] - ts[i]) for i in range(len(ts) - 1)))
    raise ValueError(k)


@proto('ph-ege-11-current', 'ЕГЭ', 11, 'Сила тока и заряд: I = Δq/Δt, число электронов, заряд по графику I(t)',
       invariant='q = It; N = q/e; при меняющемся токе заряд — площадь под графиком I(t)',
       varies='проводник/прибор (провод, спираль лампы, электролит, аккумулятор), числа и единицы (мА, мин), что найти (заряд, силу тока, число электронов); график заменён таблицей',
       answer_rule='подстановка в q = It с переводом минут и мА; N = It/e; площадь трапеций',
       mistakes=['минуты не переведены в секунды', 'N = I/e без времени', 'заряд по конечному значению тока'],
       solve=_solve_current, kes=['3.2.1'],
       fidelity=FID(11, answer_format='число (Кл, А, штук·10ⁿ)', style=NUM_STYLE + '; e = 1,6·10⁻¹⁹ Кл', scale='как в банке: токи 2–6 А, время секунды–минуты', trap='перевод единиц; площадь под графиком'))
def g_current(rng):
    kind = pick(rng, ['q', 'I', 'N', 'table'])
    # (объект, допустимый диапазон силы тока, А) — ток согласован с объектом
    where, Imin, Imax = pick(rng, [('По проводнику', Fr(1, 10), 10), ('Через спираль лампы накаливания', Fr(1, 10), 1), ('Через резистор', Fr(1, 10), 5),
                                   ('По обмотке электродвигателя', 1, 10), ('Через спираль электроплитки', 2, 8), ('Через светодиодный фонарик', Fr(1, 100), Fr(1, 2))])
    if kind == 'q':
        I = pick(rng, [Fr(2, 100), Fr(1, 10), Fr(1, 5), Fr(3, 10), Fr(1, 2), 1, 2, 3, 4, 5, 6])
        t, tu = pick(rng, [(10, 'с'), (20, 'с'), (1, 'мин'), (2, 'мин'), (5, 'мин'), (30, 'с')])
        ts = t * 60 if tu == 'мин' else t
        p = {'kind': kind, 'I': str(I), 't': ts}
        ans = _solve_current(p)
        q = f'{where} в течение {t} {tu} идёт постоянный ток {Q(I)} А. Какой электрический заряд перенесён по цепи за это время?' + ans_line('Кл')
        e = f'q = It = {Q(I)}·{ts} = {ans} Кл.'
        wrong = [W(I * t), W(Fr(ts) / I), W(I * ts * 60) if tu == 'с' else W(I * ts / 60)]
    elif kind == 'I':
        qq = pick(rng, [1, 2, 3, 6, 12, 30, 60, 90, 120, 240, 300, 600])
        t = pick(rng, [2, 3, 5, 10, 20, 30, 60, 120, 300])
        I = Fr(qq, t)
        p = {'kind': kind, 'q': qq, 't': t}
        ans = _solve_current(p)
        q = f'{where} за {t} с перенесён заряд {qq} Кл, ток был постоянным. Определите силу тока.' + ans_line('А')
        e = f'I = q/t = {qq}/{t} = {ans} А.'
        wrong = [W(qq * t), W(Fr(t, qq)), W(Fr(qq, t * 60))]
    elif kind == 'N':
        I = pick(rng, [Fr(8, 10), Fr(16, 10), Fr(32, 10), Fr(48, 10), Fr(16, 100), Fr(8, 100), Fr(32, 100)])
        t = pick(rng, [1, 2, 5, 10])
        N = I * t / E_CH
        exp = len(str(int(N))) - 1
        man = N / Fr(10) ** exp
        if not ok_dec(man, 2):
            raise Retry
        p = {'kind': kind, 'I': str(I), 't': t, 'e': exp}
        ans = _solve_current(p)
        q = f'{where} в течение {t} с идёт постоянный ток {Q(I)} А. Сколько электронов прошло за это время через сечение провода? Ответ дайте в единицах 10{str(exp).translate(str.maketrans("0123456789", "⁰¹²³⁴⁵⁶⁷⁸⁹"))}.' + ans_line(f'·10{str(exp).translate(str.maketrans("0123456789", "⁰¹²³⁴⁵⁶⁷⁸⁹"))}')
        e = f'N = It/e = {Q(I)}·{t}/(1,6·10⁻¹⁹) = {ans}·10^{exp}.'
        wrong = [W(man * 10), W(man / 10), W(I / E_CH / Fr(10) ** exp)]
    else:
        dt = pick(rng, [1, 2, 5])
        Is = [pick(rng, [0, 1, 2, 3, 4]) for _ in range(5)]
        I = Fr(max(Is))
        ts = [dt * k for k in range(5)]
        if sum(Is) == 0:
            raise Retry
        p = {'kind': kind, 'ts': ts, 'Is': Is}
        ans = _solve_current(p)
        q = (f'Сила тока в проводнике изменялась со временем; значения силы тока в разные моменты приведены в таблице, между этими моментами ток изменялся равномерно.\n'
             + table([('t, с', ts), ('I, А', Is)]) + f'\nКакой заряд прошёл через поперечное сечение проводника за время от 0 до {ts[-1]} с?' + ans_line('Кл'))
        e = f'Заряд — площадь под графиком I(t): сумма трапеций = {ans} Кл.'
        wrong = [W(Is[-1] * ts[-1]), W(max(Is) * ts[-1]), W(sum(Is) * dt)]
    if kind != 'table' and not (Imin <= I <= Imax):
        raise Retry
    return num_card('ph-ege-11-current', q, ans, e, p, wrong)


def _solve_series(p):
    Rs = [Fr(r) for r in p['Rs']]
    k = p['kind']
    if k == 'series':
        I = Fr(p['U0']) / Rs[p['i0']]
        return A(I * Rs[p['i1']] if p['ask'] == 'U' else I * sum(Rs))
    if k == 'parallel':
        U = Fr(p['I0']) * Rs[p['i0']]
        return A(U / Rs[p['i1']] if p['ask'] == 'I' else sum(U / r for r in Rs))
    if k == 'mixed':
        R1, R2, R3 = Rs
        I = Fr(p['Utot']) / (R1 + R2 * R3 / (R2 + R3))
        return A(I * R2 * R3 / (R2 + R3) / R3 if p['ask'] == 'I3' else I * R1)
    raise ValueError(k)


@proto('ph-ege-11-ohm-circuit', 'ЕГЭ', 11, 'Закон Ома для участка цепи: последовательное и параллельное соединение',
       invariant='I = U/R; при последовательном соединении ток общий, напряжения ~ R; при параллельном напряжение общее, токи ~ 1/R',
       varies='цепь (резисторы, лампы, реостат; показания вольтметра/амперметра — вместо фотографии цепи), сопротивления, что найти (напряжение, ток, общее напряжение)',
       answer_rule='найти общий ток (или напряжение) по известному элементу, затем искомую величину',
       mistakes=['напряжения при последовательном соединении делятся поровну', 'ток в параллельных ветвях одинаков', 'обратная пропорция'],
       solve=_solve_series, kes=['3.2.3', '3.2.7'],
       fidelity=FID(11, answer_format='число (В, А)', style=NUM_STYLE + '; фотография/схема цепи заменена словесным описанием соединения', scale='как в демоверсии 2027 (резистор 2 Ом, вольтметр) и банке: 1–30 Ом, 1–36 В',
                    trap='пропорциональность напряжений сопротивлениям при последовательном соединении'))
def g_series(rng):
    kind = pick(rng, ['series', 'series', 'parallel', 'mixed'])
    el = pick(rng, [('резистор', 'резисторов', 'резистора'), ('лампа', 'ламп', 'лампы')])
    if kind == 'series':
        Rs = rng.sample([1, 2, 3, 4, 5, 6, 8, 10, 12, 15, 20], rng.choice([2, 3]))
        i0, i1 = rng.sample(range(len(Rs)), 2)
        U0 = pick(rng, [1, 2, 3, 4, 5, 6, 8, 9, 10, 12])
        ask = pick(rng, ['U', 'U', 'Utot'])
        p = {'kind': kind, 'Rs': Rs, 'i0': i0, 'i1': i1, 'U0': U0, 'ask': ask}
        ans = _solve_series(p)
        names = ', '.join(f'R{i + 1} = {r} Ом' for i, r in enumerate(Rs))
        q = (f'Участок цепи состоит из последовательно соединённых резисторов сопротивлениями {names}. Идеальный вольтметр, подключённый к резистору R{i0 + 1}, показывает {U0} В. '
             + (f'Какое напряжение покажет вольтметр, если его подключить к резистору R{i1 + 1}?' if ask == 'U' else 'Каково напряжение на всём участке?') + ans_line('В'))
        e = f'I = {U0}/{Rs[i0]} А (ток общий); ответ {ans} В.'
        wrong = [W(Fr(U0 * Rs[i0], Rs[i1])), W(U0), W(Fr(U0, len(Rs)) * sum(Rs) / Rs[i0] * Rs[i1] * 2)]
    elif kind == 'parallel':
        Rs = rng.sample([2, 3, 4, 5, 6, 10, 12, 15, 20, 30], rng.choice([2, 3]))
        i0, i1 = rng.sample(range(len(Rs)), 2)
        I0 = pick(rng, [Fr(1, 2), 1, Fr(3, 2), 2, 3, 4, 6])
        ask = pick(rng, ['I', 'Itot'])
        p = {'kind': kind, 'Rs': Rs, 'i0': i0, 'i1': i1, 'I0': str(I0), 'ask': ask}
        ans = _solve_series(p)
        names = ', '.join(f'R{i + 1} = {r} Ом' for i, r in enumerate(Rs))
        q = (f'Резисторы сопротивлениями {names} соединены параллельно. Сила тока через резистор R{i0 + 1} равна {Q(I0)} А. '
             + (f'Какова сила тока через резистор R{i1 + 1}?' if ask == 'I' else 'Какова сила тока в неразветвлённой части цепи?') + ans_line('А'))
        e = f'Напряжение общее: U = {Q(I0)}·{Rs[i0]} = {Q(I0 * Rs[i0])} В; ответ {ans} А.'
        wrong = [W(I0 * Rs[i1] / Rs[i0]), W(I0), W(I0 * len(Rs))]
    else:
        R1 = pick(rng, [1, 2, 3, 4, 5, 6])
        R2, R3 = pick(rng, [(2, 2), (3, 6), (6, 3), (4, 4), (6, 6), (4, 12), (12, 4), (10, 10)])
        Utot = pick(rng, [6, 9, 12, 18, 24, 36])
        ask = pick(rng, ['I3', 'U1'])
        p = {'kind': kind, 'Rs': [R1, R2, R3], 'Utot': Utot, 'ask': ask}
        ans = _solve_series(p)
        q = (f'Резистор R1 = {R1} Ом соединён последовательно с двумя параллельно соединёнными резисторами R2 = {R2} Ом и R3 = {R3} Ом. На весь участок подано напряжение {Utot} В. '
             + ('Какова сила тока через резистор R3?' if ask == 'I3' else 'Каково напряжение на резисторе R1?') + ans_line('А' if ask == 'I3' else 'В'))
        e = f'R = R1 + R2R3/(R2 + R3); I = U/R; ответ {ans}.'
        wrong = [W(Fr(Utot, R3)), W(Fr(Utot, R1 + R2 + R3) * (R1 if ask == 'U1' else 1)), W(Fr(Utot, 3))]
    return num_card('ph-ege-11-ohm-circuit', q, ans, e, p, wrong)


def _net_R(net, r):
    if net[0] == 'r':
        return Fr(r)
    if net[0] == 's':
        return sum(_net_R(x, r) for x in net[1])
    return 1 / sum(1 / _net_R(x, r) for x in net[1])


NETS = [
    (('s', [('r',), ('p', [('r',), ('r',)])]), 'резистор, последовательно с ним — два параллельно соединённых резистора'),
    (('p', [('r',), ('s', [('r',), ('r',)])]), 'резистор, параллельно ему — два последовательно соединённых резистора'),
    (('p', [('r',), ('r',), ('r',)]), 'три резистора, соединённых параллельно'),
    (('s', [('p', [('r',), ('r',)]), ('p', [('r',), ('r',)])]), 'две последовательно соединённые пары, в каждой — два резистора параллельно'),
    (('p', [('s', [('r',), ('r',)]), ('s', [('r',), ('r',)])]), 'две параллельные ветви, в каждой — два резистора последовательно'),
    (('s', [('r',), ('r',), ('p', [('r',), ('r',), ('r',)])]), 'два резистора последовательно и с ними последовательно группа из трёх параллельных резисторов'),
    (('p', [('r',), ('s', [('r',), ('r',), ('r',)])]), 'резистор, параллельно ему — три последовательно соединённых резистора'),
]


def _solve_network(p):
    r = Fr(p['r'])
    R1 = _net_R(p['net'], r)
    if p['ask'] == 'R':
        return A(R1)
    R2 = _net_R(p['net2'], r)
    return A(abs(R1 - R2))


def _to_json(net):
    return [net[0]] + ([[_to_json(x) for x in net[1]]] if net[0] != 'r' else [])


def _from_json(j):
    return (j[0],) if j[0] == 'r' else (j[0], [_from_json(x) for x in j[1]])


@proto('ph-ege-11-network', 'ЕГЭ', 11, 'Сопротивление участка цепи из одинаковых резисторов; изменение при замыкании ключа',
       invariant='последовательно R = ΣRi; параллельно 1/R = Σ1/Ri; замкнутый ключ закорачивает участок',
       varies='схема (описана словами вместо рисунка), сопротивление одного резистора, вопрос (общее сопротивление или его изменение при добавлении/закорачивании)',
       answer_rule='свернуть схему по правилам соединения; разность сопротивлений до и после',
       mistakes=['параллельное соединение посчитано как последовательное', 'закороченный резистор оставлен в цепи'],
       solve=lambda p: _solve_network(dict(p, net=_from_json(p['net']), net2=_from_json(p['net2']) if p.get('net2') else None)), kes=['3.2.7'],
       fidelity=FID(11, answer_format='число, Ом', style=NUM_STYLE + '; схема участка описана словами', scale='как в банке: одинаковые резисторы 1–25 Ом, 3–8 штук',
                    trap='закорачивание ключом; вложенные соединения', kes='3.2.7 (последовательное и параллельное соединение; в плане 2027 для № 11 указаны 3.2.1, 3.2.3 — задания встречаются в банке этой линии)'))
def g_network(rng):
    net, desc = pick(rng, NETS)
    r = pick(rng, [1, 2, 3, 4, 5, 6, 10, 12, 15, 20, 24, 25, 30])
    ask = pick(rng, ['R', 'R', 'dR'])
    p = {'r': r, 'net': _to_json(net), 'ask': ask}
    if ask == 'R':
        q = f'Участок цепи АВ составлен из одинаковых резисторов сопротивлением {r} Ом каждый: {desc}. Каково сопротивление участка АВ?' + ans_line('Ом')
        ans = A(_net_R(net, r))
        wrong = [W(r * len(str(net).split("'r'")) - r), W(Fr(r, 3)), W(r * 2)]
    else:
        net2 = ('s', [net, ('r',)]) if rng.random() < 0.5 else ('p', [net, ('r',)])
        p['net2'] = _to_json(net2)
        how = 'последовательно подключить ещё один такой же резистор' if net2[0] == 's' else 'параллельно всему участку подключить ещё один такой же резистор'
        q = f'Участок цепи АВ составлен из одинаковых резисторов сопротивлением {r} Ом каждый: {desc}. На сколько изменится сопротивление участка, если {how}?' + ans_line('Ом')
        ans = A(abs(_net_R(net, r) - _net_R(net2, r)))
        wrong = [W(r), W(_net_R(net2, r)), W(_net_R(net, r))]
    e = f'Сворачиваем схему: R = {Q(_net_R(net, r))} Ом. Ответ: {ans} Ом.'
    if not all(ok_dec(x) for x in [_net_R(net, r)]):
        raise Retry
    return num_card('ph-ege-11-network', q, ans, e, p, wrong)


def _solve_power(p):
    k = p['kind']
    if k == 'lamp':
        P, U = Fr(p['P']), Fr(p['U'])
        return A(U * U / P if p['ask'] == 'R' else P / U)
    if k == 'fuse':
        return A(Fr(p['I']) * Fr(p['U']) / 1000)
    if k == 'energy':
        return A(Fr(p['P']) * Fr(p['t']) / 1000)
    if k == 'ratio':
        return A(Fr(p['R2']) / Fr(p['R1']) if p['conn'] == 'series' else Fr(p['R1']) / Fr(p['R2']))
    if k == 'IR':
        return A(Fr(p['I']) ** 2 * Fr(p['R']))
    raise ValueError(k)


@proto('ph-ege-11-power', 'ЕГЭ', 11, 'Работа и мощность тока: P = UI = I²R = U²/R, номинальные данные прибора, предохранитель',
       invariant='P = UI = I²R = U²/R; A = Pt; при последовательном соединении P ~ R, при параллельном P ~ 1/R',
       varies='прибор (лампа «60 Вт, 240 В», электрочайник, обогреватель, резисторы, предохранитель «30 А»), что найти (сопротивление, ток, мощность, работу, отношение мощностей)',
       answer_rule='выбор нужной формулы мощности; для отношений — по типу соединения',
       mistakes=['R = P/U', 'при параллельном соединении больше мощность на большем сопротивлении', 'кВт и Вт'],
       solve=_solve_power, kes=['3.2.8', '3.2.9'],
       fidelity=FID(11, answer_format='число (Ом, А, Вт, кВт, кДж)', style=NUM_STYLE, scale='как в банке: лампы 60–165 Вт на 220–240 В, предохранители 10–30 А', trap='выбор формулы мощности по типу соединения'))
def g_power(rng):
    kind = pick(rng, ['lamp', 'fuse', 'energy', 'ratio', 'IR'])
    if kind == 'lamp':
        P, U = pick(rng, [(60, 240), (100, 200), (40, 120), (25, 220), (48, 12), (36, 12), (24, 6), (60, 120), (75, 150), (200, 220)])
        ask = pick(rng, ['R', 'I'])
        dev = pick(rng, ['лампы накаливания', 'нагревательного элемента', 'паяльника', 'автомобильной лампы'])
        p = {'kind': kind, 'P': P, 'U': U, 'ask': ask}
        ans = _solve_power(p)
        q = (f'На корпусе {dev} указано: «{P} Вт, {U} В». Каково {"сопротивление прибора" if ask == "R" else "значение силы тока через прибор"} в рабочем режиме?'.replace('Каково значение', 'Каково значение') + ans_line('Ом' if ask == 'R' else 'А'))
        e = f'P = U²/R = UI ⇒ {"R = U²/P" if ask == "R" else "I = P/U"} = {ans}.'
        wrong = [W(Fr(P, U)) if ask == 'R' else W(Fr(U * U, P)), W(Fr(U, P)), W(Fr(P * U))]
    elif kind == 'fuse':
        I = pick(rng, [5, 6, 10, 16, 20, 25, 30, 40])
        U = pick(rng, [127, 220, 230, 380])
        p = {'kind': kind, 'I': I, 'U': U}
        ans = _solve_power(p)
        q = f'На плавком предохранителе, установленном в сети с напряжением {U} В, указано: «{I} А». Какую максимальную суммарную мощность могут иметь одновременно включённые в эту сеть приборы?' + ans_line('кВт')
        e = f'Pmax = UImax = {U}·{I} = {Q(U * I)} Вт = {ans} кВт.'
        wrong = [W(Fr(U, I)), W(U * I), W(Fr(U * U, I) / 1000)]
    elif kind == 'energy':
        P = pick(rng, [500, 800, 1000, 1200, 1500, 2000, 2200])
        t, tt = pick(rng, [(60, '1 мин'), (120, '2 мин'), (300, '5 мин'), (30, '30 с'), (600, '10 мин')])
        dev = pick(rng, ['Электрочайник', 'Утюг', 'Обогреватель', 'Фен', 'Микроволновая печь'])
        p = {'kind': kind, 'P': P, 't': t}
        ans = _solve_power(p)
        q = f'{dev} мощностью {P} Вт работает {tt}. Какую работу совершает за это время электрический ток?' + ans_line('кДж')
        e = f'A = Pt = {P}·{t} = {Q(P * t)} Дж = {ans} кДж.'
        wrong = [W(P * t), W(Fr(P, t)), W(Fr(P * t, 60000))]
    elif kind == 'ratio':
        R1, R2 = rng.sample([2, 3, 4, 5, 6, 8, 10, 12, 20], 2)
        conn = pick(rng, ['series', 'parallel'])
        r = Fr(R2, R1) if conn == 'series' else Fr(R1, R2)
        if r < 1:
            R1, R2 = R2, R1
            r = 1 / r
        if not ok_dec(r):
            raise Retry
        p = {'kind': kind, 'R1': R1, 'R2': R2, 'conn': conn}
        ans = _solve_power(p)
        q = (f'Два резистора сопротивлениями R1 = {R1} Ом и R2 = {R2} Ом соединены {"последовательно" if conn == "series" else "параллельно"} и подключены к источнику. '
             f'Чему равно отношение мощности тока во втором резисторе к мощности в первом P₂/P₁?' + ans_line())
        e = f'{"Ток общий: P = I²R, P₂/P₁ = R₂/R₁" if conn == "series" else "Напряжение общее: P = U²/R, P₂/P₁ = R₁/R₂"} = {ans}.'
        wrong = [W(1 / r), W(r * r), W(Fr(R1 + R2, R1))]
    else:
        I = pick(rng, [Fr(1, 2), 1, Fr(3, 2), 2, 3, 4, 5])
        R = pick(rng, [2, 4, 5, 8, 10, 20, 40, 50])
        p = {'kind': kind, 'I': str(I), 'R': R}
        ans = _solve_power(p)
        q = f'Сила тока в резисторе сопротивлением {R} Ом равна {Q(I)} А. Какая мощность выделяется в резисторе?' + ans_line('Вт')
        e = f'P = I²R = {Q(I)}²·{R} = {ans} Вт.'
        wrong = [W(I * R), W(I * I / R), W(R * R * I)]
    return num_card('ph-ege-11-power', q, ans, e, p, wrong)


def _solve_joule(p):
    k = p['kind']
    if k == 'Q':
        return A(Fr(p['I']) ** 2 * Fr(p['R']) * Fr(p['t']) / 1000)
    if k == 'ratio':
        return A(Fr(p['R1']) / Fr(p['R2']) if p['conn'] == 'series' else Fr(p['R2']) / Fr(p['R1']))
    if k == 'UQ':
        return A(Fr(p['U']) ** 2 / Fr(p['R']) * Fr(p['t']) / 1000)
    raise ValueError(k)


@proto('ph-ege-11-joule', 'ЕГЭ', 11, 'Закон Джоуля — Ленца: количество теплоты в проводнике',
       invariant='Q = I²Rt = U²t/R; при последовательном соединении Q ~ R, при параллельном Q ~ 1/R',
       varies='проводник (спираль плитки, резистор, нагревательный элемент, провод), ток или напряжение, время (с, мин), соединение двух резисторов',
       answer_rule='подстановка в Q = I²Rt или U²t/R; отношения по типу соединения',
       mistakes=['ток не в квадрате', 'минуты не переведены', 'при параллельном соединении Q ~ R'],
       solve=_solve_joule, kes=['3.2.8', '3.2.9'],
       fidelity=FID(11, answer_format='число (кДж или отношение)', style=NUM_STYLE, scale='как в банке: токи 1–5 А, сопротивления 2–100 Ом, время до 10 мин', trap='квадрат тока; тип соединения'))
def g_joule(rng):
    kind = pick(rng, ['Q', 'ratio', 'UQ'])
    if kind == 'Q':
        I = pick(rng, [1, 2, 3, 4, 5, Fr(1, 2)])
        R = pick(rng, [5, 10, 20, 25, 40, 50, 100])
        t, tt = pick(rng, [(10, '10 с'), (60, '1 мин'), (120, '2 мин'), (300, '5 мин'), (600, '10 мин')])
        who = pick(rng, ['спирали электроплитки', 'резисторе', 'нагревательном элементе', 'обмотке реостата'])
        p = {'kind': kind, 'I': str(I), 'R': R, 't': t}
        ans = _solve_joule(p)
        q = f'Какое количество теплоты выделится в {who} сопротивлением {R} Ом за {tt} при силе тока {Q(I)} А?' + ans_line('кДж')
        e = f'Q = I²Rt = {Q(I)}²·{R}·{t} = {Q(I * I * R * t)} Дж = {ans} кДж.'
        wrong = [W(I * R * t / 1000), W(I * I * R * t), W(I * I * R * (t // 60 if t >= 60 else t) / 1000)]
    elif kind == 'ratio':
        R1, R2 = rng.sample([2, 3, 4, 5, 6, 8, 10, 12, 20], 2)
        conn = pick(rng, ['series', 'parallel'])
        r = Fr(R1, R2) if conn == 'series' else Fr(R2, R1)
        if r < 1:
            R1, R2 = R2, R1
            r = 1 / r
        if not ok_dec(r):
            raise Retry
        p = {'kind': kind, 'R1': R1, 'R2': R2, 'conn': conn}
        ans = _solve_joule(p)
        q = (f'Два проводника сопротивлениями R1 = {R1} Ом и R2 = {R2} Ом соединены {"последовательно" if conn == "series" else "параллельно"} и подключены к источнику постоянного тока. '
             f'Каково отношение количеств теплоты Q₁/Q₂, выделившихся в них за одно и то же время?' + ans_line())
        e = f'{"Q = I²Rt, ток общий" if conn == "series" else "Q = U²t/R, напряжение общее"} ⇒ Q₁/Q₂ = {ans}.'
        wrong = [W(1 / r), W(r * r), W(Fr(R1 + R2, R2))]
    else:
        U = pick(rng, [6, 12, 20, 24, 36, 110, 220])
        R = pick(rng, [2, 4, 6, 10, 12, 20, 22, 44, 55, 110])
        t, tt = pick(rng, [(10, '10 с'), (60, '1 мин'), (100, '100 с'), (300, '5 мин')])
        p = {'kind': kind, 'U': U, 'R': R, 't': t}
        ans = _solve_joule(p)
        if Fr(ans.replace(',', '.')) > 5000:
            raise Retry
        q = f'На резистор сопротивлением {R} Ом подано постоянное напряжение {U} В. Какое количество теплоты выделится в резисторе за {tt}?' + ans_line('кДж')
        e = f'Q = U²t/R = {U}²·{t}/{R} = {ans} кДж·10³ Дж.'.replace(' кДж·10³ Дж', ' кДж')
        wrong = [W(Fr(U * t, R) / 1000), W(Fr(U * U * t, R)), W(Fr(U * U, R) / 1000)]
    return num_card('ph-ege-11-joule', q, ans, e, p, wrong)


# ================================================================= ЗАДАНИЕ 12. Магнитное поле, индукция (3.3.3, 3.3.4, 3.4.3, 3.4.6, 3.4.7)

def _solve_ampere(p):
    k = p['kind']
    if k == 'num':
        s = {90: Fr(1), 30: Fr(1, 2), 0: Fr(0)}[p['ang']]
        return A(Fr(p['B']) * Fr(p['I']) * Fr(p['L']) * s)
    if k == 'scale':
        r = Fr(p['kB']) * Fr(p['kI']) * Fr(p['kL'])
        return A(1 / r if p.get('inv') else r)
    if k == 'find':
        return A(Fr(p['F']) / (Fr(p['I']) * Fr(p['L'])))
    raise ValueError(k)


@proto('ph-ege-12-ampere', 'ЕГЭ', 12, 'Сила Ампера: FA = IBl·sinα, изменение силы',
       invariant='FA = IBl·sinα; при изменении I, B, l в k раз сила меняется пропорционально',
       varies='проводник (прямой провод, шина, стержень на рельсах, сторона рамки), числа (см, мТл), угол 90°/30°, кратности изменений, что найти (сила, индукция)',
       answer_rule='подстановка в F = IBl·sinα с переводом единиц; произведение кратностей',
       mistakes=['см не переведены', 'не учтён синус угла', 'кратности поделены вместо умножения'],
       solve=_solve_ampere, kes=['3.3.3'],
       fidelity=FID(12, answer_format='число (Н, мН, Тл или «в … раз(а)»)', style=NUM_STYLE, scale='как в демоверсии 2027 (длина ×4, индукция ÷2) и банке: 0,1–1 Тл, 1–20 А, 10–50 см',
                    trap='угол между проводником и линиями индукции'))
def g_ampere(rng):
    kind = pick(rng, ['num', 'scale', 'scale', 'find'])
    cond = pick(rng, ['Прямолинейный проводник', 'Медный стержень', 'Прямой участок провода', 'Алюминиевый стержень'])
    if kind == 'num':
        B = pick(rng, [Fr(1, 10), Fr(2, 10), Fr(1, 2), Fr(4, 100), 1, Fr(5, 100)])
        I = pick(rng, [1, 2, 4, 5, 10, 20])
        Lc = pick(rng, [10, 20, 25, 40, 50])
        ang = pick(rng, [90, 90, 30])
        p = {'kind': kind, 'B': str(B), 'I': I, 'L': str(Fr(Lc, 100)), 'ang': ang}
        ans = _solve_ampere(p)
        q = (f'{cond} длиной {Lc} см, по которому течёт ток {I} А, находится в однородном магнитном поле с индукцией {Q(B)} Тл; угол между проводником и линиями индукции {ang}°. '
             f'Каков модуль силы Ампера, действующей на проводник?' + ans_line('Н'))
        q = q.replace('Алюминиевая шина длиной', 'Алюминиевая шина длиной').replace('по которому течёт ток', 'по которой течёт ток' if cond.startswith('Алюминиевая') else 'по которому течёт ток')
        e = f'F = IBl·sinα = {I}·{Q(B)}·{Q(Fr(Lc, 100))}·sin{ang}° = {ans} Н.'
        wrong = [W(B * I * Lc), W(B * I * Fr(Lc, 100) * (1 if ang == 30 else Fr(1, 2))), W(B * I / Fr(Lc, 100))]
    elif kind == 'scale':
        kB = pick(rng, [Fr(1), Fr(2), Fr(3), Fr(1, 2), Fr(1, 3)])
        kI = pick(rng, [Fr(1), Fr(2), Fr(1, 2), Fr(4)])
        kL = pick(rng, [Fr(1), Fr(2), Fr(4), Fr(1, 2)])
        r = kB * kI * kL
        if r == 1 or sum(x != 1 for x in (kB, kI, kL)) < 2:
            raise Retry
        parts = ([f'индукцию магнитного поля {chg(kB)}'] if kB != 1 else []) + ([f'силу тока {chg(kI)}'] if kI != 1 else []) + ([f'длину проводника {chg(kL)}'] if kL != 1 else [])
        p = {'kind': kind, 'kB': str(kB), 'kI': str(kI), 'kL': str(kL), 'inv': r < 1}
        ans = _solve_ampere(p)
        q = (f'{cond} с током расположен в однородном магнитном поле перпендикулярно линиям индукции. Во сколько раз {"увеличится" if r > 1 else "уменьшится"} модуль силы Ампера, '
             f'если {parts[0] if len(parts) == 1 else ", ".join(parts[:-1]) + " и " + parts[-1]}? Взаимное расположение проводника и линий индукции не меняется.' + ans_line(raz_=True))
        e = f'F ~ IBl ⇒ F₂/F₁ = {Q(kB)}·{Q(kI)}·{Q(kL)} = {Q(r)}. Ответ: {ans}.'
        wrong = [W(kB * kL / kI), W(r * 2), W(1 / r if r > 1 else r)]
    else:
        B = pick(rng, [Fr(1, 10), Fr(2, 10), Fr(1, 2), Fr(1, 20), Fr(1, 4)])
        I = pick(rng, [2, 4, 5, 10])
        L = pick(rng, [Fr(1, 10), Fr(1, 5), Fr(1, 2)])
        F = B * I * L
        p = {'kind': kind, 'F': str(F), 'I': I, 'L': str(L)}
        ans = _solve_ampere(p)
        q = (f'На {cond.lower().replace("прямолинейный", "прямолинейный")} длиной {Q(L * 100)} см с током {I} А, расположенный перпендикулярно линиям индукции однородного магнитного поля, действует сила Ампера {Q(F)} Н. '
             f'Какова индукция поля?' + ans_line('Тл'))
        q = q.replace('На алюминиевая шина', 'На алюминиевую шину').replace('расположенный перпендикулярно', 'расположенную перпендикулярно' if 'шин' in q else 'расположенный перпендикулярно')
        e = f'B = F/(Il) = {Q(F)}/({I}·{Q(L)}) = {ans} Тл.'
        wrong = [W(F * I * L), W(F / I), W(F / (I * L * 100))]
    return num_card('ph-ege-12-ampere', q, ans, e, p, wrong)


def _solve_lorentz(p):
    k = p['kind']
    if k == 'num':
        return A(Fr(p['q']) * Fr(p['v']) * Fr(p['B']) * 10 ** 14)
    if k == 'radius':
        return A(Fr(p['km']) * Fr(p['kv']) / Fr(p['kq']))
    if k == 'period':
        return A(Fr(p['km']) / Fr(p['kq']))
    raise ValueError(k)


@proto('ph-ege-12-lorentz', 'ЕГЭ', 12, 'Сила Лоренца и движение заряженной частицы в магнитном поле',
       invariant='F = |q|υB·sinα; по окружности r = mυ/(|q|B), T = 2πm/(|q|B) — от скорости не зависит',
       varies='частица (протон, электрон, α-частица, ион), скорость и индукция, отношения масс/зарядов/скоростей двух частиц, что найти (сила, отношение радиусов, периодов)',
       answer_rule='подстановка в F = qυB; r₂/r₁ = (m₂/m₁)(υ₂/υ₁)/(q₂/q₁); T₂/T₁ = (m₂/m₁)/(q₂/q₁)',
       mistakes=['период зависит от скорости', 'радиус ~ q', 'степени десяти'],
       solve=_solve_lorentz, kes=['3.3.4'],
       fidelity=FID(12, answer_format='число (·10⁻¹⁴ Н, отношение)', style=NUM_STYLE + '; e = 1,6·10⁻¹⁹ Кл', scale='как в банке: две частицы с отношением масс/зарядов 2–8', trap='независимость периода от скорости'))
def g_lorentz(rng):
    kind = pick(rng, ['num', 'radius', 'radius', 'period'])
    if kind == 'num':
        part = pick(rng, [('Протон', 1), ('Электрон', 1), ('α-частица', 2), ('Однозарядный ион', 1)])
        v = pick(rng, [1, 2, 3, 4, 5, 10]) * 10 ** 6
        B = pick(rng, [Fr(1, 10), Fr(2, 10), Fr(1, 2), Fr(5, 100), 1])
        qch = part[1] * E_CH
        F = qch * v * B
        p = {'kind': kind, 'q': str(qch), 'v': v, 'B': str(B)}
        val = F * 10 ** 14
        if not ok_dec(val):
            raise Retry
        ans = A(val)
        p['scale'] = 14
        q = (f'{part[0]} влетает в однородное магнитное поле с индукцией {Q(B)} Тл со скоростью {v // 10 ** 6}·10⁶ м/с перпендикулярно линиям индукции. Каков модуль силы Лоренца, действующей на частицу? '
             f'Ответ выразите в единицах 10⁻¹⁴ Н.' + ans_line('·10⁻¹⁴ Н'))
        e = f'F = |q|υB = {part[1]}·1,6·10⁻¹⁹·{v // 10 ** 6}·10⁶·{Q(B)} = {ans}·10⁻¹⁴ Н.'
        wrong = [W(val / part[1]) if part[1] > 1 else W(val * 2), W(val * 10), W(val / 10)]
    elif kind == 'radius':
        km = pick(rng, [Fr(1), Fr(2), Fr(4), Fr(1, 2)])
        kq = pick(rng, [Fr(1), Fr(2), Fr(1, 2), Fr(4)])
        kv = pick(rng, [Fr(1), Fr(2), Fr(3), Fr(1, 2)])
        r = km * kv / kq
        if r <= 1 or sum(x != 1 for x in (km, kq, kv)) < 1 or not ok_dec(r):
            raise Retry
        p = {'kind': kind, 'km': str(km), 'kq': str(kq), 'kv': str(kv)}
        ans = _solve_lorentz(p)
        desc = []
        desc.append('одинаковыми массами' if km == 1 else f'массами m и {Q(km)}m')
        desc.append('одинаковыми зарядами' if kq == 1 else f'зарядами q и {Q(kq)}q')
        desc.append('одинаковыми скоростями' if kv == 1 else f'скоростями υ и {Q(kv)}υ')
        q = (f'Две частицы с {", ".join(desc)} (первое значение — для первой частицы) движутся в одном и том же однородном магнитном поле по окружностям в плоскости, перпендикулярной линиям индукции. '
             f'Чему равно отношение радиусов окружностей R₂/R₁?' + ans_line())
        e = f'R = mυ/(|q|B) ⇒ R₂/R₁ = {Q(km)}·{Q(kv)}/{Q(kq)} = {ans}.'
        wrong = [W(km * kq / kv), W(1 / r), W(km * kv * kq)]
    else:
        km = pick(rng, [Fr(1), Fr(2), Fr(4), Fr(8), Fr(1, 2)])
        kq = pick(rng, [Fr(1), Fr(2), Fr(1, 2), Fr(4)])
        r = km / kq
        if r <= 1 or not ok_dec(r):
            raise Retry
        kv = pick(rng, [2, 3, 4])
        p = {'kind': kind, 'km': str(km), 'kq': str(kq)}
        ans = _solve_lorentz(p)
        q = (f'Две частицы движутся по окружностям в одном и том же однородном магнитном поле. Масса второй частицы в {raz(km) if km > 1 else raz(1 / km)} {"больше" if km > 1 else "меньше"}, '
             f'{"заряды одинаковы" if kq == 1 else ("заряд в " + raz(kq if kq > 1 else 1 / kq) + (" больше" if kq > 1 else " меньше"))}, а скорость в {raz(kv)} больше, чем у первой. '
             f'Чему равно отношение периодов обращения T₂/T₁?'.replace('Масса второй частицы в 1 раз больше', 'Массы частиц одинаковы') + ans_line())
        e = f'T = 2πm/(|q|B) не зависит от скорости ⇒ T₂/T₁ = {Q(km)}/{Q(kq)} = {ans}.'
        wrong = [W(r * kv), W(r / kv), W(1 / r)]
    return num_card('ph-ege-12-lorentz', q, ans, e, p, wrong)


def _solve_faraday(p):
    k = p['kind']
    if k == 'dPhi':
        return A(Fr(p['N']) * abs(Fr(p['dF'])) / Fr(p['dt']))
    if k == 'table':
        ts, Fs = [Fr(x) for x in p['ts']], [Fr(x) for x in p['Fs']]
        i, j = ts.index(Fr(p['t1'])), ts.index(Fr(p['t2']))
        return A(abs(Fs[j] - Fs[i]) / (ts[j] - ts[i]) * Fr(p['N']) / 1000)
    if k == 'dB':
        return A(Fr(p['N']) * abs(Fr(p['dB'])) * Fr(p['S']) / Fr(p['dt']) / Fr(p['R']) if p['ask'] == 'I' else Fr(p['N']) * abs(Fr(p['dB'])) * Fr(p['S']) / Fr(p['dt']))
    raise ValueError(k)


@proto('ph-ege-12-faraday', 'ЕГЭ', 12, 'Закон электромагнитной индукции: ЭДС по изменению магнитного потока',
       invariant='|εi| = N·|ΔΦ|/Δt; Φ = BS·cosα; Ii = εi/R',
       varies='контур (рамка, катушка из N витков, кольцо), как задано изменение (ΔΦ за Δt, таблица Φ(t) вместо графика, изменение индукции при известной площади), '
              'что найти (ЭДС, индукционный ток)',
       answer_rule='ЭДС = NΔΦ/Δt на участке равномерного изменения; ток по закону Ома',
       mistakes=['не учтено число витков', 'мВб не переведены', 'ЭДС по значению потока, а не по его изменению'],
       solve=_solve_faraday, kes=['3.4.3'],
       fidelity=FID(12, answer_format='число (В, мВ, А)', style=NUM_STYLE + '; график Φ(t) заменён таблицей', scale='как в банке: потоки мВб, Δt 2–4 с (мс), N до 100', trap='участок с постоянным потоком — ЭДС ноль'))
def g_faraday(rng):
    kind = pick(rng, ['dPhi', 'table', 'dB'])
    if kind == 'dPhi':
        N = pick(rng, [1, 1, 10, 20, 50, 100, 200])
        dF = pick(rng, [Fr(1, 10), Fr(2, 10), Fr(1, 2), 1, 2, 3, 4, 6, 8, 12])   # мВб
        dt = pick(rng, [Fr(1, 100), Fr(1, 50), Fr(1, 10), Fr(1, 5), Fr(1, 2), 1, 2, 4])
        eps = N * dF / 1000 / dt
        if not ok_dec(eps, 3) or eps > 100:
            raise Retry
        p = {'kind': kind, 'N': N, 'dF': str(dF / 1000), 'dt': str(dt)}
        ans = _solve_faraday(p)
        who = 'через проволочную рамку' if N == 1 else f'через каждый виток катушки, содержащей {N} витков,'
        q = (f'Магнитный поток {who} равномерно {"уменьшился" if rng.random() < 0.5 else "увеличился"} на {Q(dF)} мВб за {Q(dt)} с. Каков модуль ЭДС индукции в {"рамке" if N == 1 else "катушке"}?' + ans_line('В'))
        e = f'|ε| = N|ΔΦ|/Δt = {N}·{Q(dF / 1000)}/{Q(dt)} = {ans} В.'
        wrong = [W(dF / 1000 / dt) if N > 1 else W(dF / dt), W(N * dF / dt), W(N * dF / 1000 * dt)]
    elif kind == 'table':
        dt = pick(rng, [1, 2, Fr(1, 2)])
        Fs = [0]
        for _ in range(5):
            Fs.append(Fs[-1] + pick(rng, [0, 2, 4, -2, -4, 6]))
        ts = [dt * k for k in range(6)]
        N = pick(rng, [1, 1, 10, 20])
        i = rng.randrange(0, 5)
        j = i + 1
        if Fs[j] == Fs[i]:
            raise Retry
        p = {'kind': kind, 'ts': [str(t) for t in ts], 'Fs': [str(f) for f in Fs], 't1': str(ts[i]), 't2': str(ts[j]), 'N': N}
        ans = _solve_faraday(p)
        q = (f'Магнитный поток через {"проволочную рамку" if N == 1 else f"каждый виток катушки из {N} витков"} меняется со временем; значения потока приведены в таблице, между указанными моментами поток менялся равномерно.\n'
             + table([('t, с', ts), ('Φ, мВб', Fs)]) + f'\nКаков модуль ЭДС индукции в {"рамке" if N == 1 else "катушке"} в промежутке времени от {Q(ts[i])} до {Q(ts[j])} с?' + ans_line('В'))
        e = f'|ε| = N|ΔΦ|/Δt = {N}·|{Fs[j]} − {Fs[i]}|·10⁻³/{Q(dt)} = {ans} В.'
        wrong = [W(Fr(abs(Fs[j]), 1000) / ts[j]) if ts[j] else W(1), W(Fr(abs(Fs[j] - Fs[i])) / dt * N), W(Fr(abs(Fs[j] - Fs[i]), 1000) * dt * N)]
    else:
        N = pick(rng, [1, 10, 50, 100])
        S = pick(rng, [Fr(1, 1000), Fr(2, 1000), Fr(5, 1000), Fr(1, 100)])
        dB = pick(rng, [Fr(1, 10), Fr(2, 10), Fr(1, 2), 1])
        dt = pick(rng, [Fr(1, 10), Fr(1, 5), Fr(1, 2), 1])
        R = pick(rng, [Fr(1, 10), Fr(1, 2), 1, 2, 5])
        ask = pick(rng, ['E', 'I'])
        p = {'kind': kind, 'N': N, 'S': str(S), 'dB': str(dB), 'dt': str(dt), 'R': str(R), 'ask': ask}
        ans = _solve_faraday(p)
        if Fr(ans.replace(',', '.')) == 0:
            raise Retry
        q = (f'{"Проволочная рамка" if N == 1 else f"Катушка из {N} витков"} площадью {Q(S * 10000)} см² расположена перпендикулярно линиям индукции однородного магнитного поля. '
             f'Индукция поля равномерно изменилась на {Q(dB)} Тл за {Q(dt)} с.'
             + (f' Сопротивление {"рамки" if N == 1 else "катушки"} {Q(R)} Ом. Какова сила индукционного тока?' if ask == 'I' else f' Каков модуль ЭДС индукции в {"рамке" if N == 1 else "катушке"}?')
             + ans_line('А' if ask == 'I' else 'В'))
        e = f'|ε| = NSΔB/Δt = {Q(N * S * dB / dt)} В' + (f'; I = ε/R = {ans} А.' if ask == 'I' else '.')
        wrong = [W(N * S * dB * dt), W(S * dB / dt), W(N * S * 10000 * dB / dt)]
    return num_card('ph-ege-12-faraday', q, ans, e, p, wrong)


def _solve_induct(p):
    k = p['kind']
    if k == 'Phi':
        return A(Fr(p['L']) * Fr(p['I']) * 1000)
    if k == 'L':
        return A(Fr(p['Phi']) / Fr(p['I']))
    if k == 'self':
        return A(Fr(p['L']) * Fr(p['dI']) / Fr(p['dt']))
    if k == 'Lself':
        return A(Fr(p['E']) * Fr(p['dt']) / Fr(p['dI']))
    raise ValueError(k)


@proto('ph-ege-12-inductance', 'ЕГЭ', 12, 'Индуктивность: Φ = LI, ЭДС самоиндукции',
       invariant='Φ = LI; |εsi| = L·|ΔI|/Δt',
       varies='катушка (катушка индуктивности, обмотка дросселя, соленоид, обмотка электромагнита), что дано и что найти (поток, индуктивность, ЭДС самоиндукции)',
       answer_rule='подстановка в Φ = LI или ε = LΔI/Δt с переводом мГн, мс',
       mistakes=['L = ΦI', 'ЭДС по значению тока, а не по изменению', 'мс не переведены'],
       solve=_solve_induct, kes=['3.4.6'],
       fidelity=FID(12, answer_format='число (мВб, Гн, В)', style=NUM_STYLE, scale='как в банке: L 0,1–1 Гн (мГн), токи 1–10 А, время 0,05–4 с', trap='изменение тока, а не значение'))
def g_induct(rng):
    kind = pick(rng, ['Phi', 'L', 'self', 'Lself'])
    coil = pick(rng, ['катушки индуктивности', 'обмотки дросселя', 'соленоида', 'обмотки электромагнита'])
    if kind == 'Phi':
        L = pick(rng, [Fr(1, 100), Fr(2, 100), Fr(5, 100), Fr(1, 10), Fr(2, 10), Fr(1, 2)])
        I = pick(rng, [1, 2, 3, 4, 5, 10])
        p = {'kind': kind, 'L': str(L), 'I': I}
        ans = _solve_induct(p)
        q = f'Индуктивность {coil} {Q(L * 1000)} мГн. Каков магнитный поток, пронизывающий {coil.split()[0].replace("катушки", "катушку").replace("обмотки", "обмотку").replace("соленоида", "соленоид")}, при силе тока {I} А?' + ans_line('мВб')
        e = f'Φ = LI = {Q(L)}·{I} = {Q(L * I)} Вб = {ans} мВб.'
        wrong = [W(L * I), W(L / I * 1000), W(L * I * I / 2 * 1000)]
    elif kind == 'L':
        I = pick(rng, [1, 2, 4, 5, 8, 10])
        Phi = pick(rng, [Fr(1, 10), Fr(2, 10), Fr(1, 2), 1, 2, 4])
        p = {'kind': kind, 'Phi': str(Phi), 'I': I}
        ans = _solve_induct(p)
        q = f'При силе тока {I} А магнитный поток через контур {coil} равен {Q(Phi)} Вб. Чему равна индуктивность?' + ans_line('Гн')
        e = f'L = Φ/I = {Q(Phi)}/{I} = {ans} Гн.'
        wrong = [W(Phi * I), W(Fr(I) / Phi), W(2 * Phi / I)]
    elif kind == 'self':
        L = pick(rng, [Fr(1, 1000), Fr(1, 100), Fr(1, 10), Fr(2, 10), Fr(1, 2), 1])
        dI = pick(rng, [1, 2, 4, 5, 10])
        dt = pick(rng, [Fr(1, 100), Fr(5, 100), Fr(1, 10), Fr(1, 2), 1, 2, 4])
        p = {'kind': kind, 'L': str(L), 'dI': dI, 'dt': str(dt)}
        ans = _solve_induct(p)
        if not ok_dec(Fr(ans.replace(',', '.')), 2) or Fr(ans.replace(',', '.')) > 1000:
            raise Retry
        q = f'Индуктивность {coil} {Q(L * 1000)} мГн. Ток в ней равномерно меняется так, что за {Q(dt)} с его значение изменяется на {dI} А. Определите модуль ЭДС самоиндукции.'.replace('Ток в ней', 'Ток в нём' if coil in ('соленоида', 'обмотки дросселя') else 'Ток в ней') + ans_line('В')
        e = f'|ε| = L|ΔI|/Δt = {Q(L)}·{dI}/{Q(dt)} = {ans} В.'
        wrong = [W(L * dI * dt), W(L / dt), W(L * 1000 * dI / dt)]
    else:
        E = pick(rng, [1, 2, 4, 5, 10, 20, 40])
        dI = pick(rng, [2, 4, 5, 10, 20])
        dt = pick(rng, [Fr(1, 10), Fr(1, 5), Fr(1, 2), 1])
        p = {'kind': kind, 'E': E, 'dI': dI, 'dt': str(dt)}
        ans = _solve_induct(p)
        q = f'Ток в {coil.replace("катушки индуктивности", "катушке").replace("обмотки", "обмотке").replace("соленоида", "соленоиде")} равномерно нарастает: за {Q(dt)} с он увеличивается на {dI} А, и при этом возникает ЭДС самоиндукции {E} В. Определите индуктивность.' + ans_line('Гн')
        e = f'L = εΔt/ΔI = {E}·{Q(dt)}/{dI} = {ans} Гн.'
        wrong = [W(E * dI / dt), W(Fr(E, dI)), W(E * dt * dI)]
    return num_card('ph-ege-12-inductance', q, ans, e, p, wrong)


def _solve_wmag(p):
    k = p['kind']
    if k == 'W':
        return A(Fr(p['L']) * Fr(p['I']) ** 2 / 2)
    if k == 'I':
        x = 2 * Fr(p['W']) / Fr(p['L'])
        r = math.isqrt(int(x)) if x.denominator == 1 else None
        return A(r) if r is not None and r * r == x else 'нет'
    if k == 'ratio':
        return A(Fr(p['kI']) ** 2 * Fr(p['kL']))
    if k == 'Wn':
        return A(Fr(p['W']) * (Fr(p['I2']) / Fr(p['I1'])) ** 2)
    raise ValueError(k)


@proto('ph-ege-12-mag-energy', 'ЕГЭ', 12, 'Энергия магнитного поля катушки: W = LI²/2',
       invariant='W = LI²/2; при изменении тока в k раз энергия меняется в k² раз',
       varies='катушка (катушка индуктивности, дроссель, обмотка электромагнита), числа (мГн, мДж), что найти (энергию, силу тока, энергию при новом токе, кратность)',
       answer_rule='подстановка в W = LI²/2; I = √(2W/L); W₂ = W₁(I₂/I₁)²',
       mistakes=['ток не в квадрате', 'забыто деление на 2', 'мГн не переведены'],
       solve=_solve_wmag, kes=['3.4.7'],
       fidelity=FID(12, answer_format='число (Дж, мДж, А или «в … раз(а)»)', style=NUM_STYLE, scale='как в банке: L 0,1–1 Гн, энергия 0,64 Дж и т. п.', trap='квадратичная зависимость от тока'))
def g_wmag(rng):
    kind = pick(rng, ['W', 'I', 'ratio', 'Wn'])
    coil = pick(rng, ['катушки индуктивности', 'дросселя', 'обмотки электромагнита', 'катушки'])
    if kind == 'W':
        L = pick(rng, [Fr(1, 10), Fr(2, 10), Fr(1, 2), 1, Fr(4, 10), Fr(5, 100)])
        I = pick(rng, [1, 2, 3, 4, 5, 6, 10])
        p = {'kind': kind, 'L': str(L), 'I': I}
        ans = _solve_wmag(p)
        q = f'Через обмотку {coil.replace("катушки индуктивности", "катушки").replace("обмотки электромагнита", "электромагнита")} идёт постоянный ток {I} А; индуктивность обмотки {Q(L * 1000) + " мГн" if L < 1 else Q(L) + " Гн"}. Определите энергию магнитного поля.' + ans_line('Дж')
        e = f'W = LI²/2 = {Q(L)}·{I}²/2 = {ans} Дж.'
        wrong = [W(L * I * I), W(L * I / 2), W(L * 1000 * I * I / 2)]
    elif kind == 'I':
        L = pick(rng, [Fr(1, 10), Fr(2, 10), Fr(1, 2), 1, 2])
        I = pick(rng, [1, 2, 3, 4, 5, 8, 10])
        Wv = L * I * I / 2
        p = {'kind': kind, 'L': str(L), 'W': str(Wv)}
        ans = _solve_wmag(p)
        if ans == 'нет':
            raise Retry
        q = f'Энергия магнитного поля {coil} индуктивностью {Q(L)} Гн равна {Q(Wv)} Дж. Какова сила тока в {coil.replace("катушки", "катушке").replace("дросселя", "дросселе").replace("обмотки", "обмотке")}?'.replace('катушки индуктивности индуктивностью', 'катушки индуктивностью').replace('катушке индуктивности?', 'катушке?') + ans_line('А')
        e = f'I = √(2W/L) = √(2·{Q(Wv)}/{Q(L)}) = {ans} А.'
        wrong = [W(2 * Wv / L), W(Wv / L), W(Fr(I, 2))]
    elif kind == 'ratio':
        kI = pick(rng, [Fr(2), Fr(3), Fr(1, 2), Fr(4)])
        kL = pick(rng, [Fr(1), Fr(1), Fr(2), Fr(1, 2)])
        r = kI * kI * kL
        if r <= 1:
            raise Retry
        p = {'kind': kind, 'kI': str(kI), 'kL': str(kL)}
        ans = _solve_wmag(p)
        parts = [f'силу тока в ней {chg(kI)}'] + ([f'индуктивность {chg(kL)}'] if kL != 1 else [])
        q = f'Во сколько раз увеличится энергия магнитного поля катушки, если ' + ' и '.join(parts) + '?' + ans_line(raz_=True)
        e = f'W ~ LI² ⇒ {Q(kL)}·{Q(kI)}² = {ans}.'
        wrong = [W(kI * kL), W(kI * kI), W(kI * kL * 2)]
    else:
        W0 = pick(rng, [Fr(16, 100), Fr(64, 100), 1, 2, 4, 8])
        I1, I2 = rng.sample([1, 2, 3, 4, 5, 6, 8, 10], 2)
        p = {'kind': kind, 'W': str(W0), 'I1': I1, 'I2': I2}
        ans = _solve_wmag(p)
        q = f'При силе тока {I1} А энергия магнитного поля {coil} равна {Q(W0)} Дж. Какой станет энергия поля, если силу тока {"увеличить" if I2 > I1 else "уменьшить"} до {I2} А?' + ans_line('Дж')
        e = f'W ~ I² ⇒ W₂ = {Q(W0)}·({I2}/{I1})² = {ans} Дж.'
        wrong = [W(W0 * Fr(I2, I1)), W(W0 * Fr(I1, I2) ** 2), W(W0 + I2 - I1)]
    return num_card('ph-ege-12-mag-energy', q, ans, e, p, wrong)


DIRS = {(1, 0, 0): 'вправо', (-1, 0, 0): 'влево', (0, 1, 0): 'вверх', (0, -1, 0): 'вниз', (0, 0, 1): 'к наблюдателю', (0, 0, -1): 'от наблюдателя'}
DIR_OF_FIELD = {(1, 0, 0): 'слева направо', (-1, 0, 0): 'справа налево', (0, 1, 0): 'снизу вверх', (0, -1, 0): 'сверху вниз', (0, 0, 1): 'к наблюдателю (из плоскости рисунка)',
                (0, 0, -1): 'от наблюдателя (за плоскость рисунка)'}


def _cross(a, b):
    return (a[1] * b[2] - a[2] * b[1], a[2] * b[0] - a[0] * b[2], a[0] * b[1] - a[1] * b[0])


def _solve_direction(p):
    v, B, s = tuple(p['v']), tuple(p['B']), p['sign']
    F = _cross(v, B)
    F = tuple(s * x for x in F)
    name = DIRS[F]
    return next(o['id'] for o in p['opts'] if o['t'] == name)


@proto('ph-ege-12-direction', 'ЕГЭ', 12, 'Направление силы Ампера и силы Лоренца (правило левой руки)',
       invariant='F⃗A = I·l⃗ × B⃗; F⃗Л = q·υ⃗ × B⃗; для отрицательной частицы направление противоположно',
       varies='объект (проводник с током, протон, электрон, α-частица, отрицательный ион), направления тока/скорости и линий индукции (рисунок заменён словами: вправо, вверх, к наблюдателю …)',
       answer_rule='векторное произведение направлений (правило левой руки) с учётом знака заряда; ответ — слово из списка',
       mistakes=['для электрона не изменено направление', 'сила направлена вдоль линий индукции'],
       solve=_solve_direction, kes=['3.3.3', '3.3.4'],
       fidelity=FID(12, answer_format='одно слово из списка (вправо, влево, вверх, вниз, к наблюдателю, от наблюдателя) — в банке ответ записывается словом',
                    style='Как в банке: «Как направлена относительно рисунка (вправо, влево, вверх, вниз, к наблюдателю, от наблюдателя) сила …»; рисунок заменён словами',
                    scale='качественно', trap='знак заряда частицы; правило левой руки',
                    kes='3.3.3, 3.3.4 (задания с ответом-словом из банка этой линии)'))
def g_direction(rng):
    axes = list(DIRS)
    v = pick(rng, axes)
    B = pick(rng, [a for a in axes if a != v and a != tuple(-x for x in v)])
    obj = pick(rng, [('Проводник с током', 1, 'Ток в проводнике направлен', 'сила Ампера, действующая на проводник'), ('Протон', 1, 'Скорость протона направлена', 'сила Лоренца, действующая на протон'),
                     ('Электрон', -1, 'Скорость электрона направлена', 'сила Лоренца, действующая на электрон'), ('α-частица', 1, 'Скорость α-частицы направлена', 'сила Лоренца, действующая на α-частицу'),
                     ('Отрицательный ион', -1, 'Скорость отрицательного иона направлена', 'сила Лоренца, действующая на ион')])
    names = list(DIRS.values())
    o = opts(names)
    p = {'v': list(v), 'B': list(B), 'sign': obj[1], 'opts': o}
    ans = _solve_direction(p)
    vd = DIRS[v]
    fld = pick(rng, [f'линии индукции однородного магнитного поля направлены {DIR_OF_FIELD[B]}', f'вектор индукции однородного магнитного поля направлен {DIR_OF_FIELD[B]}',
                     f'магнитное поле однородно, его линии индукции идут {DIR_OF_FIELD[B]}'])
    q = (f'{obj[2]} {vd if vd not in ("к наблюдателю", "от наблюдателя") else vd + " (перпендикулярно плоскости рисунка)"}, {fld}. '
         f'Как направлена относительно рисунка {obj[3]}?')
    F = tuple(obj[1] * x for x in _cross(v, B))
    e = f'По правилу левой руки{" для положительного заряда, затем противоположно (заряд отрицательный)" if obj[1] < 0 else ""}: {DIRS[F]}.'
    return pcard('ph-ege-12-direction', q, ans, e, k='one', o=o, p=p)


# ================================================================= ЗАДАНИЕ 13. Колебательный контур, оптика (3.5.1, 3.6.2, 3.6.3, 3.6.7)

def _solve_lc(p):
    k = p['kind']
    if k == 'ratio':
        r = Fr(p['kL']) * Fr(p['kC'])
        rt = Fr(math.isqrt(r.numerator), math.isqrt(r.denominator))
        if rt * rt != r:
            return 'нет'
        res = rt if p['what'] == 'T' else 1 / rt
        return A(1 / res if p.get('inv') else res)
    if k == 'newT':
        r = Fr(p['kL']) * Fr(p['kC'])
        rt = Fr(math.isqrt(r.numerator), math.isqrt(r.denominator))
        return A(Fr(p['X']) * (rt if p['what'] == 'T' else 1 / rt))
    if k == 'energy':
        return A(Fr(p['q']) ** 2 / (2 * Fr(p['C'])) * 10 ** 6 if p['ask'] == 'W' else Fr(p['q']) ** 2 / (2 * Fr(p['C'])) * 2 / Fr(p['L']))
    raise ValueError(k)


@proto('ph-ege-13-lc', 'ЕГЭ', 13, 'Колебательный контур: период T = 2π√(LC), частота, энергия',
       invariant='T = 2π√(LC), ν = 1/T; W = q²max/(2C) = LI²max/2',
       varies='контур (контур радиоприёмника, генератора, радиопередатчика, учебный контур), что меняют (L, C — в том числе заменой конденсатора/катушки), что найти (отношение, новый период/частоту, энергию)',
       answer_rule='T₂/T₁ = √((L₂/L₁)(C₂/C₁)), ν ~ 1/√(LC); W = q²/(2C)',
       mistakes=['без корня', 'частота изменена в ту же сторону, что период', 'мкФ не переведены'],
       solve=_solve_lc, kes=['3.5.1'],
       fidelity=FID(13, answer_format='число (мкс, кГц, мкДж или «в … раз(а)»)', style=NUM_STYLE, scale='как в банке: кратности 4, 9, 16; ёмкости мкФ, индуктивности мГн', trap='корень из произведения LC'))
def g_lc(rng):
    kind = pick(rng, ['ratio', 'newT', 'energy'])
    who = pick(rng, ['идеального колебательного контура', 'колебательного контура радиоприёмника', 'контура генератора', 'колебательного контура радиопередатчика'])
    if kind in ('ratio', 'newT'):
        kL = pick(rng, [Fr(1), Fr(4), Fr(1, 4), Fr(9), Fr(2), Fr(1, 2), Fr(16)])
        kC = pick(rng, [Fr(1), Fr(4), Fr(1, 4), Fr(9), Fr(2), Fr(1, 9), Fr(8)])
        r = kL * kC
        if kL == 1 and kC == 1 or r == 1:
            raise Retry
        rt = Fr(math.isqrt(r.numerator), math.isqrt(r.denominator))
        if rt * rt != r:
            raise Retry
        what = pick(rng, ['T', 'nu'])
        parts = ([f'индуктивность катушки {chg(kL)}'] if kL != 1 else []) + ([f'ёмкость конденсатора {chg(kC)}'] if kC != 1 else [])
        if kind == 'ratio':
            res = rt if what == 'T' else 1 / rt
            up = res > 1
            p = {'kind': kind, 'kL': str(kL), 'kC': str(kC), 'what': what, 'inv': not up}
            ans = _solve_lc(p)
            pp = ([f'катушку заменили другой, индуктивность которой в {raz(kL if kL > 1 else 1 / kL)} {"больше" if kL > 1 else "меньше"}'] if kL != 1 else []) + \
                 ([f'конденсатор заменили другим, ёмкость которого в {raz(kC if kC > 1 else 1 / kC)} {"больше" if kC > 1 else "меньше"}'] if kC != 1 else [])
            q = (f'В {who.replace("идеального колебательного контура", "идеальном колебательном контуре").replace("колебательного контура радиоприёмника", "колебательном контуре радиоприёмника").replace("контура генератора", "контуре генератора").replace("колебательного контура радиопередатчика", "колебательном контуре радиопередатчика")} '
                 f'{", а ".join(pp)}. Определите, во сколько раз {"возросла" if up and what == "nu" else ("возрос" if up else ("снизилась" if what == "nu" else "уменьшился"))} {"период" if what == "T" else "частота"} свободных электромагнитных колебаний.' + ans_line(raz_=True))
            e = f'T = 2π√(LC) ⇒ T₂/T₁ = √({Q(kL)}·{Q(kC)}) = {Q(rt)}; {"частота — обратно" if what == "nu" else ""}. Ответ: {ans}.'
            wrong = [W(r if up else 1 / r), W(1 / res if up else res), W(r * 2)]
        else:
            X = pick(rng, [1, 2, 4, 6, 8, 10, 12, 20]) if what == 'T' else pick(rng, [10, 20, 40, 60, 80, 100, 120])
            p = {'kind': kind, 'kL': str(kL), 'kC': str(kC), 'what': what, 'X': X}
            ans = _solve_lc(p)
            unit = 'мкс' if what == 'T' else 'кГц'
            q = (f'{"Период" if what == "T" else "Частота"} свободных электромагнитных колебаний {who} равн{"ен" if what == "T" else "а"} {X} {unit}. '
                 f'Затем {" и ".join(parts).replace("увеличить", "увеличили").replace("уменьшить", "уменьшили")}. Определите {"новый период" if what == "T" else "новую частоту"} колебаний.' + ans_line(unit))
            e = f'T ~ √(LC) ⇒ множитель √({Q(r)}) = {Q(rt)}. Ответ: {ans} {unit}.'
            wrong = [W(X * r if what == 'T' else X / r), W(X / rt if what == 'T' else X * rt), W(X)]
    else:
        C = pick(rng, [Fr(1, 10 ** 6), Fr(2, 10 ** 6), Fr(4, 10 ** 6), Fr(5, 10 ** 6), Fr(1, 10 ** 7)])
        qm = pick(rng, [1, 2, 3, 4, 5, 6, 10]) * Fr(1, 10 ** 6)
        ask = 'W'
        p = {'kind': kind, 'C': str(C), 'q': str(qm), 'ask': ask}
        ans = _solve_lc(p)
        q = (f'В {who.replace("идеального колебательного контура", "идеальном колебательном контуре").replace("колебательного контура радиоприёмника", "колебательном контуре радиоприёмника").replace("контура генератора", "контуре генератора").replace("колебательного контура радиопередатчика", "колебательном контуре радиопередатчика")} '
             f'ёмкость конденсатора {Q(C * 10 ** 6)} мкФ, максимальный заряд конденсатора {Q(qm * 10 ** 6)} мкКл. Какова полная энергия электромагнитных колебаний в контуре?' + ans_line('мкДж'))
        e = f'W = q²max/(2C) = ({sci(qm)})²/(2·{sci(C)}) Дж = {ans} мкДж.'
        wrong = [W(qm * qm / C * 10 ** 6), W(qm / (2 * C) * 10 ** 6), W(qm * qm * C / 2 * 10 ** 12)]
    return num_card('ph-ege-13-lc', q, ans, e, p, wrong)


def _solve_lc_table(p):
    ts, xs = [Fr(t) for t in p['ts']], [Fr(x) for x in p['xs']]
    zs = [ts[i] for i in range(len(xs) - 1) if xs[i] == 0 and xs[i + 1] > 0]
    T = zs[1] - zs[0] if len(zs) >= 2 else None
    if T is None:
        tops = [ts[i] for i, x in enumerate(xs) if x == max(xs)]
        T = tops[1] - tops[0]
    return A({'T': T * 10 ** 6, 'nu': 1 / T / 1000, 'A': max(xs)}[p['ask']])


@proto('ph-ege-13-lc-table', 'ЕГЭ', 13, 'Колебательный контур по таблице q(t) или i(t): период, частота, амплитуда',
       invariant='период — время между одинаковыми состояниями; ν = 1/T',
       varies='величина (заряд конденсатора, сила тока, напряжение), амплитуда, период (мкс), шаг таблицы, что найти; график банка заменён таблицей',
       answer_rule='по таблице: T — между двумя соседними переходами через ноль в одном направлении; ν = 1/T',
       mistakes=['полупериод принят за период', 'амплитуда — размах'],
       solve=_solve_lc_table, kes=['3.5.1'],
       fidelity=FID(13, answer_format='число (мкс, кГц, мкКл, мА, В)', style=NUM_STYLE + '; график заменён таблицей (как «В таблице показано, как менялся заряд …» в банке)',
                    scale='как в банке: периоды мкс, заряды нКл–мкКл', trap='полупериод vs период'))
def g_lc_table(rng):
    what = pick(rng, [('q, мкКл', 'заряд одной из обкладок конденсатора', 'мкКл'), ('i, мА', 'сила тока в катушке', 'мА'), ('u, В', 'напряжение на конденсаторе', 'В')])
    Amp = pick(rng, [1, 2, 3, 4, 5, 6, 8, 10, 12])
    dt = pick(rng, [1, 2, Fr(1, 2), 5])      # мкс
    n = 10
    ts = [dt * k for k in range(n)]
    pat = [0, 1, 0, -1]
    xs = [Amp * pat[k % 4] for k in range(n)]
    ask = pick(rng, ['T', 'nu', 'A'])
    T = 4 * dt
    if ask == 'nu' and not ok_dec(Fr(1000, T)):
        raise Retry
    p = {'ts': [str(t / 10 ** 6) for t in ts], 'xs': [str(x) for x in xs], 'ask': ask}
    ans = _solve_lc_table(p)
    q = (f'При свободных колебаниях в идеальном LC-контуре {what[1]} измеряли через равные промежутки времени; результаты приведены в таблице.\n'
         + table([('Время, мкс', ts), (what[0], xs)]) + '\n'
         + {'T': 'Чему равен период колебаний?', 'nu': 'Чему равна частота колебаний?', 'A': f'Чему равна амплитуда колебаний этой величины?'}[ask]
         + ans_line({'T': 'мкс', 'nu': 'кГц', 'A': what[2]}[ask]))
    e = f'Состояние повторяется через T = {Q(T)} мкс; ν = 1/T = {Q(Fr(1000, T))} кГц; амплитуда {Amp} {what[2]}. Ответ: {ans}.'
    wrong = [W(2 * dt) if ask != 'A' else W(2 * Amp), W(Fr(1000, 2 * dt)) if ask == 'nu' else W(8 * dt), W(T) if ask == 'nu' else W(Fr(1000, T))]
    return num_card('ph-ege-13-lc-table', q, ans, e, p, wrong)


def _solve_reflect(p):
    k = p['kind']
    a = Fr(p['a'])   # угол падения
    if k == 'between':
        return A(2 * a)
    if k == 'mirror_ray':
        return A(90 - a)
    if k == 'rotate':
        return A(2 * (a + Fr(p['d']) * p['s']))
    if k == 'from_mirror':
        return A(2 * (90 - Fr(p['g'])))
    raise ValueError(k)


@proto('ph-ege-13-reflection', 'ЕГЭ', 13, 'Закон отражения света: углы падения и отражения, поворот зеркала',
       invariant='угол отражения равен углу падения (от перпендикуляра); угол между лучами 2α; угол между лучом и зеркалом 90° − α; при повороте зеркала на β угол падения меняется на β',
       varies='как задан угол (падения, между лучами, между зеркалом и лучом), что найти (угол отражения, угол между лучами), поворот зеркала на заданный угол',
       answer_rule='переход к углу падения, затем закон отражения',
       mistakes=['угол отсчитан от зеркала, а не от перпендикуляра', 'при повороте зеркала на β угол между лучами меняется на β, а не на 2β'],
       solve=_solve_reflect, kes=['3.6.2'],
       fidelity=FID(13, answer_format='число, градусы', style=NUM_STYLE + '; рисунок поворота зеркала заменён словами', scale='как в демоверсии 2027 (70°, поворот на 10°) и банке', trap='отсчёт угла от нормали'))
def g_reflect(rng):
    kind = pick(rng, ['between', 'mirror_ray', 'rotate', 'from_mirror'])
    if kind == 'between':
        a = pick(rng, list(range(5, 86, 5)) + [12, 18, 24, 32, 36, 42, 48, 54, 62, 66, 72, 78])
        p = {'kind': kind, 'a': a}
        ans = _solve_reflect(p)
        q = f'{pick(rng, ["Луч света", "Луч лазерной указки", "Солнечный луч", "Узкий пучок света"])} падает на плоское зеркало под углом {a}° к перпендикуляру, восставленному к поверхности зеркала в точке падения. Чему равен угол между падающим и отражённым лучами?' + ans_line('градусов')
        e = f'Угол отражения равен углу падения: угол между лучами 2·{a}° = {ans}°.'
        wrong = [W(a), W(180 - 2 * a), W(90 - a)]
    elif kind == 'mirror_ray':
        a = pick(rng, list(range(10, 81, 5)) + [12, 16, 18, 22, 24, 28, 32, 36, 42, 44])
        p = {'kind': kind, 'a': a}
        ans = _solve_reflect(p)
        q = f'Угол между {pick(rng, ["падающим на плоское зеркало лучом", "лучом лазера, падающим на плоское зеркало,", "солнечным лучом, падающим на плоское зеркало,"])} и отражённым лучом равен {2 * a}°. Каков угол между отражённым лучом и плоскостью зеркала?' + ans_line('градусов')
        e = f'Угол отражения {a}°, угол с плоскостью зеркала 90° − {a}° = {ans}°.'
        wrong = [W(a), W(2 * a), W(180 - 2 * a)]
    elif kind == 'rotate':
        a = pick(rng, [15, 20, 25, 30, 35, 40, 45, 50, 55, 60])
        d = pick(rng, [5, 8, 10, 12, 15])
        s = pick(rng, [1, -1])
        p = {'kind': kind, 'a': a, 'd': d, 's': s}
        ans = _solve_reflect(p)
        q = (f'Свет падает на горизонтальное плоское зеркало; угол между падающим и отражённым лучами {2 * a}°. Зеркало поворачивают на {d}° так, что угол падения {"увеличивается" if s > 0 else "уменьшается"}, '
             f'направление падающего луча не меняется. Каким станет угол между падающим и отражённым лучами?' + ans_line('градусов'))
        e = f'Угол падения станет {a} {"+" if s > 0 else "−"} {d} = {a + s * d}°; угол между лучами {ans}°.'
        wrong = [W(2 * a + s * d), W(2 * a), W(a + s * d)]
    else:
        g = pick(rng, list(range(10, 81, 5)) + [12, 18, 24, 36, 42, 48, 54])
        p = {'kind': kind, 'a': 90 - g, 'g': g}
        ans = _solve_reflect(p)
        q = f'Угол между плоским зеркалом и падающим на него {pick(rng, ["лучом", "лучом лазерной указки", "солнечным лучом", "узким пучком света"])} равен {g}°. Каков угол между падающим и отражённым лучами?' + ans_line('градусов')
        e = f'Угол падения 90° − {g}° = {90 - g}°, между лучами 2·{90 - g}° = {ans}°.'
        wrong = [W(2 * g), W(90 - g), W(180 - 2 * g)]
    return num_card('ph-ege-13-reflection', q, ans, e, p, wrong)


def _solve_mirror(p):
    k = p['kind']
    if k == 'dist':
        return A(2 * Fr(p['d']))
    if k == 'move':
        return A(2 * Fr(p['s']))
    if k == 'speed':
        return A(2 * Fr(p['v']) if p['frame'] == 'obj' else Fr(p['v']))
    if k == 'mirror_move':
        return A(2 * Fr(p['s']))
    raise ValueError(k)


@proto('ph-ege-13-mirror-image', 'ЕГЭ', 13, 'Изображение в плоском зеркале: расстояния и скорости',
       invariant='изображение симметрично предмету относительно плоскости зеркала: расстояние предмет — изображение 2d; при сдвиге зеркала на s изображение смещается на 2s',
       varies='предмет (свеча, человек, точечный источник, шахматная фигура — клетки доски вместо рисунка), расстояния, перемещения предмета/зеркала, скорость',
       answer_rule='симметрия: расстояние до изображения = расстоянию до зеркала; относительная скорость предмета и изображения 2υ',
       mistakes=['расстояние предмет — изображение равно d', 'при сдвиге зеркала изображение смещается на s'],
       solve=_solve_mirror, kes=['3.6.3'],
       fidelity=FID(13, answer_format='число (см, м, клетки, м/с)', style=NUM_STYLE + '; рисунок заменён описанием', scale='как в банке: шахматная доска, источник на расстоянии 25–75 см', trap='удвоение расстояний и скоростей'))
def g_mirror(rng):
    kind = pick(rng, ['dist', 'move', 'speed', 'mirror_move'])
    obj = pick(rng, [('Свеча', 'свечи'), ('Точечный источник света', 'источника'), ('Человек', 'человека'), ('Ваза', 'вазы'), ('Лампа', 'лампы'), ('Кукла', 'куклы')])
    if kind == 'dist':
        d = pick(rng, [12, 15, 18, 20, 25, 30, 35, 40, 45, 50, 60, 75, 80, 90, 120])
        p = {'kind': kind, 'd': d}
        ans = _solve_mirror(p)
        q = f'Расстояние от {obj[1]} до плоского зеркала {d} см. На каком расстоянии от {obj[1]} находится {"его" if obj[1] in ("источника", "человека") else "её"} изображение в зеркале?' + ans_line('см')
        e = f'Изображение на таком же расстоянии за зеркалом: 2·{d} = {ans} см.'
        wrong = [W(d), W(Fr(d, 2)), W(4 * d)]
    elif kind == 'move':
        d = pick(rng, [2, 3, 4, 5, 6])
        s = pick(rng, [x for x in (1, 2, 3) if x < d])
        p = {'kind': kind, 's': s}
        ans = _solve_mirror(p)
        q = (f'На шахматной доске вертикально стоит плоское зеркало вдоль одной из линий доски; фигура стоит на расстоянии {d} клеток от зеркала. Фигуру передвинули на {s} клетк{"у" if s == 1 else "и"} ближе к зеркалу. '
             f'На сколько клеток уменьшилось расстояние между фигурой и её изображением?' + ans_line('клеток'))
        e = f'Расстояние фигура — изображение 2d; уменьшилось на 2·{s} = {ans}.'
        wrong = [W(s), W(2 * (d - s)), W(d - s)]
    elif kind == 'speed':
        v = pick(rng, [Fr(1, 2), 1, Fr(3, 2), 2, 3, Fr(4, 5), Fr(6, 5), Fr(5, 2)])
        frame = pick(rng, ['obj', 'mirror'])
        p = {'kind': kind, 'v': str(v), 'frame': frame}
        ans = _solve_mirror(p)
        who = pick(rng, ['Человек идёт', 'Мальчик бежит', 'Робот-пылесос едет', 'Кошка идёт', 'Девочка идёт'])
        q = (f'{who} к плоскому зеркалу со скоростью {Q(v)} м/с перпендикулярно его плоскости. '
             + ('С какой скоростью сокращается расстояние между движущимся телом и его изображением?' if frame == 'obj' else 'С какой по модулю скоростью движется изображение относительно зеркала?') + ans_line('м/с'))
        e = f'Изображение движется навстречу со скоростью {Q(v)} м/с относительно зеркала; относительно человека — 2υ. Ответ: {ans} м/с.'
        wrong = [W(v if frame == 'obj' else 2 * v), W(v / 2), W(4 * v)]
    else:
        s = pick(rng, [2, 3, 4, 5, 8, 10, 12, 15, 20, 25, 30, 40])
        p = {'kind': kind, 's': s}
        ans = _solve_mirror(p)
        q = f'{obj[0]} неподвижно стоит перед плоским зеркалом. Зеркало отодвинули от {obj[1]} на {s} см, не поворачивая его. На сколько сантиметров сместилось изображение?' + ans_line('см')
        e = f'Расстояние до изображения 2d: при увеличении d на {s} см изображение смещается на {ans} см.'
        wrong = [W(s), W(4 * s), W(Fr(s, 2))]
    return num_card('ph-ege-13-mirror-image', q, ans, e, p, wrong)


def _solve_lens(p):
    k = p['kind']
    if k == 'f':
        d, F = Fr(p['d']), Fr(p['F'])
        return A(1 / (1 / F - 1 / d))
    if k == 'F':
        d, f = Fr(p['d']), Fr(p['f'])
        return A(1 / (1 / d + 1 / f))
    if k == 'D':
        d, f = Fr(p['d']) / 100, Fr(p['f']) / 100
        return A(1 / d + 1 / f)
    if k == 'size':
        d, F, h = Fr(p['d']), Fr(p['F']), Fr(p['h'])
        f = 1 / (1 / F - 1 / d)
        return A(h * f / d)
    if k == 'Gamma':
        return A(Fr(p['f']) / Fr(p['d']))
    raise ValueError(k)


@proto('ph-ege-13-lens', 'ЕГЭ', 13, 'Формула тонкой линзы: расстояние до изображения, фокусное расстояние, оптическая сила, увеличение',
       invariant='1/F = 1/d + 1/f (действительное изображение в собирающей линзе); D = 1/F; Γ = f/d = H/h',
       varies='прибор (собирающая линза, объектив проектора, лупа-линза на экране, фотоаппарат), что дано и что найти (f, F, D в дптр, размер изображения, увеличение)',
       answer_rule='подстановка в формулу тонкой линзы с согласованными единицами',
       mistakes=['f = d − F', 'D посчитана в см', 'увеличение d/f'],
       solve=_solve_lens, kes=['3.6.7'],
       fidelity=FID(13, answer_format='число (см, дптр)', style=NUM_STYLE, scale='как в банке: F 10–50 см, d 15–100 см, оптическая сила 1–10 дптр', trap='единицы оптической силы'))
def g_lens(rng):
    kind = pick(rng, ['f', 'F', 'D', 'size', 'Gamma'])
    dev = pick(rng, ['тонкой собирающей линзы', 'объектива проектора (тонкая линза)', 'собирающей линзы', 'объектива фотоаппарата (тонкая линза)'])
    F = pick(rng, [5, 10, 12, 15, 20, 24, 25, 30, 40, 50])
    d = pick(rng, [x for x in range(F + 2, 5 * F) if x % 5 == 0 or x % 6 == 0] or [2 * F])
    f = 1 / (Fr(1, F) - Fr(1, d))
    if not ok_dec(f, 1) or f > 400:
        raise Retry
    if kind == 'f':
        p = {'kind': kind, 'd': d, 'F': F}
        ans = _solve_lens(p)
        q = f'Предмет расположен на главной оптической оси {dev} с фокусным расстоянием {F} см на расстоянии {d} см от неё. На каком расстоянии от линзы находится его изображение?' + ans_line('см')
        e = f'1/f = 1/F − 1/d ⇒ f = dF/(d − F) = {ans} см.'
        wrong = [W(d - F), W(Fr(d * F, d + F)), W(d + F)]
    elif kind == 'F':
        p = {'kind': kind, 'd': d, 'f': str(f)}
        ans = _solve_lens(p)
        q = f'Действительное изображение предмета, находящегося на расстоянии {d} см от {dev}, получилось на расстоянии {Q(f)} см от неё. Каково фокусное расстояние линзы?' + ans_line('см')
        e = f'1/F = 1/d + 1/f ⇒ F = df/(d + f) = {ans} см.'
        wrong = [W(d + f), W(abs(d - f)), W(d * f / abs(f - d)) if f != d else W(2 * F)]
    elif kind == 'D':
        if not ok_dec(Fr(100, F)):
            raise Retry
        p = {'kind': kind, 'd': d, 'f': str(f)}
        ans = _solve_lens(p)
        q = f'Предмет находится на расстоянии {d} см от {dev}, его действительное изображение — на расстоянии {Q(f)} см от линзы. Какова оптическая сила линзы?' + ans_line('дптр')
        e = f'D = 1/d + 1/f (в метрах) = {ans} дптр.'
        wrong = [W(Fr(1, d) + 1 / f), W(Fr(1, F)), W(Fr(F, 100))]
    elif kind == 'size':
        h = pick(rng, [1, 2, 3, 4, 5, 6, 10])
        p = {'kind': kind, 'd': d, 'F': F, 'h': h}
        ans = _solve_lens(p)
        q = f'Предмет высотой {h} см стоит перпендикулярно главной оптической оси {dev} с фокусным расстоянием {F} см на расстоянии {d} см от неё. Какова высота изображения?' + ans_line('см')
        e = f'f = dF/(d − F) = {Q(f)} см; H = h·f/d = {ans} см.'
        wrong = [W(h * d / f), W(h * F / d), W(h)]
    else:
        p = {'kind': kind, 'd': d, 'f': str(f)}
        ans = _solve_lens(p)
        q = f'Предмет находится на расстоянии {d} см от {dev}, а его действительное изображение — на расстоянии {Q(f)} см от линзы. Каково линейное увеличение линзы?' + ans_line()
        e = f'Γ = f/d = {Q(f)}/{d} = {ans}.'
        wrong = [W(d / f), W(f - d) if f > d else W(d - f), W(F / Fr(d))]
    return num_card('ph-ege-13-lens', q, ans, e, p, wrong)


# ================================================================= дополнения по банку: направление поля зарядов (№ 11), тепловой баланс (№ 8)

def _field_vec(charges, pt):
    ex = ey = 0.0
    for (x, y), qv in charges:
        dx, dy = pt[0] - x, pt[1] - y
        r3 = (dx * dx + dy * dy) ** 1.5
        ex += qv * dx / r3
        ey += qv * dy / r3
    return ex, ey


def _solve_fdir(p):
    ch = [((c[0], c[1]), c[2]) for c in p['ch']]
    ex, ey = _field_vec(ch, tuple(p['pt']))
    s = p['test']
    ex, ey = ex * s, ey * s
    if abs(ex) > 1e-9 and abs(ey) < 1e-9 * max(1, abs(ex)):
        name = 'вправо' if ex > 0 else 'влево'
    elif abs(ey) > 1e-9 and abs(ex) < 1e-9 * max(1, abs(ey)):
        name = 'вверх' if ey > 0 else 'вниз'
    else:
        raise ValueError('не по оси')
    return next(o['id'] for o in p['opts'] if o['t'] == name)


@proto('ph-ege-11-field-direction', 'ЕГЭ', 11, 'Направление напряжённости поля и кулоновской силы в поле двух точечных зарядов',
       invariant='напряжённость поля точечного заряда направлена от положительного и к отрицательному заряду, E ~ |q|/r²; принцип суперпозиции; F⃗ = qE⃗',
       varies='расположение зарядов (на одной прямой, точка посередине/снаружи, на серединном перпендикуляре), знаки и модули зарядов, что спрашивают (E⃗ или силу на пробный заряд своего знака); '
              'рисунок заменён словесным описанием',
       answer_rule='сложить векторы полей зарядов с учётом расстояний; для отрицательного пробного заряда сила противоположна E⃗',
       mistakes=['поле отрицательного заряда направлено от него', 'не учтено различие расстояний (1/r²)', 'для отрицательного пробного заряда направление не изменено'],
       solve=_solve_fdir, kes=['3.1.2', '3.1.4', '3.1.6'],
       fidelity=FID(11, answer_format='номер направления из списка (в банке ответ записывается словом: вправо, влево, вверх, вниз, к наблюдателю, от наблюдателя)',
                    style='Как в банке: «Куда направлен относительно рисунка (вправо, влево, вверх, вниз, к наблюдателю, от наблюдателя) вектор напряжённости …»; рисунок заменён словами',
                    scale='как в банке: +q и −5q, +Q и −Q, одинаковые заряды', trap='знак пробного заряда; 1/r²',
                    kes='3.1.2, 3.1.4, 3.1.6 (в плане 2027 для № 11 указан 3.1.2; задания на направление встречаются в банке этой линии)'))
def g_fdir(rng):
    cfg = pick(rng, ['mid', 'outside', 'bisector'])
    mags = [Fr(1), Fr(2), Fr(3), Fr(5), Fr(3, 2), Fr(4)]
    q1 = pick(rng, mags) * pick(rng, [1, -1])
    q2 = pick(rng, mags) * pick(rng, [1, -1])
    if cfg == 'bisector':
        q2 = abs(q1) * pick(rng, [1, -1])
    horiz = rng.random() < 0.7
    A_, B_ = ((0, 0), (2, 0)) if horiz else ((0, 0), (0, 2))
    if cfg == 'mid':
        pt = (1, 0) if horiz else (0, 1)
        where = 'находится посередине отрезка AB'
    elif cfg == 'outside':
        pt = (3, 0) if horiz else (0, 3)
        where = 'лежит на прямой AB за точкой B, на расстоянии AB/2 от точки B'
    else:
        pt = (1, 1) if horiz else (-1, 1)
        where = 'лежит на серединном перпендикуляре к отрезку AB на расстоянии AB/2 от его середины, ' + ('выше отрезка' if horiz else 'левее отрезка')
    test = pick(rng, [0, 1, -1])
    o = opts(list(DIRS.values()))

    def qs(v):
        v = Fr(v)
        mag = '' if abs(v) == 1 else Q(abs(v))
        return f'{"+" if v > 0 else "−"}{mag}q'
    lay = f'точка B — на расстоянии AB {"правее" if horiz else "выше"} точки A' if True else ''
    p = {'ch': [[A_[0], A_[1], float(q1)], [B_[0], B_[1], float(q2)]], 'pt': list(pt), 'test': test if test else 1, 'opts': o}
    try:
        ans = _solve_fdir(p)
    except ValueError:
        raise Retry
    ex, ey = _field_vec([((A_[0], A_[1]), float(q1)), ((B_[0], B_[1]), float(q2))], pt)
    if abs(ex) < 1e-9 and abs(ey) < 1e-9:
        raise Retry
    ask = ('вектор напряжённости электростатического поля в точке C' if test == 0 else
           f'кулоновская сила, действующая на {"положительный" if test > 0 else "отрицательный"} точечный заряд, помещённый в точку C')
    q = (f'Неподвижные точечные заряды {qs(q1)} и {qs(q2)} (q > 0) закреплены в точках A и B соответственно; {lay}. Точка C {where}. '
         f'Как направлен{"а" if test else ""} относительно рисунка {ask}?')
    e = f'Складываем поля зарядов с учётом знаков и расстояний (E ~ |q|/r²){"; для отрицательного заряда сила противоположна E⃗" if test < 0 else ""}: {o[int(ans) - 1]["t"]}.'
    return pcard('ph-ege-11-field-direction', q, ans, e, k='one', o=o, p=p)


def _solve_balance(p):
    k = p['kind']
    if k == 'mix':
        m1, t1, m2, t2 = (Fr(p[x]) for x in ('m1', 't1', 'm2', 't2'))
        return A((m1 * t1 + m2 * t2) / (m1 + m2))
    if k == 'body':
        cb, mb, tb, mw, tw = Fr(p['cb']), Fr(p['mb']), Fr(p['tb']), Fr(p['mw']), Fr(p['tw'])
        return A((cb * mb * tb + 4200 * mw * tw) / (cb * mb + 4200 * mw))
    if k == 'ice':
        return A(4200 * Fr(p['mw']) * Fr(p['tw']) / 330000 * 1000)
    raise ValueError(k)


@proto('ph-ege-08-heat-balance', 'ЕГЭ', 8, 'Уравнение теплового баланса: смешивание, тело в воде, таяние льда',
       invariant='в теплоизолированной системе Qотд = Qпол: cm₁(t₁ − θ) = cm₂(θ − t₂); λmльда = cmводы(t − 0)',
       varies='сюжет (смешивание воды в ванне/кастрюле, горячая деталь в воде, лёд в воде до установления 0 °С), массы, температуры, что найти',
       answer_rule='составить уравнение теплового баланса и решить относительно неизвестной',
       mistakes=['температура смеси — среднее арифметическое при разных массах', 'не учтена теплота плавления'],
       solve=_solve_balance, kes=['2.2.4', '2.2.5', '2.2.11'],
       fidelity=FID(8, answer_format='число (°С, г)', style=NUM_STYLE + '; c, λ — из справочных данных КИМ', scale='как в банке: калориметр с 200–500 г воды, лёд при 0 °С',
                    trap='массы разные — среднее взвешенное', kes='2.2.4, 2.2.5, 2.2.11 (в плане 2027 для № 8 не указан 2.2.11; задания встречаются в банке этой линии)'))
def g_balance(rng):
    kind = pick(rng, ['mix', 'body', 'ice'])
    if kind == 'mix':
        m1, m2 = rng.sample([Fr(1, 10), Fr(1, 5), Fr(1, 2), 1, 2, 3, 5, 10, 20, 30], 2)
        t1, t2 = rng.sample([10, 15, 20, 30, 40, 50, 60, 70, 80, 90], 2)
        p = {'kind': kind, 'm1': str(m1), 't1': t1, 'm2': str(m2), 't2': t2}
        ans = _solve_balance(p)
        where = pick(rng, ['В ванну', 'В кастрюлю', 'В теплоизолированный сосуд', 'В калориметр'])
        f = lambda m: f'{Q(m * 1000)} г' if m < 1 else f'{Q(m)} кг'
        where = where.replace('В ванну', 'ванне').replace('В кастрюлю', 'кастрюле').replace('В теплоизолированный сосуд', 'теплоизолированном сосуде').replace('В калориметр', 'калориметре')
        q = f'Смешали {f(m1)} воды, имевшей температуру {t1} °С, и {f(m2)} воды с температурой {t2} °С (смешивание происходит в {where}). Определите температуру смеси после установления теплового равновесия. Теплообменом с окружающей средой и сосудом пренебречь.' + ans_line('°С')
        e = f'cm₁(θ − t₁) + cm₂(θ − t₂) = 0 ⇒ θ = (m₁t₁ + m₂t₂)/(m₁ + m₂) = {ans} °С.'
        wrong = [W(Fr(t1 + t2, 2)), W((m1 * t2 + m2 * t1) / (m1 + m2)), W(abs(t1 - t2))]
    elif kind == 'body':
        mat, cb = pick(rng, [('алюминиевую', 900), ('медную', 380), ('железную', 460), ('свинцовую', 130), ('чугунную', 500)])
        mb = pick(rng, [Fr(1, 10), Fr(1, 5), Fr(1, 2), 1])
        mw = pick(rng, [Fr(1, 10), Fr(1, 5), Fr(1, 4), Fr(1, 2), 1])
        tb = pick(rng, [80, 100, 120, 150, 200])
        tw = pick(rng, [10, 15, 20, 25])
        p = {'kind': kind, 'cb': cb, 'mb': str(mb), 'tb': tb, 'mw': str(mw), 'tw': tw}
        ans = _solve_balance(p)
        q = (f'Нагретую до {tb} °С {mat} деталь массой {Q(mb * 1000)} г опустили в {Q(mw * 1000)} г воды при температуре {tw} °С. Какая температура установится? '
             f'Теплообменом с сосудом и окружающей средой пренебречь, вода не кипит.' + ans_line('°С'))
        e = f'c₁m₁(t₁ − θ) = c₂m₂(θ − t₂) ⇒ θ = {ans} °С.'
        wrong = [W(Fr(tb + tw, 2)), W((mb * tb + mw * tw) / (mb + mw)), W(tw)]
    else:
        mw = pick(rng, [Fr(1, 10), Fr(1, 5), Fr(1, 4), Fr(1, 2), 1, Fr(11, 20), Fr(11, 10)])
        tw = pick(rng, [10, 11, 20, 22, 25, 30, 33, 40, 44, 55])
        p = {'kind': kind, 'mw': str(mw), 'tw': tw}
        ans = _solve_balance(p)
        what = pick(rng, ['мелко колотый лёд', 'ледяную крошку', 'кубики льда'])
        q = (f'В теплоизолированный сосуд с {Q(mw * 1000)} г воды, имеющей температуру {tw} °С, понемногу добавляют {what} при 0 °С, пока лёд не перестанёт плавиться. '
             f'Сколько граммов льда расплавилось? Теплоёмкостью сосуда пренебречь.' + ans_line('г'))
        e = f'λmл = cmв(t − 0) ⇒ mл = 4200·{Q(mw)}·{tw}/(3,3·10⁵) кг = {ans} г.'
        wrong = [W(Fr(2100) * mw * tw / 330000 * 1000), W(Fr(4200) * mw * tw / 2300000 * 1000), W(mw * 1000)]
    return num_card('ph-ege-08-heat-balance', q, ans, e, p, wrong)
